  3, 70, 31,
  80.24, 'http://oss.sxakgs.com/en/001JK2K01bRFsR7/cover.webp',
  'http://oss.sxakgs.com/en/001JK2K01bRFsR7/video.mp4', 'http://oss.sxakgs.com/en/001JK2K01bRFsR7/audio.mp3',
  'http://oss.sxakgs.com/en/001JK2K01bRFsR7/cover.webp', 'https://www.youtube.com/watch?v=E3y5L4WM2H8',
  (SELECT id FROM authors WHERE name = 'Andrew Alexander' AND accent = '美国' LIMIT 1),
