INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 26.04, 32.64, 'and my French is still absolutely horrible but I can understand a lot more than last time.', '我的法语仍然非常糟糕，但我现在懂得比上次更多了。', '/ænd maɪ fɹɛntʃ ɪz stɪl æbsəluːtli hɔːɹɪbəl bʌt aɪ kæn ʌndɚstænd ɐ lɑːt mɔːɹ ðɐn læst taɪm./', '<span>and</span><span>my</span><span tid="5354">French</span><span>is</span><span tid="5356">still</span><span tid="5357" class="highlight highlight-a">absolutely</span><span tid="5358" class="highlight highlight-a">horrible</span><span>but</span><span>I</span><span>can</span><span tid="5362">understand</span><span>a</span><span tid="5364">lot</span><span>more</span><span tid="5366">than</span><span tid="5367" class="highlight highlight-a">last</span><span tid="5368">time.</span>'
