INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 20.039, 23.371, 'Thankfully, I know a place I can get free water. Lay down, Peachy.', '还好我知道有个地方可以免费打水。躺下，Peachy。', '/θæŋkfəli, aɪ noʊ ɐ pleɪs aɪ kæn ɡɛt fɹiː wɔːɾɚ. leɪ daʊn, piːki./', '<span tid="7242" class="highlight highlight-a">Thankfully,</span><span>I</span><span>know</span><span>a</span><span tid="7246">place</span><span>I</span><span>can</span><span>get</span><span tid="7250">free</span><span tid="7251">water.</span><span pid="875" class="highlight highlight-d">Lay down,</span><span tid="7254">Peachy.</span>'
