INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 45.48, 49.799, 'I''m gonna get attack. I didn''t realize I had you guys sit/sitting on the dumping station.', '感觉那只狗要咬我。我都没注意到我把你们放在排污站上。', '/aɪm ɡənə ɡɛt ɐtæk. aɪ dɪdnt ɹiːəlaɪz aɪ hæd juː ɡaɪz sɪt slæʃ sɪɾɪŋ ɔnðə dʌmpɪŋ steɪʃən./', '<span>I''m</span><span tid="7293">gonna</span><span>get</span><span tid="7295">attack.</span><span>I</span><span>didn''t</span><span tid="7298" class="highlight highlight-a">realize</span><span>I</span><span>had</span><span>you</span><span tid="7302">guys</span><span tid="7303">sit/sitting</span><span>on</span><span>the</span><span tid="7306">dumping</span><span tid="7307">station.</span>'
