INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 54.783, 56.12, 'And like that, now we''re good to go to camp.', '就这样，我们可以出发去露营了。', '/ænd laɪk ðæt, naʊ wɪɹ ɡʊd tə ɡoʊ tə kæmp./', '<span>And</span><span>like</span><span>that,</span><span tid="7321">now</span><span>we''re</span><span>good</span><span>to</span><span>go</span><span>to</span><span tid="7327" class="highlight highlight-a">camp.</span>'
