INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 56.599, 60.023, 'Found this cool spot right by the river. Let''s go check it out.', '我在河边找到一个很棒的地方。我们去看看吧。', '/faʊnd ðɪs kuːl spɑːt ɹaɪt baɪ ðə ɹɪvɚ. lɛts ɡoʊ tʃɛk ɪɾ aʊt./', '<span tid="7328">Found</span><span>this</span><span tid="7330" class="highlight highlight-a">cool</span><span tid="7331" class="highlight highlight-a">spot</span><span tid="7332" class="highlight highlight-a">right</span><span pid="878" class="highlight highlight-c">by the river.</span><span>Let''s</span><span>go</span><span pid="879" class="highlight highlight-d">check it out.</span>'
