INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 60.023, 61.906, 'Got some windy/winding roads to go down though.', '不过得先走几段弯曲的路。', '/ɡɑːt sʌm wɪndi slæʃ waɪndɪŋ ɹoʊdz tə ɡoʊ daʊn ðoʊ./', '<span>Got</span><span>some</span><span tid="7343">windy/winding</span><span tid="7344">roads</span><span>to</span><span pid="880" class="highlight highlight-d">go down</span><span tid="7348">though.</span>'
