INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 63.799, 65.805, 'Road''s getting a little rough right here.', '这段路有点难走了。', '/ɹoʊdz ɡɛɾɪŋ ɐ lɪɾəl ɹʌf ɹaɪt hɪɹ./', '<span tid="7349">Road''s</span><span>getting</span><span>a</span><span tid="7352">little</span><span tid="7353" class="highlight highlight-a">rough</span><span tid="7354" class="highlight highlight-a">right</span><span>here.</span>'
