INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 71.479, 76.039, 'Okay, we got it. We got it. Online, it looks like a really great campsite.', '小问题，小问题。网上看起来是个非常棒的露营地。', '/oʊkeɪ, wiː ɡɑːt ɪt. wiː ɡɑːt ɪt. ɑːnlaɪn, ɪt lʊks laɪk ɐ ɹiəli ɡɹeɪt kæmpsaɪt./', '<span>Okay,</span><span pid="881" class="highlight highlight-i">we got it.</span><span pid="881" class="highlight highlight-i">We got it.</span><span tid="7363">Online,</span><span>it</span><span tid="7365" class="highlight highlight-a">looks</span><span>like</span><span>a</span><span tid="7368">really</span><span tid="7369">great</span><span tid="7370" class="highlight highlight-a">campsite.</span>'
