INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 22, 85.48, 88.237, 'Well, first campsite''s already taken, so that''s not a good sign.', '第一个营地已经有人了，这可不是好兆头。', '/wɛl, fɜːst kæmpsaɪtz ɔːlɹɛdi teɪkən, soʊ ðæts nɑːɾə ɡʊd saɪn./', '<span tid="7408">Well,</span><span tid="7409">first</span><span tid="7410" class="highlight highlight-a">campsite''s</span><span tid="7411">already</span><span tid="7412">taken,</span><span>so</span><span>that''s</span><span>not</span><span>a</span><span>good</span><span tid="7418">sign.</span>'
