INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 23, 88.237, 90.04, 'These red rocks are just gorgeous.', '这些红色的石头太好看了。', '/ðiːz ɹɛd ɹɑːks ɑːɹ dʒʌst ɡɔːɹdʒəs./', '<span>These</span><span tid="7420">red</span><span tid="7421">rocks</span><span>are</span><span>just</span><span tid="7424" class="highlight highlight-a">gorgeous.</span>'
