INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 91.88, 94.234, 'Well, I can see the river. It looks beautiful.', '我已经能看到那条河了，看起来还不错。', '/wɛl, aɪ kæn siː ðə ɹɪvɚ. ɪt lʊks bjuːɾifəl./', '<span tid="7425">Well,</span><span>I</span><span>can</span><span tid="7428">see</span><span>the</span><span tid="7430">river.</span><span>It</span><span tid="7432" class="highlight highlight-a">looks</span><span tid="7433">beautiful.</span>'
