INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 25, 94.234, 96.383, 'Just gotta figure out how to get down there.', '只需要想办法下去。', '/dʒʌst ɡɑːɾə fɪɡjɚɹ aʊt haʊ tə ɡɛt daʊn ðɛɹ./', '<span>Just</span><span pid="888" class="highlight highlight-i">gotta</span><span pid="884" class="highlight highlight-d">figure out</span><span>how</span><span>to</span><span>get</span><span tid="7441">down</span><span>there.</span>'
