INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 74.24, 76.237, 'It''s hard for them to eat, go to the bathroom.', '她戴着很难吃东西、上厕所。', '/ɪts hɑːɹd fɔːɹ ðɛm tʊ iːt, ɡoʊ tə ðə bæθɹuːm./', '<span>It''s</span><span tid="6210">hard</span><span>for</span><span>them</span><span>to</span><span tid="6214">eat,</span><span>go</span><span>to</span><span>the</span><span tid="6218" class="highlight highlight-a">bathroom.</span>'
