INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 30, 109.5, 112.62, 'I also learned that cats are very, very simple creatures.', '我还发现猫其实是非常非常简单的动物。', '/aɪ ɔːlsoʊ lɜːnd ðæt kæts ɑːɹ vɛɹi, vɛɹi sɪmpəl kɹiːtʃɚz./', '<span>I</span><span>also</span><span tid="6364">learned</span><span>that</span><span tid="6366">cats</span><span>are</span><span>very,</span><span>very</span><span tid="6370">simple</span><span tid="6371" class="highlight highlight-a">creatures.</span>'
