INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 38, 138.34, 141.2, 'So it does take time for them to get assimilated to some things.', '所以猫适应一些东西确实是需要时间的。', '/soʊ ɪt dʌz teɪk taɪm fɔːɹ ðɛm tə ɡɛt ɐsɪmᵻleɪɾᵻd tə sʌm θɪŋz./', '<span>So</span><span>it</span><span>does</span><span tid="6471">take</span><span tid="6472">time</span><span>for</span><span>them</span><span>to</span><span>get</span><span tid="6477" class="highlight highlight-a">assimilated</span><span>to</span><span>some</span><span>things.</span>'
