INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 40, 149.1, 151.32, 'I actually get a lot of PR, which I''m so grateful for.', '我其实收到了很多赞助包裹，真的非常感激。', '/aɪ æktʃuːəli ɡɛt ɐ lɑːt ʌv piːɑːɹ, wɪtʃ aɪm soʊ ɡɹeɪtfəl fɔːɹ./', '<span>I</span><span tid="6511">actually</span><span>get</span><span>a</span><span tid="6514">lot</span><span>of</span><span tid="6516" class="highlight highlight-a">PR,</span><span>which</span><span>I''m</span><span>so</span><span tid="6520" class="highlight highlight-a">grateful</span><span>for.</span>'
