INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 43, 156.84, 161.46, 'But she has an attachment to this one box and I can''t find it in my heart to throw it away.', '但她对其中一个箱子特别有感情，我实在下不了决心把它扔掉。', '/bʌt ʃiː hɐz ɐn ɐtætʃmənt tə ðɪswʌn bɑːks ænd aɪ kænt faɪnd ɪɾ ɪn maɪ hɑːɹt tə θɹoʊ ɪɾ ɐweɪ./', '<span>But</span><span>she</span><span pid="622" class="highlight highlight-h">has an attachment to</span><span>this</span><span>one</span><span tid="6551">box</span><span>and</span><span>I</span><span pid="623" class="highlight highlight-l">can''t find it in my heart to</span><span pid="624" class="highlight highlight-d">throw it away.</span>'
