INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 21.54, 25.68, 'I always like try to just find one person that I really like that I can just go to.', '我总是会努力找一个我很喜欢、可以一直找她修眉的人。', '/aɪ ɔːlweɪz laɪk tɹaɪ tə dʒʌst faɪnd wʌn pɜːsən ðæt aɪ ɹiəli laɪk ðæt aɪ kæn dʒʌst ɡoʊ tuː./', '<span>I</span><span tid="10702">always</span><span>like</span><span tid="10704">try</span><span>to</span><span>just</span><span tid="10707">find</span><span>one</span><span tid="10709">person</span><span>that</span><span>I</span><span tid="10712">really</span><span>like</span><span>that</span><span>I</span><span>can</span><span>just</span><span>go</span><span>to.</span>'
