INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 34.88, 37.84, 'It doesn''t really matter to me as long as it looks good which she always does here.', '对我来说无所谓，只要效果好就行——而她每次都做得很好。', '/ɪt dʌzənt ɹiəli mæɾɚ tə miː æz lɔŋ æz ɪt lʊks ɡʊd wɪtʃ ʃi ɔːlweɪz dʌz hɪɹ./', '<span pid="1804" class="highlight highlight-l">It doesn''t really matter to me</span><span>as</span><span tid="10764">long</span><span>as</span><span>she</span><span tid="10767" class="highlight highlight-a">looks</span><span>good</span><span>which</span><span>it</span><span tid="10771">always</span><span>does</span><span>here.</span>'
