INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 37.9, 42.18, 'And then she also convinced me to start doing a brow tint when I come which I really like.', '她还说服我每次来都做个眉毛染色，我挺喜欢的。', '/ænd ðɛn ʃiː ɔːlsoʊ kənvɪnst miː tə stɑːɹt duːɪŋ ɐ bɹaʊ tɪnt wɛn aɪ kʌm wɪtʃ aɪ ɹiəli laɪk./', '<span>And</span><span>then</span><span>she</span><span>also</span><span tid="10778" class="highlight highlight-a">convinced</span><span>me</span><span>to</span><span tid="10781">start</span><span>doing</span><span>a</span><span tid="10784" class="highlight highlight-a">brow</span><span tid="10785" class="highlight highlight-a">tint</span><span>when</span><span>I</span><span tid="10788">come</span><span>which</span><span>I</span><span tid="10791">really</span><span>like.</span>'
