INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 10, 44.53, 46.24, 'If you''re thinking about going into that profession.', '如果你考虑进入这个行业的话。', '/ɪf jʊɹ θɪŋkɪŋ ɐbaʊt ɡoʊɪŋ ɪntʊ ðæt pɹəfɛʃən./', '<span>If</span><span>you''re</span><span>thinking</span><span>about</span><span>going</span><span tid="8557" class="highlight highlight-a">into</span><span>that</span><span tid="8559" class="highlight highlight-a">profession.</span>'
