INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 54.96, 59.42, 'and my salary is $60,700.', '我的年薪是60700美元。', '/ænd maɪ sælɚɹi ɪz dɑːlɚ sɪksti,sɛvənhʌndɹɪd./', '<span>and</span><span>my</span><span tid="8593" class="highlight highlight-a">salary</span><span>is</span><span>$60,700.</span>'
