INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 59.42, 61.76, 'Now, of course there''s like taxes and stuff.', '当然，这其中还要扣税之类的。', '/naʊ, ʌv kɔːɹs ðɛɹz laɪk tæksᵻz ænd stʌf./', '<span tid="8596">Now,</span><span pid="2569" class="highlight highlight-c">of course</span><span>there''s</span><span>like</span><span tid="8601">taxes</span><span>and</span><span tid="8603" class="highlight highlight-a">stuff.</span>'
