INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 61.76, 71.26, 'So what my paycheck was last night was actually $1,954.94.', '所以我昨晚实际拿到的工资是1954.94美元。', '/soʊ wʌt maɪ peɪtʃɛk wʌz læst naɪt wʌz æktʃuːəli dɑːlɚ wʌn,naɪnhʌndɹɪd fɪfti fɔːɹ.naɪnti fɔːɹ./', '<span>So</span><span>what</span><span>my</span><span tid="8607" class="highlight highlight-a">paycheck</span><span>was</span><span tid="8609" class="highlight highlight-a">last</span><span tid="8610">night</span><span>was</span><span tid="8612">actually</span><span>$1,954.94.</span>'
FROM episodes e WHERE e.video_id = '017nWvA8emQs16p';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
