INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 73.1, 75.76, 'Technically we did get paid two weeks ago.', '严格来说我们在两周前也发了一次薪水。', '/tɛknɪkli wiː dɪd ɡɛt peɪd tuː wiːks ɐɡoʊ./', '<span tid="8620" class="highlight highlight-a">Technically</span><span>we</span><span>did</span><span pid="2571" class="highlight highlight-c">get paid</span><span>two</span><span tid="8626">weeks</span><span tid="8627">ago.</span>'
