INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 101.98, 106.44, 'And it''s kind of hard to do surgery hours because my hours have varied so much.', '不过手术的排班比较难计算，因为我的工时变动很大。', '/ænd ɪts kaɪnd ʌv hɑːɹd tə duː sɜːdʒɚɹi aʊɚz bɪkʌz maɪ aʊɚz hæv vɛɹid soʊ mʌtʃ./', '<span>And</span><span>it''s</span><span tid="8718">kind</span><span>of</span><span tid="8720">hard</span><span>to</span><span>do</span><span tid="8723" class="highlight highlight-a">surgery</span><span tid="8724">hours</span><span>because</span><span>my</span><span tid="8727">hours</span><span>have</span><span tid="8729" class="highlight highlight-a">varied</span><span>so</span><span tid="8731">much.</span>'
