INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.46, 2.98, 'we are finally at cruising altitude.', '我们终于达到巡航高度了。', '/wiː ɑːɹ faɪnəli æt kɹuːzɪŋ æltɪtuːd./', '<span>we</span><span>are</span><span tid="13783">finally</span><span>at</span><span tid="13785" class="highlight highlight-a">cruising</span><span tid="13786">altitude.</span>'
