INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 52.16, 58.58, 'I love when we get two beds because I just put my clothes on one and I sleep on the other.', '我喜欢住到有两张床的房间，这样我就可以把衣服放在一张床上，另一张用来睡觉。', '/aɪ lʌv wɛn wiː ɡɛt tuː bɛdz bɪkʌz aɪ dʒʌst pʊt maɪ kloʊðz ɔn wʌn ænd aɪ sliːp ɔnðɪ ʌðɚ./', '<span>I</span><span tid="13574">love</span><span>when</span><span>we</span><span>get</span><span>two</span><span tid="13579" class="highlight highlight-a">beds</span><span>because</span><span>I</span><span>just</span><span tid="13583">put</span><span>my</span><span tid="13585">clothes</span><span>on</span><span>one</span><span>and</span><span>I</span><span tid="13590">sleep</span><span>on</span><span>the</span><span tid="13593">other.</span>'
