INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 59.1, 72.26, 'A little sofa, closet, desk, and then the bathroom is really cool with this cute little bookshelf.', '还有个小沙发、衣柜、书桌，然后浴室也很好，有一个可爱的迷你书架。', '/ɐ lɪɾəl soʊfə, klɑːzɪt, dɛsk, ænd ðɛn ðə bæθɹuːm ɪz ɹiəli kuːl wɪð ðɪs kjuːt lɪɾəl bʊkʃɛlf./', '<span>A</span><span tid="13595">little</span><span tid="13596" class="highlight highlight-a">sofa,</span><span tid="13597" class="highlight highlight-a">closet,</span><span tid="13598">desk,</span><span>and</span><span>then</span><span>the</span><span tid="13602" class="highlight highlight-a">bathroom</span><span>is</span><span tid="13604">really</span><span tid="13605" class="highlight highlight-a">cool</span><span>with</span><span>this</span><span tid="13608" class="highlight highlight-a">cute</span><span tid="13609">little</span><span tid="13610" class="highlight highlight-a">bookshelf.</span>'
