INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 72.26, 74.22, 'I cannot wait to go to bed.', '好想赶紧睡觉啊。', '/aɪ kænɑːt weɪt tə ɡoʊ tə bɛd./', '<span>I</span><span>cannot</span><span tid="13613">wait</span><span>to</span><span pid="61" class="highlight highlight-c">go to bed.</span>'
FROM episodes e WHERE e.video_id = '023laD90XVkPU4i';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 74.22, 80.42, 'I''m just gonna change out, clean up really quick, and then knock out.', '我就换个衣服，快速洗漱一下，然后倒头就睡。', '/aɪm dʒʌst ɡənə tʃeɪndʒ aʊt, kliːn ʌp ɹiəli kwɪk, ænd ðɛn nɑːk aʊt./', '<span>I''m</span><span>just</span><span tid="13620">gonna</span><span pid="62" class="highlight highlight-d">change out,</span><span pid="63" class="highlight highlight-d">clean up</span><span tid="13625">really</span><span tid="13626">quick,</span><span>and</span><span>then</span><span pid="64" class="highlight highlight-d">knock out.</span>'
