INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 80.42, 82.34, 'I also don''t really have that much time in Tampa.', '我在坦帕其实也没有太多时间。', '/aɪ ɔːlsoʊ doʊnt ɹiəli hæv ðæt mʌtʃ taɪm ɪn tæmpə./', '<span>I</span><span>also</span><span>don''t</span><span tid="13634">really</span><span>have</span><span>that</span><span tid="13637">much</span><span tid="13638">time</span><span>in</span><span tid="13640">Tampa.</span>'
