INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 82.34, 88.02, 'I''m kind of sad because originally we were supposed to arrive at around 10.', '我有点难过，因为本来我们应该大约在十点就到的。', '/aɪm kaɪnd ʌv sæd bɪkʌz ɚɹɪdʒɪnəli wiː wɜː səpoʊzd tʊ ɚɹaɪv æɾ ɚɹaʊnd tɛn./', '<span>I''m</span><span tid="13642">kind</span><span>of</span><span tid="13644">sad</span><span>because</span><span tid="13646" class="highlight highlight-a">originally</span><span>we</span><span pid="54" class="highlight highlight-c">were supposed to</span><span pid="66" class="highlight highlight-c">arrive at</span><span tid="13653">around</span><span>10.</span>'
