INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 88.02, 92.92, 'I had a longer layover and I wanted to wake up early, get a workout in and what now.', '我原本有更长的停留时间，打算早点起床、锻炼一下之类的。', '/aɪ hæd ɐ lɔŋɡɚ leɪoʊvɚ ænd aɪ wɔntᵻd tə weɪk ʌp ɜːli, ɡɛt ɐ wɜːkaʊt ɪn ænd wʌt naʊ./', '<span>I</span><span>had</span><span>a</span><span tid="13658">longer</span><span tid="13659" class="highlight highlight-a">layover</span><span>and</span><span>I</span><span>wanted</span><span>to</span><span pid="67" class="highlight highlight-d">wake up early,</span><span pid="73" class="highlight highlight-d">get a workout in</span><span>and</span><span>what</span><span tid="13673">now.</span>'
