INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 107.08, 110.64, 'I want to sleep in, wake up, shower, get ready.', '我想多睡一会儿，起床、洗澡、准备一下。', '/aɪ wɔnt tə sliːp ɪn, weɪk ʌp, ʃaʊɚ, ɡɛt ɹɛdi./', '<span>I</span><span>want</span><span>to</span><span pid="69" class="highlight highlight-d">sleep in,</span><span tid="13725">wake</span><span>up,</span><span tid="13727" class="highlight highlight-a">shower,</span><span>get</span><span tid="13729">ready.</span>'
