INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 22, 116.92, 122.18, 'It''s what happens in this industry, so I''m glad we made it into Florida safely.', '这在这个行业是常有的事，所以我很庆幸我们平安抵达佛罗里达。', '/ɪts wʌt hæpənz ɪn ðɪs ɪndʌstɹi, soʊ aɪm ɡlæd wiː meɪd ɪɾ ɪntʊ flɔːɹɪdə seɪfli./', '<span>It''s</span><span>what</span><span tid="13752">happens</span><span>in</span><span>this</span><span tid="13755" class="highlight highlight-a">industry,</span><span>so</span><span>I''m</span><span tid="13758">glad</span><span>we</span><span pid="72" class="highlight highlight-i">made it into Florida</span><span tid="13764">safely.</span>'
