INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 10, 40.8, 43.54, 'when I went on the run and when I was working out.', '但今天我去跑步、锻炼的时候，', '/wɛn aɪ wɛnt ɔnðə ɹʌn ænd wɛn aɪ wʌz wɜːkɪŋ aʊt./', '<span>when</span><span>I</span><span pid="772" class="highlight highlight-d">went on</span><span>the</span><span tid="13138">run</span><span>and</span><span>when</span><span>I</span><span>was</span><span pid="773" class="highlight highlight-d">working out.</span>'
