INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 43.54, 49.06, 'my clarity and my energy and my attentiveness and even when i''m doing all those things.', '我感觉我的思绪、精力、注意力，甚至在我运动的时候。', '/maɪ klæɹᵻɾi ænd maɪ ɛnɚdʒi ænd maɪ ɐtɛntɪvnəs ænd iːvən wɛn aɪm duːɪŋ ɔːl ðoʊz θɪŋz./', '<span>my</span><span tid="13146" class="highlight highlight-a">clarity</span><span>and</span><span>my</span><span tid="13149" class="highlight highlight-a">energy</span><span>and</span><span>my</span><span tid="13152" class="highlight highlight-a">attentiveness</span><span>and</span><span tid="13154">even</span><span>when</span><span>i''m</span><span>doing</span><span>all</span><span>those</span><span>things.</span>'
