INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 97.3, 106.58, 'I think it is extremely extremely important for everyone no matter who you are to just take time to be in silence and to think and to reflect.', '我真的觉得，每个人，不管你是谁，都特别特别需要抽时间静下来，去思考、去自省。', '/aɪ θɪŋk ɪɾ ɪz ɛkstɹiːmli ɛkstɹiːmli ɪmpɔːɹtənt fɔːɹ ɛvɹɪwʌn noʊ mæɾɚ huː juː ɑːɹ tə dʒʌst teɪk taɪm təbi ɪn saɪləns ænd tə θɪŋk ænd tə ɹᵻflɛkt./', '<span>I</span><span>think</span><span>it</span><span>is</span><span tid="13313" class="highlight highlight-a">extremely</span><span tid="13314" class="highlight highlight-a">extremely</span><span tid="13315">important</span><span>for</span><span tid="13317">everyone</span><span>no</span><span tid="13319">matter</span><span>who</span><span>you</span><span>are</span><span>to</span><span>just</span><span pid="780" class="highlight highlight-c">take time to</span><span>be</span><span>in</span><span tid="13330" class="highlight highlight-a">silence</span><span>and</span><span>to</span><span>think</span><span>and</span><span>to</span><span tid="13336" class="highlight highlight-a">reflect.</span>'
