INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 26, 108.8, 114.98, 'that''s why I''m really excited for summer because I get to spend time in what looks like paradise right now.', '所以我特别期待夏天的到来，因为那时候我就可以待在这种像天堂一样的地方。', '/ðæts waɪ aɪm ɹiəli ɛksaɪɾᵻd fɔːɹ sʌmɚ bɪkʌz aɪ ɡɛt tə spɛnd taɪm ɪn wʌt lʊks laɪk pæɹədaɪs ɹaɪt naʊ./', '<span>that''s</span><span>why</span><span>I''m</span><span tid="13347">really</span><span tid="13348">excited</span><span>for</span><span tid="13350">summer</span><span>because</span><span>I</span><span>get</span><span>to</span><span tid="13355">spend</span><span tid="13356">time</span><span>in</span><span>what</span><span tid="13359" class="highlight highlight-a">looks</span><span>like</span><span tid="13361">paradise</span><span pid="765" class="highlight highlight-c">right now.</span>'
