INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 49.56, 54.78, 'You know sometimes you just set goals for the year and you just don''t get to it.', '有时候你给自己定了一些年度目标，结果就是没做到。', '/juː noʊ sʌmtaɪmz juː dʒʌst sɛt ɡoʊlz fɚðə jɪɹ ænd juː dʒʌst doʊnt ɡɛt tʊ ɪt./', '<span>You</span><span>know</span><span tid="12826">sometimes</span><span>you</span><span>just</span><span tid="12829" class="highlight highlight-a">set</span><span tid="12830">goals</span><span>for</span><span>the</span><span tid="12833">year</span><span>and</span><span>you</span><span>just</span><span>don''t</span><span pid="639" class="highlight highlight-c">get to</span><span>it.</span>'
