INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 99.34, 106.62, 'even though I cook a lot of meals at home like most of my meals are under 30 minutes because I do not have a lot of time and busy.', '虽然我在家做很多饭，但大多数都是30分钟以内搞定的，因为我没太多时间，而且很忙。', '/iːvən ðoʊ aɪ kʊk ɐ lɑːt ʌv miːlz æt hoʊm laɪk moʊst əv maɪ miːlz ɑːɹ ʌndɚ θɜːɾi mɪnɪts bɪkʌz aɪ duːnɑːt hæv ɐ lɑːt ʌv taɪm ænd bɪzi./', '<span pid="645" class="highlight highlight-f">even though</span><span>I</span><span tid="12978" class="highlight highlight-a">cook</span><span>a</span><span tid="12980">lot</span><span>of</span><span tid="12982">meals</span><span>at</span><span tid="12984">home</span><span>like</span><span tid="12986">most</span><span>of</span><span>my</span><span tid="12989">meals</span><span>are</span><span tid="12991">under</span><span>30</span><span tid="12993">minutes</span><span>because</span><span>I</span><span>do</span><span>not</span><span>have</span><span>a</span><span tid="13000">lot</span><span>of</span><span tid="13002">time</span><span>and</span><span tid="13004" class="highlight highlight-a">busy.</span>'
