INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 7.6, 'Whilst I was away in LA I sent this car to the garage to get fixed and now she runs like a dream.', '我在洛杉矶的时候，把这辆车送去修了，现在她开起来顺滑得像做梦一样。', '/waɪlst aɪ wʌz ɐweɪ ɪn ɛleɪ aɪ sɛnt ðɪs kɑːɹ tə ðə ɡɚɹɑːʒ tə ɡɛt fɪkst ænd naʊ ʃiː ɹʌnz laɪk ɐ dɹiːm./', '<span tid="12051" class="highlight highlight-a">Whilst</span><span>I</span><span>was</span><span tid="12054">away</span><span>in</span><span tid="12056">LA</span><span>I</span><span tid="12058">sent</span><span>this</span><span tid="12060">car</span><span>to</span><span>the</span><span tid="12063" class="highlight highlight-a">garage</span><span>to</span><span>get</span><span tid="12066">fixed</span><span>and</span><span tid="12068">now</span><span>she</span><span tid="12070">runs</span><span>like</span><span>a</span><span tid="12073">dream.</span>'
FROM episodes e WHERE e.video_id = '026WLbKWc955CsP';
