INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 140.6, 146.54, 'By the way, where that I''m driving right now is all of my old podcast studios because.', '顺便说一下，我现在开的这条路，周围全是我以前录播客的“录音棚”。', '/baɪ ðə weɪ, wɛɹ ðæt aɪm dɹaɪvɪŋ ɹaɪt naʊ ɪz ɔːl ʌv maɪ oʊld pɑːdkæst stuːdɪoʊz bɪkʌz./', '<span pid="1231" class="highlight highlight-f">By the way,</span><span>where</span><span>that</span><span>I''m</span><span tid="12510">driving</span><span pid="1235" class="highlight highlight-c">right now</span><span>is</span><span>all</span><span>of</span><span>my</span><span tid="12517">old</span><span tid="12518" class="highlight highlight-a">podcast</span><span tid="12519" class="highlight highlight-a">studios</span><span>because.</span>'
