INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 36, 154.92, 159.7, 'you can usually find ones with like only a couple of other cars in them like it''s pretty quiet up here.', '通常你能找到那种只有一两辆车的地方，这儿挺安静的。', '/juː kæn juːʒuːəli faɪnd wʌnz wɪð laɪk oʊnli ɐ kʌpəl ʌv ʌðɚ kɑːɹz ɪn ðɛm laɪk ɪts pɹɪɾi kwaɪət ʌp hɪɹ./', '<span>you</span><span>can</span><span tid="12557">usually</span><span tid="12558">find</span><span>ones</span><span>with</span><span>like</span><span tid="12562">only</span><span>a</span><span tid="12564">couple</span><span>of</span><span tid="12566">other</span><span tid="12567">cars</span><span>in</span><span>them</span><span>like</span><span>it''s</span><span tid="12572" class="highlight highlight-a">pretty</span><span tid="12573">quiet</span><span pid="1263" class="highlight highlight-c">up here.</span>'
