INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 19.08, 24.16, 'I recently started working as a doctor in A&E (Accidents and Emergency department).', '我最近开始在急诊科工作，也就是意外与急诊部门。', '/aɪ ɹiːsəntli stɑːɹɾᵻd wɜːkɪŋ æz ɐ dɑːktɚɹ ɪn eɪɐnd iː (æksɪdənts ænd ɪmɜːdʒənsi dᵻpɑːɹtmənt)./', '<span>I</span><span tid="11850">recently</span><span tid="11851">started</span><span tid="11852">working</span><span>as</span><span>a</span><span tid="11855">doctor</span><span>in</span><span tid="11857">A&E</span><span tid="11858">(Accidents</span><span>and</span><span tid="11860" class="highlight highlight-a">Emergency</span><span tid="11861" class="highlight highlight-a">department).</span>'
