INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 2.44, 'I like to read meditations in between my work periods.', '我喜欢在工作间隙读一下《沉思录》。', '/aɪ laɪk tə ɹiːd mɛdɪteɪʃənz ɪn bᵻtwiːn maɪ wɜːk piəɹɪədz./', '<span>I</span><span>like</span><span>to</span><span tid="11482">read</span><span tid="11483" class="highlight highlight-a">meditations</span><span pid="2905" class="highlight highlight-i">in between</span><span>my</span><span tid="11487">work</span><span tid="11488" class="highlight highlight-a">periods.</span>'
