INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 20.24, 22.82, 'I''m excited. This is really refreshing to me.', '我很兴奋，对我来说真的很提神。', '/aɪm ɛksaɪɾᵻd. ðɪs ɪz ɹiəli ɹᵻfɹɛʃɪŋ tə miː./', '<span>I''m</span><span tid="11563">excited.</span><span>This</span><span>is</span><span tid="11566">really</span><span tid="11567" class="highlight highlight-a">refreshing</span><span>to</span><span>me.</span>'
