INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 40.84, 44.56, 'You always wish that you could too, which is idiotic.', '你也总是希望自己也能逃离，其实这很愚蠢。', '/juː ɔːlweɪz wɪʃ ðæt juː kʊd tuː, wɪtʃ ɪz ɪdɪɑːɾɪk./', '<span>You</span><span tid="11602">always</span><span tid="11603">wish</span><span>that</span><span>you</span><span>could</span><span>too,</span><span>which</span><span>is</span><span tid="11610" class="highlight highlight-a">idiotic.</span>'
