INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 47.92, 53.06, 'nowhere you can go is more peaceful, more free of interruptions than your own soul.', '没有哪个地方比你自己的内心更安宁、更不受打扰。', '/noʊwɛɹ juː kæn ɡoʊ ɪz mɔːɹ piːsfəl, mɔːɹ fɹiː ʌv ɪntɚɹʌpʃənz ðɐn jʊɹ oʊn soʊl./', '<span tid="11623" class="highlight highlight-a">nowhere</span><span>you</span><span>can</span><span>go</span><span>is</span><span>more</span><span tid="11629">peaceful,</span><span>more</span><span pid="2916" class="highlight highlight-c">free of interruptions</span><span tid="11634">than</span><span>your</span><span tid="11636" class="highlight highlight-a">own</span><span tid="11637" class="highlight highlight-a">soul.</span>'
