INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 18.86, 24.85, 'um but the hike tomorrow takes uh I think it''s like five to six hours.', '不过明天的徒步大概要五到六个小时。', '/ʌm bʌt ðə haɪk təmɑːɹoʊ teɪks ʌ aɪ θɪŋk ɪts laɪk faɪv tə sɪks aʊɚz./', '<span tid="10943">um</span><span>but</span><span>the</span><span tid="10946" class="highlight highlight-a">hike</span><span tid="10947">tomorrow</span><span tid="10948">takes</span><span>uh</span><span>I</span><span>think</span><span>it''s</span><span>like</span><span>five</span><span>to</span><span>six</span><span tid="10957">hours.</span>'
