INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 46.42, 52.28, 'um it''s nice just to have a complete like reset and just cut off and shut off from the world a bit.', '这种完全的重启、切断联系、从世界抽离的感觉真的很棒。', '/ʌm ɪts naɪs dʒʌst tə hæv ɐ kəmpliːt laɪk ɹᵻsɛt ænd dʒʌst kʌt ɔf ænd ʃʌt ɔf fɹʌmðə wɜːld ɐ bɪt./', '<span tid="11020">um</span><span>it''s</span><span tid="11022">nice</span><span>just</span><span>to</span><span>have</span><span>a</span><span tid="11027">complete</span><span>like</span><span tid="11029" class="highlight highlight-a">reset</span><span>and</span><span>just</span><span pid="2963" class="highlight highlight-d">cut off</span><span>and</span><span pid="2964" class="highlight highlight-d">shut off</span><span>from</span><span>the</span><span tid="11039">world</span><span>a</span><span tid="11041">bit.</span>'
