INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 3.02, 'It''s been a while since I''ve seen you all.', '好久不见，大家。', '/ɪts bɪn ɐ waɪl sɪns aɪv siːn juː ɔːl./', '<span pid="3346" class="highlight highlight-l">It''s been a while since</span><span>I''ve</span><span tid="18363">seen</span><span>you</span><span>all.</span>'
