INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 3.02, 6.8, 'The last we spoke, I was planting my garden.', '上次和你们说话的时候，我正在播种我的小花园。', '/ðə læst wiː spoʊk, aɪ wʌz plæntɪŋ maɪ ɡɑːɹdən./', '<span>The</span><span tid="18367" class="highlight highlight-a">last</span><span>we</span><span tid="18369">spoke,</span><span>I</span><span>was</span><span tid="18372" class="highlight highlight-a">planting</span><span>my</span><span tid="18374" class="highlight highlight-a">garden.</span>'
