INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 48.98, 53.88, 'We can get so wrapped up in the little things', '我们总是容易被那些琐碎的小事牵绊，', '/wiː kæn ɡɛt soʊ ɹæpt ʌp ɪnðə lɪɾəl θɪŋz/', '<span>We</span><span>can</span><span>get</span><span>so</span><span pid="3351" class="highlight highlight-c">wrapped up</span><span>in</span><span>the</span><span tid="18470">little</span><span>things</span>'
