INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 53.88, 57.48, 'our daily worries, the noise of life.', '被日常的烦忧、生活的喧嚣包围。', '/aʊɚ deɪli wʌɹiz, ðə nɔɪz ʌv laɪf./', '<span>our</span><span tid="18473">daily</span><span tid="18474">worries,</span><span>the</span><span tid="18476">noise</span><span>of</span><span tid="18478">life.</span>'
FROM episodes e WHERE e.video_id = '0316umBskWdrx0B';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 57.48, 61.4, 'that we forget time is passing no matter what.', '以至于忘了，时间从不为谁停留。', '/ðæt wiː fɚɡɛt taɪm ɪz pæsɪŋ noʊ mæɾɚ wʌt./', '<span>that</span><span>we</span><span tid="18481">forget</span><span tid="18482">time</span><span>is</span><span tid="18484" class="highlight highlight-a">passing</span><span pid="3352" class="highlight highlight-l">no matter</span><span>what.</span>'
