INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 61.4, 64.86, 'Every day we''re growing older.', '我们每天都在悄悄变老。', '/ɛvɹi deɪ wɪɹ ɡɹoʊɪŋ oʊldɚ./', '<span tid="18488">Every</span><span>day</span><span>we''re</span><span pid="3353" class="highlight highlight-h">growing older.</span>'
