INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 70.76, 75.48, 'Back in the middle of winter, during those long dark nights,', '还记得那个冬天正盛的时节，长夜漫漫。', '/bæk ɪnðə mɪdəl ʌv wɪntɚ, dʊɹɹɪŋ ðoʊz lɔŋ dɑːɹk naɪts,/', '<span tid="18511" class="highlight highlight-a">Back</span><span pid="3355" class="highlight highlight-c">in the middle of</span><span tid="18516">winter,</span><span tid="18517">during</span><span>those</span><span tid="18519">long</span><span tid="18520">dark</span><span tid="18521">nights,</span>'
