INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 75.48, 79.74, 'I kept thinking to myself, I just want it to be warm again.', '我总是对自己说，我只想春暖花开快些到来。', '/aɪ kɛpt θɪŋkɪŋ tə maɪsɛlf, aɪ dʒʌst wɔnt ɪt təbi wɔːɹm ɐɡɛn./', '<span>I</span><span pid="3356" class="highlight highlight-c">kept</span><span pid="3361" class="highlight highlight-i">thinking to myself,</span><span>I</span><span>just</span><span>want</span><span>it</span><span>to</span><span>be</span><span tid="18533">warm</span><span tid="18534">again.</span>'
