INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 81.06, 88.86, 'I spent so many days dreaming of spring, of the melting of snow, the longer light.', '我无数次在梦里回到春天，幻想着雪融之后的阳光与日渐拉长的白昼。', '/aɪ spɛnt soʊ mɛni deɪz dɹiːmɪŋ ʌv spɹɪŋ, ʌvðə mɛltɪŋ ʌv snoʊ, ðə lɔŋɡɚ laɪt./', '<span>I</span><span tid="18540">spent</span><span>so</span><span>many</span><span>days</span><span tid="18544">dreaming</span><span>of</span><span tid="18546">spring,</span><span>of</span><span>the</span><span tid="18549">melting</span><span>of</span><span tid="18551">snow,</span><span>the</span><span tid="18553">longer</span><span tid="18554" class="highlight highlight-a">light.</span>'
