INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 98.08, 101.04, 'It feels slow when you''re waiting for something.', '当你等待时，它缓慢如流沙；', '/ɪt fiːlz sloʊ wɛn jʊɹ weɪɾɪŋ fɔːɹ sʌmθɪŋ./', '<span>It</span><span tid="18576">feels</span><span tid="18577">slow</span><span>when</span><span>you''re</span><span tid="18580">waiting</span><span>for</span><span>something.</span>'
