INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 25, 101.04, 104.16, 'Then all at once, everything''s changed.', '可一转眼，一切便已天翻地覆。', '/ðɛn ɔːl ɐtwʌns, ɛvɹɪθɪŋz tʃeɪndʒd./', '<span>Then</span><span pid="3359" class="highlight highlight-c">all at once,</span><span tid="18587">everything''s</span><span tid="18588">changed.</span>'
