INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 26, 104.16, 110.5, 'As I''ve gotten older, I''ve realized how easy it is to always be looking ahead,', '年岁渐长，我开始明白人总是习惯向前张望，', '/æz aɪv ɡɑːʔn̩ oʊldɚ, aɪv ɹiːəlaɪzd haʊ iːzi ɪɾ ɪz tʊ ɔːlweɪz biː lʊkɪŋ ɐhɛd,/', '<span>As</span><span>I''ve</span><span>gotten</span><span tid="18592">older,</span><span>I''ve</span><span tid="18594" class="highlight highlight-a">realized</span><span>how</span><span tid="18596">easy</span><span>it</span><span>is</span><span>to</span><span tid="18600">always</span><span>be</span><span pid="3360" class="highlight highlight-d">looking ahead,</span>'
