INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 33.76, 41.82, 'And then if I spin you round, we have the most beautiful bouquet of roses, bottle of champagne.', '然后我转个身，就看到了一束超级美的玫瑰花，还有一瓶香槟。', '/ænd ðɛn ɪf aɪ spɪn juː ɹaʊnd, wiː hæv ðə moʊst bjuːɾifəl buːkeɪ ʌv ɹoʊzᵻz, bɑːɾəl ʌv ʃæmpeɪn./', '<span>And</span><span>then</span><span>if</span><span>I</span><span pid="1978" class="highlight highlight-d">spin you round,</span><span>we</span><span>have</span><span>the</span><span tid="18075">most</span><span tid="18076">beautiful</span><span tid="18077" class="highlight highlight-a">bouquet</span><span>of</span><span tid="18079">roses,</span><span tid="18080">bottle</span><span>of</span><span tid="18082" class="highlight highlight-a">champagne.</span>'
