INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 80.56, 84.44, 'He was literally like, oh, my God, for a split second, I thought I was getting proposed to again.', '他直接说：“天呐”。有那么一瞬间我还以为又要被求婚了。', '/hiː wʌz lɪɾɚɹəli laɪk, oʊ, maɪ ɡɑːd, fɚɹə splɪt sɛkənd, aɪ θɔːt aɪ wʌz ɡɛɾɪŋ pɹəpoʊzd tʊ ɐɡɛn./', '<span>He</span><span>was</span><span tid="18192" class="highlight highlight-a">literally</span><span>like,</span><span>oh,</span><span>my</span><span tid="18196">God,</span><span pid="1986" class="highlight highlight-i">for a split second,</span><span>I</span><span>thought</span><span>I</span><span>was</span><span>getting</span><span tid="18206" class="highlight highlight-a">proposed</span><span>to</span><span tid="18208">again.</span>'
