INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 6.52, 10.86, 'And today I''m excited to take you all on a tour of my insane office.', '今天我很兴奋要带大家参观一下我超酷的办公室。', '/ænd tədeɪ aɪm ɛksaɪɾᵻd tə teɪk juː ɔːl ɔn ɐ tʊɹ ʌv maɪ ɪnseɪn ɑːfɪs./', '<span>And</span><span tid="17408">today</span><span>I''m</span><span tid="17410">excited</span><span>to</span><span pid="80" class="highlight highlight-c">take you all on a tour of</span><span>my</span><span tid="17420" class="highlight highlight-a">insane</span><span tid="17421">office.</span>'
