INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 54.38, 56.92, 'He''s got a guest badge so he can join me for the tour.', '他现在有访客通行证，可以跟我一起参观。', '/hiːz ɡɑːt ɐ ɡɛst bædʒ soʊ hiː kæn dʒɔɪn miː fɚðə tʊɹ./', '<span>He''s</span><span>got</span><span>a</span><span pid="83" class="highlight highlight-c">guest badge</span><span>so</span><span>he</span><span>can</span><span tid="17566">join</span><span>me</span><span>for</span><span>the</span><span tid="17570" class="highlight highlight-a">tour.</span>'
