INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 57.5, 61.74, 'Once you scan in, there''s something that seriously blew my mind the first time I saw it.', '刷卡进去后，有个东西第一次看到真的让我震惊。', '/wʌns juː skæn ɪn, ðɛɹz sʌmθɪŋ ðæt sɪɹiəsli bluː maɪ maɪnd ðə fɜːst taɪm aɪ sɔː ɪt./', '<span tid="17571" class="highlight highlight-a">Once</span><span>you</span><span pid="84" class="highlight highlight-d">scan in,</span><span>there''s</span><span>something</span><span>that</span><span tid="17578" class="highlight highlight-a">seriously</span><span pid="85" class="highlight highlight-f">blew my mind</span><span pid="86" class="highlight highlight-l">the first time</span><span>I</span><span tid="17586">saw</span><span>it.</span>'
