INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 96.28, 100.04, 'and you can get coffee, tea or, even sparkling water.', '你可以在这儿喝咖啡、茶，甚至是汽水。', '/ænd juː kæn ɡɛt kɔfi, tiː ɔːɹ, iːvən spɑːɹklɪŋ wɔːɾɚ./', '<span>and</span><span>you</span><span>can</span><span>get</span><span tid="17702">coffee,</span><span tid="17703">tea</span><span>or,</span><span tid="17705">even</span><span pid="78" class="highlight highlight-c">sparkling water.</span>'
