INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 100.04, 107.97, 'Just wait just wait. Yeah, yeah, there''s like all the clean dishes you can get like plates, bowls, like forks, knives.', '你等下、你等下，对，这里有所有干净的餐具，比如盘子、碗、叉子、刀子。', '/dʒʌst weɪt dʒʌst weɪt. jɛh, jɛh, ðɛɹz laɪk ɔːl ðə kliːn dɪʃᵻz juː kæn ɡɛt laɪk pleɪts, boʊlz, laɪk fɔːɹks, naɪvz./', '<span>Just</span><span tid="17709">wait</span><span>just</span><span tid="17711">wait.</span><span>Yeah,</span><span>yeah,</span><span>there''s</span><span>like</span><span>all</span><span>the</span><span tid="17718">clean</span><span tid="17719">dishes</span><span>you</span><span>can</span><span>get</span><span>like</span><span tid="17724">plates,</span><span tid="17725" class="highlight highlight-a">bowls,</span><span>like</span><span tid="17727" class="highlight highlight-a">forks,</span><span tid="17728">knives.</span>'
