INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 21, 108.9, 111.88, 'Anything you want and then you could put food in this fridge as well.', '你想要什么都有，而且还可以把食物放进冰箱里。', '/ɛnɪθɪŋ juː wɔnt ænd ðɛn juː kʊd pʊt fuːd ɪn ðɪs fɹɪdʒ æz wɛl./', '<span tid="17729">Anything</span><span>you</span><span>want</span><span>and</span><span>then</span><span>you</span><span>could</span><span tid="17736">put</span><span tid="17737">food</span><span>in</span><span>this</span><span tid="17740" class="highlight highlight-a">fridge</span><span>as</span><span tid="17742">well.</span>'
