INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 14.3, 19.26, 'I do fit quite a bit of stuff in here and I don''t think I''ll be able to in the new apartment but.', '所以我在这里放了不少东西，我觉得新公寓里可能就放不下了。', '/aɪ duː fɪt kwaɪt ɐ bɪt ʌv stʌf ɪn hɪɹ ænd aɪ doʊnt θɪŋk aɪl biː eɪbəl tʊ ɪnðə nuː ɐpɑːɹtmənt bʌt./', '<span>I</span><span>do</span><span tid="16922" class="highlight highlight-a">fit</span><span tid="16923">quite</span><span>a</span><span tid="16925">bit</span><span>of</span><span tid="16927" class="highlight highlight-a">stuff</span><span>in</span><span>here</span><span>and</span><span>I</span><span>don''t</span><span>think</span><span>I''ll</span><span>be</span><span tid="16936">able</span><span>to</span><span>in</span><span>the</span><span tid="16940">new</span><span tid="16941" class="highlight highlight-a">apartment</span><span>but.</span>'
FROM episodes e WHERE e.video_id = '034dCTgtZcV926N';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 19.26, 25.88, 'I have my antique chair for my childhood home along with my antique mirror and my nightstand.', '这是我从小时候老家带来的古董椅，还有古董镜子和床头柜。', '/aɪ hæv maɪ æntiːk tʃɛɹ fɔːɹ maɪ tʃaɪldhʊd hoʊm ɐlɔŋ wɪð maɪ æntiːk mɪɹɚ ænd maɪ naɪtstænd./', '<span>I</span><span>have</span><span>my</span><span tid="16946" class="highlight highlight-a">antique</span><span tid="16947">chair</span><span>for</span><span>my</span><span tid="16950">childhood</span><span tid="16951">home</span><span pid="2764" class="highlight highlight-c">along with</span><span>my</span><span tid="16955" class="highlight highlight-a">antique</span><span tid="16956">mirror</span><span>and</span><span>my</span><span tid="16959" class="highlight highlight-a">nightstand.</span>'
