INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 25.88, 30.44, 'This is a queen-size bed so again this room is huge.', '这是一张大号床（Queen-size），所以说这房间真的很大。', '/ðɪs ɪz ɐ kwiːnsaɪz bɛd soʊ ɐɡɛn ðɪs ɹuːm ɪz hjuːdʒ./', '<span>This</span><span>is</span><span>a</span><span pid="2753" class="highlight highlight-i">queen-size bed</span><span>so</span><span tid="16966">again</span><span>this</span><span tid="16968">room</span><span>is</span><span tid="16970">huge.</span>'
