INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 37.52, 39.88, 'and I have my TV mounted above it.', '然后我把电视装在它上方。', '/ænd aɪ hæv maɪ tiːviː maʊntᵻd əbʌv ɪt./', '<span>and</span><span>I</span><span>have</span><span>my</span><span tid="16992">TV</span><span tid="16993" class="highlight highlight-a">mounted</span><span tid="16994">above</span><span>it.</span>'
