INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 87.72, 93.18, 'so there is like a spine in the back but you can''t see it.', '它后面其实有个支架，但你是看不到的。', '/soʊ ðɛɹ ɪz laɪk ɐ spaɪn ɪnðə bæk bʌt juː kænt siː ɪt./', '<span>so</span><span>there</span><span>is</span><span>like</span><span>a</span><span tid="17156" class="highlight highlight-a">spine</span><span>in</span><span>the</span><span tid="17159" class="highlight highlight-a">back</span><span>but</span><span>you</span><span tid="17162">can''t</span><span tid="17163">see</span><span>it.</span>'
