INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 93.18, 96.48, 'so it looks like my books are just stacked there.', '所以看起来像是我的书就那样堆在上面。', '/soʊ ɪt lʊks laɪk maɪ bʊks ɑːɹ dʒʌst stækt ðɛɹ./', '<span>so</span><span>it</span><span tid="17167" class="highlight highlight-a">looks</span><span>like</span><span>my</span><span tid="17170">books</span><span>are</span><span>just</span><span tid="17173" class="highlight highlight-a">stacked</span><span>there.</span>'
