INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 103.7, 107.06, 'We''re really high up yet we can hear absolutely everything.', '我们住得这么高，但几乎什么声音都能听到。', '/wɪɹ ɹiəli haɪ ʌp jɛt wiː kæn hɪɹ æbsəluːtli ɛvɹɪθɪŋ./', '<span>We''re</span><span tid="17196">really</span><span tid="17197">high</span><span>up</span><span tid="17199" class="highlight highlight-a">yet</span><span>we</span><span>can</span><span tid="17202">hear</span><span tid="17203" class="highlight highlight-a">absolutely</span><span tid="17204">everything.</span>'
