INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 21, 107.06, 112.46, 'I almost feel like it''s exaggerated because of the wind almost.', '我几乎觉得噪音因为风的原因被放大了。', '/aɪ ɔːlmoʊst fiːl laɪk ɪts ɛɡzædʒɚɹeɪɾᵻd bɪkʌz ʌvðə wɪnd ɔːlmoʊst./', '<span>I</span><span tid="17206">almost</span><span tid="17207">feel</span><span>like</span><span>it''s</span><span tid="17210">exaggerated</span><span>because</span><span>of</span><span>the</span><span tid="17214">wind</span><span tid="17215">almost.</span>'
