INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 22, 112.46, 117.78, 'The sirens in this area are out of control and it''s pretty much constant.', '这一带的警笛声真的非常夸张，几乎是持续不断的。', '/ðə saɪɹənz ɪn ðɪs ɛɹiə ɑːɹ aʊɾəv kəntɹoʊl ænd ɪts pɹɪɾi mʌtʃ kɑːnstənt./', '<span>The</span><span tid="17217" class="highlight highlight-a">sirens</span><span>in</span><span>this</span><span tid="17220">area</span><span>are</span><span pid="2758" class="highlight highlight-c">out of control</span><span>and</span><span>it''s</span><span tid="17227" class="highlight highlight-a">pretty</span><span tid="17228">much</span><span tid="17229" class="highlight highlight-a">constant.</span>'
