INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 121.1, 126.94, 'but I do work from home most of the time so I have my desk here with my new desk chair.', '不过我大部分时间都在家工作，所以我在这儿放了办公桌和新买的办公椅。', '/bʌt aɪ duː wɜːk fɹʌm hoʊm moʊst əv ðə taɪm soʊ aɪ hæv maɪ dɛsk hɪɹ wɪð maɪ nuː dɛsk tʃɛɹ./', '<span>but</span><span>I</span><span>do</span><span pid="2759" class="highlight highlight-c">work from home</span><span pid="2760" class="highlight highlight-i">most of the time</span><span>so</span><span>I</span><span>have</span><span>my</span><span tid="17253">desk</span><span>here</span><span>with</span><span>my</span><span tid="17257">new</span><span tid="17258">desk</span><span tid="17259">chair.</span>'
