INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 31.48, 34.9, 'So when I looked on Facebook, I just happened to come across this one,', '后来我在Facebook上随便看了看，正好看到这张，', '/soʊ wɛn aɪ lʊkt ɔn feɪsbʊk, aɪ dʒʌst hæpənd tə kʌm əkɹɑːs ðɪswʌn,/', '<span>So</span><span>when</span><span>I</span><span tid="16529" class="highlight highlight-a">looked</span><span>on</span><span tid="16531">Facebook,</span><span>I</span><span>just</span><span pid="1894" class="highlight highlight-d">happened to</span><span pid="1895" class="highlight highlight-d">come across</span><span>this</span><span>one,</span>'
