INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 26, 103.3, 108.273, 'And honestly, I feel like coasters are one of those things that when you buy them new, they''re never cool.', '说实话，我觉得杯垫就是那种，你去店里买新的，永远都不好看。', '/ænd ɑːnɪstli, aɪ fiːl laɪk koʊstɚz ɑːɹ wʌn ʌv ðoʊz θɪŋz ðæt wɛn juː baɪ ðɛm nuː, ðeɪɚ nɛvɚ kuːl./', '<span>And</span><span tid="16787" class="highlight highlight-a">honestly,</span><span>I</span><span tid="16789">feel</span><span>like</span><span tid="16791" class="highlight highlight-a">coasters</span><span>are</span><span>one</span><span>of</span><span>those</span><span>things</span><span>that</span><span>when</span><span>you</span><span tid="16800">buy</span><span>them</span><span tid="16802">new,</span><span>they''re</span><span tid="16804">never</span><span tid="16805" class="highlight highlight-a">cool.</span>'
