INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 27, 108.273, 112.34, 'Coasters you can find at thrift stores, and they always are so much cooler than when you buy them new.', '但在旧货店里淘到的杯垫，总是比新品有趣多了。', '/koʊstɚz juː kæn faɪnd æt θɹɪft stɔːɹz, ænd ðeɪ ɔːlweɪz ɑːɹ soʊ mʌtʃ kuːlɚ ðɐn wɛn juː baɪ ðɛm nuː./', '<span tid="16806" class="highlight highlight-a">Coasters</span><span>you</span><span>can</span><span tid="16809">find</span><span>at</span><span tid="16811" class="highlight highlight-a">thrift</span><span tid="16812" class="highlight highlight-a">stores,</span><span>and</span><span>they</span><span tid="16815">always</span><span>are</span><span>so</span><span tid="16818">much</span><span tid="16819" class="highlight highlight-a">cooler</span><span tid="16820">than</span><span>when</span><span>you</span><span tid="16823">buy</span><span>them</span><span tid="16825">new.</span>'
