INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 28, 112.34, 117.44, 'So go find some cool coasters at your thrift store and put them on your old coffee table.', '所以去你们附近的旧货店找些有趣的杯垫，放在你们的旧茶几上吧。', '/soʊ ɡoʊ faɪnd sʌm kuːl koʊstɚz æt jʊɹ θɹɪft stɔːɹ ænd pʊt ðɛm ɔn jʊɹ oʊld kɔfi teɪbəl./', '<span>So</span><span>go</span><span tid="16828">find</span><span>some</span><span tid="16830" class="highlight highlight-a">cool</span><span tid="16831" class="highlight highlight-a">coasters</span><span>at</span><span>your</span><span tid="16834" class="highlight highlight-a">thrift</span><span tid="16835" class="highlight highlight-a">store</span><span>and</span><span tid="16837">put</span><span>them</span><span>on</span><span>your</span><span tid="16841">old</span><span pid="1890" class="highlight highlight-c">coffee table.</span>'
