INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 40.28, 42.7, 'I''m speaking for myself. This is just for me.', '我是说我自己。这只是对我来说。', '/aɪm spiːkɪŋ fɔːɹ maɪsɛlf. ðɪs ɪz dʒʌst fɔːɹ miː./', '<span pid="1762" class="highlight highlight-l">I''m speaking for myself.</span><span>This</span><span>is</span><span>just</span><span>for</span><span>me.</span>'
