INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 36, 170.08, 172.44, 'and that''s kind of what I''m thinking for tonight.', '这就是我今晚的打算。', '/ænd ðæts kaɪnd ʌv wʌt aɪm θɪŋkɪŋ fɔːɹ tənaɪt./', '<span>and</span><span>that''s</span><span tid="16399">kind</span><span>of</span><span>what</span><span>I''m</span><span>thinking</span><span>for</span><span tid="16405">tonight.</span>'
