INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 37, 172.44, 178.48, 'I have my eye mask on, my jug, have my little journal, all ready to go', '我戴着眼罩，拿着我的水杯，小日记本也准备好了。', '/aɪ hæv maɪ aɪ mæsk ɔn, maɪ dʒʌɡ, hæv maɪ lɪɾəl dʒɜːnəl, ɔːl ɹɛdi tə ɡoʊ/', '<span>I</span><span>have</span><span>my</span><span pid="1757" class="highlight highlight-c">eye mask</span><span>on,</span><span>my</span><span tid="16413" class="highlight highlight-a">jug,</span><span>have</span><span>my</span><span tid="16416">little</span><span tid="16417" class="highlight highlight-a">journal,</span><span>all</span><span tid="16419">ready</span><span>to</span><span>go</span>'
