INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 61.28, 66.48, 'I wanna say this is country 48 or 49 I need to verify that.', '我想说这是我的第48个还是第49个国家，我得确认一下。', '/aɪ wɔnə seɪ ðɪs ɪz kʌntɹi fɔːɹɾi eɪt ɔːɹ fɔːɹɾi naɪn aɪ niːd tə vɛɹᵻfaɪ ðæt./', '<span pid="1913" class="highlight highlight-j">I wanna say</span><span>this</span><span>is</span><span tid="15557">country</span><span>48</span><span>or</span><span>49</span><span>I</span><span tid="15562">need</span><span>to</span><span tid="15564" class="highlight highlight-a">verify</span><span>that.</span>'
FROM episodes e WHERE e.video_id = '0387rgeGd2zIRhB';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 66.48, 69.94, 'We''re gonna hit the 50 mark, this contract, which is amazing.', '这个合约期间我们会突破50个国家的目标，太棒了。', '/wɪɹ ɡənə hɪt ðə fɪfti mɑːɹk, ðɪs kɑːntɹækt, wɪtʃ ɪz ɐmeɪzɪŋ./', '<span>We''re</span><span tid="15567">gonna</span><span tid="15568" class="highlight highlight-a">hit</span><span>the</span><span>50</span><span tid="15571" class="highlight highlight-a">mark,</span><span>this</span><span tid="15573" class="highlight highlight-a">contract,</span><span>which</span><span>is</span><span tid="15576">amazing.</span>'
