INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 71.26, 76.44, 'So we gotta do training first and then we''re gonna get off and seize the day.', '所以我们先去培训，然后就下船好好享受这一天。', '/soʊ wiː ɡɑːɾə duː tɹeɪnɪŋ fɜːst ænd ðɛn wɪɹ ɡənə ɡɛt ɔf ænd siːz ðə deɪ./', '<span>So</span><span>we</span><span tid="15583">gotta</span><span>do</span><span tid="15585" class="highlight highlight-a">training</span><span tid="15586">first</span><span>and</span><span>then</span><span>we''re</span><span tid="15590">gonna</span><span pid="1909" class="highlight highlight-d">get off</span><span>and</span><span pid="1910" class="highlight highlight-f">seize the day.</span>'
