INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 5.45, 9.92, 'Welcome to or back to my channel. My name is Stella if you have no idea who I am.', '欢迎来到我的频道，或者欢迎回来。如果你不知道我是谁，我叫Stella。', '/wɛlkʌm tʊ ɔːɹ bæk tə maɪ tʃænəl. maɪ neɪm ɪz stɛlə ɪf juː hæv noʊ aɪdiə huː aɪæm./', '<span tid="14573">Welcome</span><span>to</span><span>or</span><span tid="14576" class="highlight highlight-a">back</span><span>to</span><span>my</span><span tid="14579" class="highlight highlight-a">channel.</span><span>My</span><span tid="14581">name</span><span>is</span><span tid="14583">Stella</span><span>if</span><span>you</span><span pid="3381" class="highlight highlight-i">have no idea</span><span>who</span><span>I</span><span>am.</span>'
FROM episodes e WHERE e.video_id = '040CMuBrDaRd3sA';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 9.92, 12.4, 'This has been a very interesting week for me.', '这对我来说是非常有趣的一周。', '/ðɪs hæzbiːn ɐ vɛɹi ɪntɹɛstɪŋ wiːk fɔːɹ miː./', '<span>This</span><span>has</span><span>been</span><span>a</span><span>very</span><span tid="14597">interesting</span><span tid="14598">week</span><span>for</span><span>me.</span>'
FROM episodes e WHERE e.video_id = '040CMuBrDaRd3sA';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 12.4, 16.82, 'I got really sick and I lost my voice. I was nonverbal for the entirety of the week.', '我生了一场大病，还失去了声音。整个星期我都不能说话。', '/aɪ ɡɑːt ɹiəli sɪk ænd aɪ lɔst maɪ vɔɪs. aɪ wʌz nɑːnvɜːbəl fɚðɪ ɛntaɪɹɪɾi ʌvðə wiːk./', '<span>I</span><span pid="3382" class="highlight highlight-c">got really sick</span><span>and</span><span>I</span><span tid="14607">lost</span><span>my</span><span tid="14609">voice.</span><span>I</span><span>was</span><span tid="14612" class="highlight highlight-a">nonverbal</span><span pid="3383" class="highlight highlight-i">for the entirety of the week.</span>'
FROM episodes e WHERE e.video_id = '040CMuBrDaRd3sA';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 16.82, 23.08, 'but now it''s Friday and I have my voice and I have a day off in New York City.', '但现在是星期五，我的声音回来了，而且我今天在纽约有一天休息。', '/bʌt naʊ ɪts fɹaɪdeɪ ænd aɪ hæv maɪ vɔɪs ænd aɪ hæv ɐ deɪ ɔf ɪn nuː jɔːɹk sɪɾi./', '<span>but</span><span tid="14620">now</span><span>it''s</span><span tid="14622">Friday</span><span>and</span><span>I</span><span>have</span><span>my</span><span tid="14627">voice</span><span>and</span><span>I</span><span>have</span><span pid="3384" class="highlight highlight-c">a day off</span><span>in</span><span tid="14635">New</span><span tid="14636">York</span><span tid="14637">City.</span>'
