INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 25.38, 27.4, 'I''m not gonna lie to you guys. I''m gonna keep it real.', '我不想骗你们，我实话实说。', '/aɪm nɑːt ɡənə laɪ tə juː ɡaɪz. aɪm ɡənə kiːp ɪt ɹiːəl./', '<span pid="3386" class="highlight highlight-l">I''m not gonna lie to you</span><span tid="14651">guys.</span><span>I''m</span><span tid="14653">gonna</span><span pid="3387" class="highlight highlight-i">keep it real.</span>'
