INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 33.3, 38.68, 'It''s a perfect place to come by, lounge, read a book, work on your laptop.', '这是一个完美的地方，适合来这里放松，读书，或者在笔记本电脑上工作。', '/ɪts ɐ pɜːfɛkt pleɪs tə kʌm baɪ, laʊndʒ, ɹiːd ɐ bʊk, wɜːk ɔn jʊɹ læptɑːp./', '<span>It''s</span><span>a</span><span tid="34872">perfect</span><span tid="34873">place</span><span>to</span><span pid="3269" class="highlight highlight-d">come by,</span><span tid="34877" class="highlight highlight-a">lounge,</span><span tid="34878">read</span><span>a</span><span tid="34880">book,</span><span tid="34881">work</span><span>on</span><span>your</span><span tid="34884" class="highlight highlight-a">laptop.</span>'
