INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 44.94, 52.0, 'So since this is such a nice sunny day, I decided to walk down to the canals.', '因为今天阳光明媚，我决定走到运河边。', '/soʊ sɪns ðɪs ɪz sʌtʃ ɐ naɪs sʌni deɪ, aɪ dᵻsaɪdᵻd tə wɔːk daʊn tə ðə kənælz./', '<span>So</span><span tid="34910">since</span><span>this</span><span>is</span><span tid="34913">such</span><span>a</span><span tid="34915">nice</span><span tid="34916">sunny</span><span>day,</span><span>I</span><span tid="34919">decided</span><span>to</span><span tid="34921">walk</span><span tid="34922">down</span><span>to</span><span>the</span><span tid="34925" class="highlight highlight-a">canals.</span>'
