INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 61.6, 64.66, 'They had a collective exhibition of young artists.', '他们有一个年轻艺术家的集体展览。', '/ðeɪ hæd ɐ kəlɛktɪv ɛksɪbɪʃən ʌv jʌŋ ɑːɹɾɪsts./', '<span>They</span><span>had</span><span>a</span><span pid="3268" class="highlight highlight-c">collective exhibition</span><span>of</span><span tid="34951">young</span><span tid="34952" class="highlight highlight-a">artists.</span>'
