INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 26.5, 34.22, 'whenever there is a photo or a video of a public figure or a celebrity online somewhere.', '就是每当网上出现公众人物或者明星的照片或视频时，', '/wɛnɛvɚ ðɛɹ ɪz ɐ foʊɾoʊ ɔːɹ ɐ vɪdɪoʊ əvə pʌblɪk fɪɡjɚ ɔːɹ ɐ səlɛbɹᵻɾi ɑːnlaɪn sʌmwɛɹ./', '<span tid="34498">whenever</span><span>there</span><span>is</span><span>a</span><span tid="34502">photo</span><span>or</span><span>a</span><span tid="34505">video</span><span>of</span><span>a</span><span pid="2588" class="highlight highlight-c">public figure</span><span>or</span><span>a</span><span tid="34512" class="highlight highlight-a">celebrity</span><span tid="34513">online</span><span tid="34514" class="highlight highlight-a">somewhere.</span>'
