INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 39.42, 43.38, 'This person''s skin looks this way, they aged poorly.', '这个人的皮肤怎么怎么样，老得好快之类的。', '/ðɪs pɜːsənz skɪn lʊks ðɪs weɪ, ðeɪ eɪdʒd pʊɹli./', '<span>This</span><span tid="34526">person''s</span><span tid="34527">skin</span><span tid="34528" class="highlight highlight-a">looks</span><span>this</span><span tid="34530" class="highlight highlight-a">way,</span><span>they</span><span tid="34532" class="highlight highlight-a">aged</span><span tid="34533" class="highlight highlight-a">poorly.</span>'
