INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 52.82, 55.8, 'Sometimes I just wish looks were not even a thing.', '有时候我真的希望，外貌这个概念根本不存在。', '/sʌmtaɪmz aɪ dʒʌst wɪʃ lʊks wɜː nɑːt iːvən ɐ θɪŋ./', '<span pid="2597" class="highlight highlight-l">Sometimes I just wish</span><span tid="34557" class="highlight highlight-a">looks</span><span>were</span><span pid="2591" class="highlight highlight-i">not even a thing.</span>'
