INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 55.8, 62.94, 'Can you imagine if we lived in a world where we didn''t even know what pretty or ugly was?', '你能想象我们如果生活在一个我们完全不懂美和丑的世界里吗', '/kæn juː ɪmædʒɪn ɪf wiː lɪvd ɪn ɐ wɜːld wɛɹ wiː dɪdnt iːvən noʊ wʌt pɹɪɾi ɔːɹ ʌɡli wʌz?/', '<span>Can</span><span>you</span><span tid="34565" class="highlight highlight-a">imagine</span><span>if</span><span>we</span><span tid="34568">lived</span><span>in</span><span>a</span><span tid="34571">world</span><span>where</span><span>we</span><span>didn''t</span><span tid="34575">even</span><span>know</span><span>what</span><span tid="34578" class="highlight highlight-a">pretty</span><span>or</span><span tid="34580" class="highlight highlight-a">ugly</span><span>was?</span>'
FROM episodes e WHERE e.video_id = '042AnQLoLyYayIS';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
