INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 64.64, 71.32, 'It just existed without ever thinking about or understanding the concept of looks.', '就是存在在那里，但我们从来不会去思考，或者去理解“外貌”这个概念。', '/ɪt dʒʌst ɛɡzɪstᵻd wɪðaʊt ɛvɚ θɪŋkɪŋ ɐbaʊt ɔːɹ ʌndɚstændɪŋ ðə kɑːnsɛpt ʌv lʊks./', '<span>It</span><span>just</span><span tid="34589">existed</span><span tid="34590">without</span><span tid="34591" class="highlight highlight-a">ever</span><span>thinking</span><span>about</span><span>or</span><span tid="34595">understanding</span><span>the</span><span tid="34597" class="highlight highlight-a">concept</span><span>of</span><span tid="34599" class="highlight highlight-a">looks.</span>'
FROM episodes e WHERE e.video_id = '042AnQLoLyYayIS';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 71.32, 73.0, 'Is there a book on that or something?', '有这方面的书吗，还是什么？', '/ɪz ðɛɹ ɐ bʊk ɔn ðæt ɔːɹ sʌmθɪŋ?/', '<span>Is</span><span>there</span><span>a</span><span tid="34603">book</span><span>on</span><span>that</span><span>or</span><span>something?</span>'
