INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 73.0, 74.22, 'I would love to read it.', '我真的很想读一读。', '/aɪ wʊd lʌv tə ɹiːd ɪt./', '<span pid="2593" class="highlight highlight-l">I would love to</span><span tid="34612">read</span><span>it.</span>'
