INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 4.46, 'Yes, what is up peeps. Welcome back to a brand new episode. I hope you''re all doing well.', '大家好，欢迎回到全新的一集，你们最近还好吗。', '/jɛs, wʌt ɪz ʌp piːps. wɛlkʌm bæk tʊ ɐ bɹænd nuː ɛpɪsoʊd. aɪ hoʊp jʊɹ ɔːl duːɪŋ wɛl./', '<span>Yes,</span><span pid="2025" class="highlight highlight-l">what is up</span><span tid="33910">peeps.</span><span tid="33911">Welcome</span><span tid="33912" class="highlight highlight-a">back</span><span>to</span><span>a</span><span pid="2024" class="highlight highlight-c">brand new</span><span tid="33917" class="highlight highlight-a">episode.</span><span pid="2026" class="highlight highlight-l">I hope you''re all doing well.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 4.46, 7.9399999999999995, 'Today is Monday and the time has just gone 6 p.m.', '今天是星期一，现在时间刚刚过了下午6点。', '/tədeɪ ɪz mʌndeɪ ænd ðə taɪm hɐz dʒʌst ɡɔn sɪks piː.ɛm./', '<span tid="33924">Today</span><span>is</span><span tid="33926">Monday</span><span>and</span><span>the</span><span tid="33929">time</span><span pid="2027" class="highlight highlight-l">has just gone</span><span>6</span><span tid="33934">p.m.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 7.9399999999999995, 15.1, 'This is following on from my Gophr shift that I worked this morning where I earned 46 pound and 43 pence.', '这是我今天早上做完 Gophr 任务后接着做的，我赚了46英镑43便士。', '/ðɪs ɪz fɑːloʊɪŋ ɔn fɹʌm maɪ ɡɑːfɚ ʃɪft ðæt aɪ wɜːkt ðɪs mɔːɹnɪŋ wɛɹ aɪ ɜːnd fɔːɹɾi sɪks paʊnd ænd fɔːɹɾi θɹiː pɛns./', '<span>This</span><span>is</span><span pid="2028" class="highlight highlight-d">following on from</span><span>my</span><span tid="33941">Gophr</span><span tid="33942" class="highlight highlight-a">shift</span><span>that</span><span>I</span><span tid="33945">worked</span><span>this</span><span tid="33947">morning</span><span>where</span><span>I</span><span tid="33950" class="highlight highlight-a">earned</span><span>46</span><span tid="33952" class="highlight highlight-a">pound</span><span>and</span><span>43</span><span tid="33955" class="highlight highlight-a">pence.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 15.1, 22.5, 'I need to make another 53 pound and 57 pence to hit my 100 pound target for today.', '我还需要赚53英镑57便士才能达到今天100英镑的目标。', '/aɪ niːd tə meɪk ɐnʌðɚ fɪfti θɹiː paʊnd ænd fɪfti sɛvən pɛns tə hɪt maɪ wʌnhʌndɹɪd paʊnd tɑːɹɡɪt fɔːɹ tədeɪ./', '<span>I</span><span tid="33957">need</span><span>to</span><span tid="33959">make</span><span tid="33960">another</span><span>53</span><span tid="33962" class="highlight highlight-a">pound</span><span>and</span><span>57</span><span tid="33965" class="highlight highlight-a">pence</span><span>to</span><span tid="33967" class="highlight highlight-a">hit</span><span>my</span><span>100</span><span tid="33970" class="highlight highlight-a">pound</span><span tid="33971" class="highlight highlight-a">target</span><span>for</span><span tid="33973">today.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 22.5, 29.26, 'So if you haven''t watched that shift, head over and give it a watch. it''s going to be the last upload on the channel.', '所以如果你还没看过那个任务，赶紧去看看吧。就是频道里最新上传的视频。', '/soʊ ɪf juː hævənt wɑːtʃt ðæt ʃɪft, hɛd oʊvɚ ænd ɡɪv ɪɾ ɐ wɑːtʃ. ɪts ɡoʊɪŋ təbi ðə læst ʌploʊd ɔnðə tʃænəl./', '<span>So</span><span>if</span><span>you</span><span>haven''t</span><span tid="33978">watched</span><span>that</span><span tid="33980" class="highlight highlight-a">shift,</span><span pid="2029" class="highlight highlight-d">head over</span><span>and</span><span tid="33984">give</span><span>it</span><span>a</span><span tid="33987">watch.</span><span>it''s</span><span>going</span><span>to</span><span>be</span><span>the</span><span tid="33993" class="highlight highlight-a">last</span><span tid="33994">upload</span><span>on</span><span>the</span><span tid="33997" class="highlight highlight-a">channel.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 29.26, 30.5, 'I don''t know where I''m gonna be working.', '我还不知道今天要去哪儿。', '/aɪ doʊnt noʊ wɛɹ aɪm ɡənə biː wɜːkɪŋ./', '<span>I</span><span>don''t</span><span>know</span><span>where</span><span>I''m</span><span tid="34003">gonna</span><span>be</span><span tid="34005">working.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 30.5, 36.28, 'I''m heading up towards Lordship Lane now, which is in Dulwich because I haven''t been there in quite a few months.', '我现在正朝着杜尔维奇的Lordship Lane走去，因为我已经好几个月没去了。', '/aɪm hɛdɪŋ ʌp təwɔːɹdz lɔːɹdʃɪp leɪn naʊ, wɪtʃ ɪz ɪn dʌlwɪtʃ bɪkʌz aɪ hævənt bɪn ðɛɹ ɪn kwaɪt ɐ fjuː mʌnθs./', '<span>I''m</span><span pid="2030" class="highlight highlight-c">heading up towards</span><span tid="34010">Lordship</span><span tid="34011">Lane</span><span tid="34012">now,</span><span>which</span><span>is</span><span>in</span><span tid="34016">Dulwich</span><span>because</span><span>I</span><span>haven''t</span><span>been</span><span>there</span><span>in</span><span pid="2031" class="highlight highlight-c">quite a few</span><span tid="34026">months.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 36.28, 40.92, 'and it can be a very very busy place. they''ve got a lot of Indian restaurants.', '那里是个非常忙碌的地方，那里有很多印度餐馆。', '/ænd ɪt kæn biː ɐ vɛɹi vɛɹi bɪzi pleɪs. ðeɪv ɡɑːt ɐ lɑːt ʌv ɪndiən ɹɛstɹɑːnts./', '<span>and</span><span>it</span><span>can</span><span>be</span><span>a</span><span>very</span><span>very</span><span tid="34034" class="highlight highlight-a">busy</span><span tid="34035">place.</span><span pid="2034" class="highlight highlight-i">they''ve got</span><span>a</span><span tid="34039">lot</span><span>of</span><span tid="34041">Indian</span><span tid="34042">restaurants.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 40.92, 46.92, 'They''ve got Chipotle they''ve got... Well, they''ve got loads of stuff Thai food.', '有 Chipotle，泰国餐馆也有…总之他们有很多餐厅。', '/ðeɪv ɡɑːt tʃᵻpoʊtleɪ ðeɪv ɡɑːt... wɛl, ðeɪv ɡɑːt loʊdz ʌv stʌf taɪ fuːd./', '<span pid="2035" class="highlight highlight-i">They''ve got</span><span tid="34045">Chipotle</span><span pid="2035" class="highlight highlight-i">they''ve got...</span><span tid="34048">Well,</span><span pid="2035" class="highlight highlight-i">they''ve got</span><span pid="2017" class="highlight highlight-c">loads of</span><span tid="34053" class="highlight highlight-a">stuff</span><span pid="2032" class="highlight highlight-c">Thai food.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 10, 46.92, 52.18, 'There''s a lot of restaurants now. there is a lot of drivers that work in this area as well.', '现在有很多餐馆。而且这里也有很多外卖员。', '/ðɛɹz ɐ lɑːt ʌv ɹɛstɹɑːnts naʊ. ðɛɹ ɪz ɐ lɑːt ʌv dɹaɪvɚz ðæt wɜːk ɪn ðɪs ɛɹiə æz wɛl./', '<span>There''s</span><span>a</span><span tid="34058">lot</span><span>of</span><span tid="34060">restaurants</span><span tid="34061">now.</span><span>there</span><span>is</span><span>a</span><span tid="34065">lot</span><span>of</span><span tid="34067" class="highlight highlight-a">drivers</span><span>that</span><span tid="34069">work</span><span>in</span><span>this</span><span tid="34072">area</span><span pid="2012" class="highlight highlight-i">as well.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 52.18, 55.9, 'But I feel like there is enough orders to go around and', '但我觉得订单够多，应该够分。', '/bʌt aɪ fiːl laɪk ðɛɹ ɪz ɪnʌf ɔːɹdɚz tə ɡoʊ ɚɹaʊnd ænd/', '<span>But</span><span>I</span><span pid="2013" class="highlight highlight-i">feel like</span><span>there</span><span>is</span><span tid="34081">enough</span><span tid="34082" class="highlight highlight-a">orders</span><span>to</span><span pid="2018" class="highlight highlight-d">go around</span><span>and</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 55.9, 58.9, 'I''m not gonna be going home until I hit this 100 pound target.', '我今天不会回家，直到我达到100英镑的目标。', '/aɪm nɑːt ɡənə biː ɡoʊɪŋ hoʊm ʌntɪl aɪ hɪt ðɪs wʌnhʌndɹɪd paʊnd tɑːɹɡɪt./', '<span>I''m</span><span>not</span><span tid="34089">gonna</span><span>be</span><span>going</span><span tid="34092">home</span><span tid="34093" class="highlight highlight-a">until</span><span>I</span><span tid="34095" class="highlight highlight-a">hit</span><span>this</span><span>100</span><span tid="34098" class="highlight highlight-a">pound</span><span tid="34099" class="highlight highlight-a">target.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 58.9, 64.4, 'even if I have to stay out until God knows when 1 2 a.m.', '即使我得待到凌晨1、2点，我也不打算回家。', '/iːvən ɪf aɪ hæv tə steɪ aʊt ʌntɪl ɡɑːd noʊz wɛn wʌn tuː eɪ.ɛm./', '<span pid="2016" class="highlight highlight-c">even if</span><span>I</span><span>have</span><span>to</span><span pid="2019" class="highlight highlight-d">stay out</span><span tid="34107" class="highlight highlight-a">until</span><span pid="2020" class="highlight highlight-i">God knows when</span><span>1</span><span>2</span><span tid="34113">a.m.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 64.4, 68.66, 'And there''s the first one coming in there 6 pound and 79 pence.', '这里有第一个订单，6英镑79便士。', '/ænd ðɛɹz ðə fɜːst wʌn kʌmɪŋ ɪn ðɛɹ sɪks paʊnd ænd sɛvənti naɪn pɛns./', '<span>And</span><span>there''s</span><span>the</span><span tid="34117">first</span><span>one</span><span pid="2021" class="highlight highlight-d">coming in</span><span>there</span><span>6</span><span tid="34123" class="highlight highlight-a">pound</span><span>and</span><span>79</span><span tid="34126" class="highlight highlight-a">pence.</span>'
