INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 68.66, 74.48, 'Let''s pull over and go and get this one lovely stuff.', '我们停下车去拿这个。', '/lɛts pʊl oʊvɚ ænd ɡoʊ ænd ɡɛt ðɪswʌn lʌvli stʌf./', '<span>Let''s</span><span pid="2022" class="highlight highlight-d">pull over</span><span>and</span><span>go</span><span>and</span><span>get</span><span>this</span><span>one</span><span tid="34136" class="highlight highlight-a">lovely</span><span tid="34137" class="highlight highlight-a">stuff.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 74.48, 77.7, 'All right, I''ve got to go back down the hill that I just came from.', '好吧，我得再下坡去取单。', '/ɔːl ɹaɪt, aɪv ɡɑːt tə ɡoʊ bæk daʊn ðə hɪl ðæt aɪ dʒʌst keɪm fɹʌm./', '<span>All</span><span tid="34139" class="highlight highlight-a">right,</span><span pid="2011" class="highlight highlight-i">I''ve got to</span><span>go</span><span tid="34144" class="highlight highlight-a">back</span><span tid="34145">down</span><span>the</span><span tid="34147" class="highlight highlight-a">hill</span><span>that</span><span>I</span><span>just</span><span tid="34151">came</span><span>from.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 77.7, 82.43, 'I''m only gonna be running Deliveroo tonight I''m not gonna be running Uber Eats or Just Eat.', '今晚我只跑 Deliveroo，不会跑 Uber Eats 或 Just Eat。', '/aɪm oʊnli ɡənə biː ɹʌnɪŋ dᵻlɪvɚɹuː tənaɪt aɪm nɑːt ɡənə biː ɹʌnɪŋ juːbɚɹ iːts ɔːɹ dʒʌst iːt./', '<span>I''m</span><span tid="34154">only</span><span tid="34155">gonna</span><span>be</span><span tid="34157">running</span><span tid="34158">Deliveroo</span><span tid="34159">tonight</span><span>I''m</span><span>not</span><span tid="34162">gonna</span><span>be</span><span tid="34164">running</span><span tid="34165" class="highlight highlight-a">Uber</span><span tid="34166">Eats</span><span>or</span><span>Just</span><span tid="34169">Eat.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 82.43, 89.64, 'The reason for that is uh well Just Eat, I can''t get any shifts and Uber Eats is slow.', '原因是，Just Eat，我不能接到任何班次，然后 Uber Eats 很慢。', '/ðə ɹiːzən fɔːɹ ðæt ɪz ʌ wɛl dʒʌst iːt, aɪ kænt ɡɛt ɛni ʃɪfts ænd juːbɚɹ iːts ɪz sloʊ./', '<span>The</span><span tid="34171">reason</span><span>for</span><span>that</span><span>is</span><span>uh</span><span tid="34176">well</span><span>Just</span><span tid="34178">Eat,</span><span>I</span><span tid="34180">can''t</span><span>get</span><span tid="34182">any</span><span tid="34183" class="highlight highlight-a">shifts</span><span>and</span><span tid="34185" class="highlight highlight-a">Uber</span><span tid="34186">Eats</span><span>is</span><span tid="34188">slow.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 89.64, 95.08, 'so I don''t want to be taking my attention away from the app that gives me the most orders.', '所以我不想把注意力分散到那些不那么多单的平台上。', '/soʊ aɪ doʊnt wɔnt təbi teɪkɪŋ maɪ ɐtɛnʃən ɐweɪ fɹʌmðɪ æp ðæt ɡɪvz miː ðə moʊst ɔːɹdɚz./', '<span>so</span><span>I</span><span>don''t</span><span>want</span><span>to</span><span>be</span><span pid="2014" class="highlight highlight-d">taking my attention away from</span><span>the</span><span tid="34201">app</span><span>that</span><span tid="34203">gives</span><span>me</span><span>the</span><span tid="34206">most</span><span tid="34207" class="highlight highlight-a">orders.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 95.08, 97.88, 'I''m gonna be sticking with Deliveroo today.', '今天我只跑 Deliveroo。', '/aɪm ɡənə biː stɪkɪŋ wɪð dᵻlɪvɚɹuː tədeɪ./', '<span>I''m</span><span tid="34209">gonna</span><span>be</span><span pid="2023" class="highlight highlight-d">sticking with</span><span tid="34213">Deliveroo</span><span tid="34214">today.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 21, 97.88, 101.03, 'And uh yeah, I reckon it''s gonna be a decent one.', '我觉得今天会有不错的成果。', '/ænd ʌ jɛh, aɪ ɹɛkən ɪts ɡənə biː ɐ diːsənt wʌn./', '<span>And</span><span>uh</span><span>yeah,</span><span pid="2015" class="highlight highlight-c">I reckon</span><span>it''s</span><span tid="34221">gonna</span><span>be</span><span>a</span><span tid="34224" class="highlight highlight-a">decent</span><span>one.</span>'
FROM episodes e WHERE e.video_id = '043jEyV3e32WDCw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
