INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 5.52, 'Ladies and gents, I''ve been waiting months for it to come to my Costco, and it''s finally here.', '先生们女士们，我已经等了好几个月，终于等到它来到我的好市多了。', '/leɪdiz ænd dʒɛnts, aɪv bɪn weɪɾɪŋ mʌnθs fɔːɹ ɪt tə kʌm tə maɪ kɔstkoʊ, ænd ɪts faɪnəli hɪɹ./', '<span tid="33097">Ladies</span><span>and</span><span tid="33099">gents,</span><span>I''ve</span><span>been</span><span tid="33102">waiting</span><span tid="33103">months</span><span>for</span><span>it</span><span>to</span><span tid="33107">come</span><span>to</span><span>my</span><span tid="33110" class="highlight highlight-a">Costco,</span><span>and</span><span>it''s</span><span tid="33113">finally</span><span>here.</span>'
