INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 13.5, 14.6, 'It''s not just tallow.', '这不仅仅是牛油。', '/ɪts nɑːt dʒʌst tæloʊ./', '<span>It''s</span><span>not</span><span>just</span><span tid="33141" class="highlight highlight-a">tallow.</span>'
