INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 14.6, 24.2, 'It''s 100 % grass-fed, grass-finished tallow, a big 28-ounce jar for $17.99.', '这是100%草饲、草养的牛油，一大瓶28盎司（~793g），价格是17.99美元（~129元）。', '/ɪts wʌnhʌndɹɪd pɚsɛnt ɡɹæsfɛd, ɡɹæsfɪnɪʃt tæloʊ, ɐ bɪɡ twɛnti eɪtaʊns dʒɑːɹ fɔːɹ dɑːlɚ sɛvəntiːn.naɪnti naɪn./', '<span>It''s</span><span>100</span><span>%</span><span tid="33145">grass-fed,</span><span tid="33146">grass-finished</span><span tid="33147" class="highlight highlight-a">tallow,</span><span>a</span><span tid="33149">big</span><span tid="33150">28-ounce</span><span tid="33151" class="highlight highlight-a">jar</span><span>for</span><span>$17.99.</span>'
