INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 56.2, 59.8, 'It just looks so sad and droopy and has so much character to it.', '它看起来有点沮丧、耷拉着，但又非常有个性。', '/ɪt dʒʌst lʊks soʊ sæd ænd dɹuːpi ænd hɐz soʊ mʌtʃ kæɹɪktɚ tʊ ɪt./', '<span>It</span><span>just</span><span tid="32526" class="highlight highlight-a">looks</span><span>so</span><span tid="32528">sad</span><span>and</span><span tid="32530" class="highlight highlight-a">droopy</span><span>and</span><span>has</span><span>so</span><span tid="32534">much</span><span tid="32535" class="highlight highlight-a">character</span><span>to</span><span>it.</span>'
