INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 78.3, 87.44, 'And this is typically how you would find most Dracaena at the store either like this or taller versions of this.', '你在商店里看到的大多数龙血树基本都是这样的，或者是更高一点的版本。', '/ænd ðɪs ɪz tɪpɪkli haʊ juː wʊd faɪnd moʊst dɹækiːnə æt ðə stɔːɹ iːðɚ laɪk ðɪs ɔːɹ tɔːlɚ vɜːʒənz ʌv ðɪs./', '<span>And</span><span>this</span><span>is</span><span tid="32598" class="highlight highlight-a">typically</span><span>how</span><span>you</span><span>would</span><span tid="32602">find</span><span tid="32603">most</span><span tid="32604">Dracaena</span><span>at</span><span>the</span><span tid="32607" class="highlight highlight-a">store</span><span tid="32608">either</span><span>like</span><span>this</span><span>or</span><span tid="32612">taller</span><span tid="32613" class="highlight highlight-a">versions</span><span>of</span><span>this.</span>'
