INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 28, 131.4, 135.54, 'I''m not sure, but they look a bit similar to me.', '我不太确定，但对我来说它们看起来挺像的。', '/aɪm nɑːt ʃʊɹ, bʌt ðeɪ lʊk ɐ bɪt sɪmɪlɚ tə miː./', '<span>I''m</span><span>not</span><span tid="32747">sure,</span><span>but</span><span>they</span><span tid="32750" class="highlight highlight-a">look</span><span>a</span><span tid="32752">bit</span><span tid="32753">similar</span><span>to</span><span>me.</span>'
