INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 6.04, 'This is Erewhon, the most expensive grocery store in the world, but it is so much more than that.', '这里是 Erewhon，全世界最贵的杂货店，但它远不止如此。', '/ðɪs ɪz ɪɹuːhən, ðə moʊst ɛkspɛnsɪv ɡɹoʊsɚɹi stɔːɹ ɪnðə wɜːld, bʌt ɪɾ ɪz soʊ mʌtʃ mɔːɹ ðɐn ðæt./', '<span>This</span><span>is</span><span tid="30881" class="highlight highlight-a">Erewhon,</span><span>the</span><span tid="30883">most</span><span tid="30884">expensive</span><span pid="936" class="highlight highlight-c">grocery store</span><span>in</span><span>the</span><span tid="30889">world,</span><span>but</span><span>it</span><span>is</span><span>so</span><span tid="30894">much</span><span>more</span><span tid="30896">than</span><span>that.</span>'
FROM episodes e WHERE e.video_id = '048daaeM6zLVq8v';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 6.04, 8.7, 'It''s a status symbol, a cultural phenomenon.', '它是一种地位象征，是一种文化现象', '/ɪts ɐ stæɾəs sɪmbəl, ɐ kʌltʃɚɹəl fɪnɑːmɪnən./', '<span>It''s</span><span>a</span><span pid="942" class="highlight highlight-c">status symbol,</span><span>a</span><span pid="943" class="highlight highlight-c">cultural phenomenon.</span>'
