INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 13.06, 16.2, 'While other luxury grocers like Whole Foods might charge you a premium.', '虽然其他高端超市比如 Whole Foods 也会收取溢价，', '/waɪl ʌðɚ lʌkʃɚɹi ɡɹoʊsɚz laɪk hoʊl fuːdz maɪt tʃɑːɹdʒ juː ɐ pɹiːmiəm./', '<span tid="30923">While</span><span tid="30924">other</span><span tid="30925" class="highlight highlight-a">luxury</span><span tid="30926" class="highlight highlight-a">grocers</span><span>like</span><span tid="30928">Whole</span><span tid="30929">Foods</span><span tid="30930" class="highlight highlight-a">might</span><span tid="30931" class="highlight highlight-a">charge</span><span>you</span><span>a</span><span tid="30934" class="highlight highlight-a">premium.</span>'
