INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 2.2800000000000002, 'okay so let me show you what I''m making for breakfast.', '给你们看一下我今天早上要做什么早餐。', '/oʊkeɪ soʊ lɛt miː ʃoʊ juː wʌt aɪm meɪkɪŋ fɔːɹ bɹɛkfəst./', '<span>okay</span><span>so</span><span>let</span><span>me</span><span tid="30378">show</span><span>you</span><span>what</span><span>I''m</span><span tid="30382">making</span><span>for</span><span tid="30384">breakfast.</span>'
