INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 10, 44.84, 46.62, 'It''s just nuts.', '这太疯狂了。', '/ɪts dʒʌst nʌts./', '<span>It''s</span><span>just</span><span tid="28151">nuts.</span>'
FROM episodes e WHERE e.video_id = '052BI0DcaOGR0i1';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 46.62, 50.42, 'There''s literally these massive window panes with water coming down them.', '这边真的有这些巨大的玻璃墙，水从上面流下来。', '/ðɛɹz lɪɾɚɹəli ðiːz mæsɪv wɪndoʊ peɪnz wɪð wɔːɾɚ kʌmɪŋ daʊn ðɛm./', '<span>There''s</span><span tid="28153" class="highlight highlight-a">literally</span><span>these</span><span tid="28155" class="highlight highlight-a">massive</span><span pid="801" class="highlight highlight-c">window panes</span><span>with</span><span tid="28159">water</span><span tid="28160">coming</span><span tid="28161">down</span><span>them.</span>'
