INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 50.42, 53.12, 'Tons of beautiful, colorful, freshwater fish.', '满是美丽、色彩斑斓的淡水鱼。', '/tʌnz ʌv bjuːɾifəl, kʌlɚfəl, fɹɛʃwɔːɾɚ fɪʃ./', '<span tid="28163">Tons</span><span>of</span><span tid="28165">beautiful,</span><span tid="28166" class="highlight highlight-a">colorful,</span><span pid="802" class="highlight highlight-c">freshwater fish.</span>'
