INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 55.24, 58.32, 'This is like their version of an aquarium tunnel, but for fresh water.', '这就像是他们的淡水版水族隧道。', '/ðɪs ɪz laɪk ðɛɹ vɜːʒən əvən ɐkwɛɹiəm tʌnəl, bʌt fɔːɹ fɹɛʃ wɔːɾɚ./', '<span>This</span><span>is</span><span>like</span><span>their</span><span tid="28180" class="highlight highlight-a">version</span><span>of</span><span>an</span><span tid="28183" class="highlight highlight-a">aquarium</span><span tid="28184" class="highlight highlight-a">tunnel,</span><span>but</span><span>for</span><span tid="28187" class="highlight highlight-a">fresh</span><span tid="28188">water.</span>'
