INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 79, 229.66, 232.82, 'There''s also guppies and platies in this tank.', '这个缸里还有孔雀鱼和月光鱼。', '/ðɛɹz ɔːlsoʊ ɡʌpɪz ænd pleɪɾiz ɪn ðɪs tæŋk./', '<span>There''s</span><span>also</span><span tid="28685" class="highlight highlight-a">guppies</span><span>and</span><span tid="28687" class="highlight highlight-a">platies</span><span>in</span><span>this</span><span tid="28690" class="highlight highlight-a">tank.</span>'
