INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 80, 232.82, 236.32, 'There''s also some cherry barbs, which are these small, all red fish.', '还有一些樱桃无须魮，这些全红的小鱼。', '/ðɛɹz ɔːlsoʊ sʌm tʃɛɹi bɑːɹbz, wɪtʃ ɑːɹ ðiːz smɔːl, ɔːl ɹɛd fɪʃ./', '<span>There''s</span><span>also</span><span>some</span><span tid="28694" class="highlight highlight-a">cherry</span><span tid="28695">barbs,</span><span>which</span><span>are</span><span>these</span><span tid="28699">small,</span><span pid="814" class="highlight highlight-i">all red</span><span tid="28702">fish.</span>'
