INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 87, 309.24, 313.12, 'so come in here and take a look at her teeth. take a look at her tongue.', '来看看她的牙齿和舌头。', '/soʊ kʌm ɪn hɪɹ ænd teɪk ɐ lʊk æt hɜː tiːθ. teɪk ɐ lʊk æt hɜː tʌŋ./', '<span>so</span><span pid="715" class="highlight highlight-d">come in</span><span>here</span><span>and</span><span pid="748" class="highlight highlight-i">take a look at</span><span>her</span><span tid="26998">teeth.</span><span pid="748" class="highlight highlight-i">take a look at</span><span>her</span><span tid="27004" class="highlight highlight-a">tongue.</span>'
