INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 88, 313.12, 318.18, 'you have two kinds of sloths. you have two-toed sloths and three-toed sloths. you don''t really see the three-toed sloths here in captivity.', '树懒分两趾和三趾两种。你在圈养环境里很少看到三趾树懒。', '/juː hæv tuː kaɪndz ʌv slɑːθs. juː hæv tuːtoʊd slɑːθs ænd θɹiːtoʊd slɑːθs. juː doʊnt ɹiəli siː ðə θɹiːtoʊd slɑːθs hɪɹ ɪn kæptɪvᵻɾi./', '<span>you</span><span>have</span><span>two</span><span tid="27008">kinds</span><span>of</span><span tid="27010" class="highlight highlight-a">sloths.</span><span>you</span><span>have</span><span tid="27013">two-toed</span><span tid="27014" class="highlight highlight-a">sloths</span><span>and</span><span tid="27016">three-toed</span><span tid="27017" class="highlight highlight-a">sloths.</span><span>you</span><span>don''t</span><span tid="27020">really</span><span tid="27021">see</span><span>the</span><span tid="27023">three-toed</span><span tid="27024" class="highlight highlight-a">sloths</span><span>here</span><span>in</span><span tid="27027" class="highlight highlight-a">captivity.</span>'
FROM episodes e WHERE e.video_id = '054dDMEu75yRY78';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 89, 318.18, 321.2, 'because of their crazy diet they have to eat cecropia leaves.', '因为它们只能吃一种叫“伞树叶”的植物。', '/bɪkʌz ʌv ðɛɹ kɹeɪzi daɪət ðeɪ hæv tʊ iːt sɛkɹoʊpiə liːvz./', '<span>because</span><span>of</span><span>their</span><span tid="27031">crazy</span><span tid="27032" class="highlight highlight-a">diet</span><span>they</span><span>have</span><span>to</span><span tid="27036">eat</span><span tid="27037">cecropia</span><span tid="27038">leaves.</span>'
