INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 90, 321.2, 324.62, 'which only grow here in South Florida and tropical climates.', '这种植物只在南佛罗里达和热带地区生长。', '/wɪtʃ oʊnli ɡɹoʊ hɪɹ ɪn saʊθ flɔːɹɪdə ænd tɹɑːpɪkəl klaɪməts./', '<span>which</span><span tid="27040">only</span><span tid="27041">grow</span><span>here</span><span>in</span><span tid="27044">South</span><span tid="27045">Florida</span><span>and</span><span tid="27047" class="highlight highlight-a">tropical</span><span tid="27048" class="highlight highlight-a">climates.</span>'
FROM episodes e WHERE e.video_id = '054dDMEu75yRY78';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 91, 324.62, 327.08, 'so there is a few facilities that keep three-toed sloths.', '有些地方会养三趾树懒，', '/soʊ ðɛɹ ɪz ɐ fjuː fəsɪlᵻɾiz ðæt kiːp θɹiːtoʊd slɑːθs./', '<span>so</span><span>there</span><span>is</span><span>a</span><span tid="27053">few</span><span tid="27054" class="highlight highlight-a">facilities</span><span>that</span><span tid="27056">keep</span><span tid="27057">three-toed</span><span tid="27058" class="highlight highlight-a">sloths.</span>'
FROM episodes e WHERE e.video_id = '054dDMEu75yRY78';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 92, 327.08, 332.94, 'but I believe they actually fly in their leaves from Hawaii several times a week in order to feed their sloths.', '但据我所知，他们要每周多次从夏威夷空运叶子来喂它们。', '/bʌt aɪ bᵻliːv ðeɪ æktʃuːəli flaɪ ɪn ðɛɹ liːvz fɹʌm həwaɪiː sɛvɹəl taɪmz ɐ wiːk ɪn ɔːɹdɚ tə fiːd ðɛɹ slɑːθs./', '<span>but</span><span>I</span><span tid="27061">believe</span><span>they</span><span tid="27063">actually</span><span tid="27064">fly</span><span>in</span><span>their</span><span tid="27067">leaves</span><span>from</span><span tid="27069">Hawaii</span><span tid="27070">several</span><span tid="27071">times</span><span>a</span><span tid="27073">week</span><span>in</span><span tid="27075" class="highlight highlight-a">order</span><span>to</span><span tid="27077" class="highlight highlight-a">feed</span><span>their</span><span tid="27079" class="highlight highlight-a">sloths.</span>'
