INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 32, 140.06, 146.86, 'Secondly now this movement is also one which is widely done is the dumbbell shoulder press.', '第二个动作也是很常见的，那就是哑铃肩推。', '/sɛkəndli naʊ ðɪs muːvmənt ɪz ɔːlsoʊ wʌn wɪtʃ ɪz waɪdli dʌn ɪz ðə dʌmbɛl ʃoʊldɚ pɹɛs./', '<span tid="23369" class="highlight highlight-a">Secondly</span><span tid="23370">now</span><span>this</span><span tid="23372" class="highlight highlight-a">movement</span><span>is</span><span>also</span><span>one</span><span>which</span><span>is</span><span tid="23378" class="highlight highlight-a">widely</span><span>done</span><span>is</span><span>the</span><span pid="2411" class="highlight highlight-c">dumbbell shoulder press.</span>'
