INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 152.78, 157.14, 'and then for me that also contributes to a better development of the shoulder.', '这样对肩部的发力会更精准，效果也更好。', '/ænd ðɛn fɔːɹ miː ðæt ɔːlsoʊ kəntɹɪbjuːts tʊ ɐ bɛɾɚ dɪvɛləpmənt ʌvðə ʃoʊldɚ./', '<span>and</span><span>then</span><span>for</span><span>me</span><span>that</span><span>also</span><span pid="2413" class="highlight highlight-c">contributes to</span><span>a</span><span tid="23412">better</span><span tid="23413" class="highlight highlight-a">development</span><span>of</span><span>the</span><span tid="23416" class="highlight highlight-a">shoulder.</span>'
