INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 38, 172.0, 177.28, 'So those are my two favourite exercises for the push muscle group.', '所以这两个就是我最喜欢的推类动作。', '/soʊ ðoʊz ɑːɹ maɪ tuː feɪvɹɪt ɛksɚsaɪzᵻz fɚðə pʊʃ mʌsəl ɡɹuːp./', '<span>So</span><span>those</span><span>are</span><span>my</span><span>two</span><span tid="23466">favourite</span><span tid="23467" class="highlight highlight-a">exercises</span><span>for</span><span>the</span><span tid="23470" class="highlight highlight-a">push</span><span pid="2376" class="highlight highlight-c">muscle group.</span>'
