INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 39, 177.28, 180.96, 'Next one we move on to back.', '接下来我们讲背部训练。', '/nɛkst wʌn wiː muːv ɔn tə bæk./', '<span tid="23473">Next</span><span>one</span><span>we</span><span pid="2418" class="highlight highlight-c">move on to</span><span tid="23479" class="highlight highlight-a">back.</span>'
