FROM episodes e WHERE e.video_id = '056WwYdevNyPvkr';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 41, 185.1, 192.4, 'I love training back compared to push and legs partly because it has this one exercise called the the pull-up.', '比起推和腿，我更喜欢练背，部分原因是因为有一个动作——引体向上。', '/aɪ lʌv tɹeɪnɪŋ bæk kəmpɛɹd tə pʊʃ ænd lɛɡz pɑːɹtli bɪkʌz ɪt hɐz ðɪswʌn ɛksɚsaɪz kɔːld ðə ðə pʊlʌp./', '<span>I</span><span tid="23495">love</span><span tid="23496">training</span><span tid="23497" class="highlight highlight-a">back</span><span pid="2362" class="highlight highlight-c">compared to</span><span tid="23500" class="highlight highlight-a">push</span><span>and</span><span tid="23502" class="highlight highlight-a">legs</span><span pid="2405" class="highlight highlight-i">partly because</span><span>it</span><span>has</span><span>this</span><span>one</span><span tid="23509" class="highlight highlight-a">exercise</span><span tid="23510">called</span><span>the</span><span>the</span><span tid="23513" class="highlight highlight-a">pull-up.</span>'
