INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 42, 192.4, 196.08, 'Now the pull-up is an absolute goated movement.', '引体向上真的是神级动作。', '/naʊ ðə pʊlʌp ɪz ɐn æbsəluːt ɡoʊɾᵻd muːvmənt./', '<span tid="23514">Now</span><span>the</span><span tid="23516" class="highlight highlight-a">pull-up</span><span>is</span><span>an</span><span tid="23519" class="highlight highlight-a">absolute</span><span tid="23520" class="highlight highlight-a">goated</span><span tid="23521" class="highlight highlight-a">movement.</span>'
FROM episodes e WHERE e.video_id = '056WwYdevNyPvkr';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 43, 196.08, 201.78, 'partly because if you can nail the pull-up when I and I mean nail I mean obviously go up and slow down.', '如果你能掌握它，我是说掌握得很好，比如上拉慢下，', '/pɑːɹtli bɪkʌz ɪf juː kæn neɪl ðə pʊlʌp wɛn aɪ ænd aɪ miːn neɪl aɪ miːn ɑːbviəsli ɡoʊ ʌp ænd sloʊ daʊn./', '<span pid="2406" class="highlight highlight-i">partly because</span><span>if</span><span>you</span><span>can</span><span tid="23527" class="highlight highlight-a">nail</span><span>the</span><span tid="23529" class="highlight highlight-a">pull-up</span><span>when</span><span>I</span><span>and</span><span>I</span><span tid="23534">mean</span><span tid="23535" class="highlight highlight-a">nail</span><span>I</span><span tid="23537">mean</span><span tid="23538" class="highlight highlight-a">obviously</span><span>go</span><span>up</span><span>and</span><span pid="2360" class="highlight highlight-d">slow down.</span>'
FROM episodes e WHERE e.video_id = '056WwYdevNyPvkr';
