INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 110, 519.02, 523.42, 'thank you for listening as always and I''ll see you guys in the next one. peace', '感谢大家一如既往地收看，我们下期再见，拜拜。', '/θæŋk juː fɔːɹ lɪsənɪŋ æz ɔːlweɪz ænd aɪl siː juː ɡaɪz ɪnðə nɛkst wʌn. piːs/', '<span tid="24528">thank</span><span>you</span><span>for</span><span tid="24531">listening</span><span pid="2447" class="highlight highlight-i">as always</span><span>and</span><span>I''ll</span><span tid="24536">see</span><span>you</span><span tid="24538">guys</span><span>in</span><span>the</span><span tid="24541">next</span><span>one.</span><span tid="24543">peace</span>'
