INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 48, 268.44, 272.12, 'For example, in this case, there''s a blind spot.', '例如在这个地方，有一个视野盲区。', '/fɔːɹ ɛɡzæmpəl, ɪn ðɪs keɪs, ðɛɹz ɐ blaɪnd spɑːt./', '<span>For</span><span tid="21777">example,</span><span pid="2895" class="highlight highlight-i">in this case,</span><span>there''s</span><span>a</span><span tid="21783">blind</span><span tid="21784" class="highlight highlight-a">spot.</span>'
FROM episodes e WHERE e.video_id = '058GxNmMGp24Q66';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 49, 272.12, 274.34, 'I don''t see any person behind this car.', '我看不到这辆车后面的人。', '/aɪ doʊnt siː ɛni pɜːsən bᵻhaɪnd ðɪs kɑːɹ./', '<span>I</span><span>don''t</span><span tid="21787">see</span><span tid="21788">any</span><span tid="21789">person</span><span tid="21790">behind</span><span>this</span><span tid="21792">car.</span>'
FROM episodes e WHERE e.video_id = '058GxNmMGp24Q66';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 50, 274.34, 278.86, 'I don''t want to be sitting on my throttle pedal all the time.', '我不想一直踩着油门。', '/aɪ doʊnt wɔnt təbi sɪɾɪŋ ɔn maɪ θɹɑːɾəl pɛdəl ɔːl ðə taɪm./', '<span>I</span><span>don''t</span><span>want</span><span>to</span><span>be</span><span tid="21798">sitting</span><span>on</span><span>my</span><span tid="21801">throttle</span><span tid="21802" class="highlight highlight-a">pedal</span><span pid="2864" class="highlight highlight-c">all the time.</span>'
