INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 44.58, 47.58, 'Ohio is nothing if not soggy right now.', '俄亥俄州现在湿得不得了。', '/oʊhaɪoʊ ɪz nʌθɪŋ ɪf nɑːt sɑːɡi ɹaɪt naʊ./', '<span tid="19780">Ohio</span><span>is</span><span pid="2457" class="highlight highlight-l">nothing if not</span><span tid="19785" class="highlight highlight-a">soggy</span><span tid="19786" class="highlight highlight-a">right</span><span tid="19787">now.</span>'
