INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 47.58, 49.76, 'It just rains and rains and rains.', '一直下雨，雨下个不停。', '/ɪt dʒʌst ɹeɪnz ænd ɹeɪnz ænd ɹeɪnz./', '<span>It</span><span>just</span><span tid="19790">rains</span><span>and</span><span tid="19792">rains</span><span>and</span><span tid="19794">rains.</span>'
