INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 49.76, 54.24, 'And I didn''t wanna harvest this stuff while the ground is wet, but I don''t think I''m gonna have a choice.', '我不想在地面湿的时候采摘这些大蒜，但我也没什么办法了。', '/ænd aɪ dɪdnt wɔnə hɑːɹvɪst ðɪs stʌf waɪl ðə ɡɹaʊnd ɪz wɛt, bʌt aɪ doʊnt θɪŋk aɪm ɡənə hæv ɐ tʃɔɪs./', '<span>And</span><span>I</span><span>didn''t</span><span tid="19798">wanna</span><span tid="19799" class="highlight highlight-a">harvest</span><span>this</span><span tid="19801" class="highlight highlight-a">stuff</span><span tid="19802">while</span><span>the</span><span tid="19804" class="highlight highlight-a">ground</span><span>is</span><span tid="19806">wet,</span><span>but</span><span>I</span><span>don''t</span><span>think</span><span>I''m</span><span tid="19812">gonna</span><span>have</span><span>a</span><span tid="19815" class="highlight highlight-a">choice.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 54.24, 56.4, 'So hopefully these are still okay.', '希望这些大蒜还没坏。', '/soʊ hoʊpfəli ðiːz ɑːɹ stɪl oʊkeɪ./', '<span>So</span><span tid="19817" class="highlight highlight-a">hopefully</span><span>these</span><span>are</span><span tid="19820">still</span><span>okay.</span>'
