INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 56.4, 58.08, 'Ooh, those are looking nice.', '哦，这些看起来不错。', '/uː, ðoʊz ɑːɹ lʊkɪŋ naɪs./', '<span tid="19822">Ooh,</span><span>those</span><span>are</span><span tid="19825" class="highlight highlight-a">looking</span><span tid="19826">nice.</span>'
