INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 58.08, 69.18, 'Once hardneck garlic has the bottom three to four leaves brown, once they''re starting to brown, that is when you want to pull this stuff.', '硬皮大蒜的下三到四片叶子开始变黄时，就是你要采摘的时候。', '/wʌns hɑːɹdnɛk ɡɑːɹlɪk hɐz ðə bɑːɾəm θɹiː tə fɔːɹ liːvz bɹaʊn, wʌns ðeɪɚ stɑːɹɾɪŋ tə bɹaʊn, ðæt ɪz wɛn juː wɔnt tə pʊl ðɪs stʌf./', '<span tid="19827" class="highlight highlight-a">Once</span><span tid="19828">hardneck</span><span tid="19829" class="highlight highlight-a">garlic</span><span>has</span><span>the</span><span tid="19832">bottom</span><span>three</span><span>to</span><span>four</span><span tid="19836">leaves</span><span tid="19837">brown,</span><span tid="19838" class="highlight highlight-a">once</span><span>they''re</span><span tid="19840">starting</span><span>to</span><span tid="19842">brown,</span><span>that</span><span>is</span><span>when</span><span>you</span><span>want</span><span>to</span><span tid="19849">pull</span><span>this</span><span tid="19851" class="highlight highlight-a">stuff.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 69.18, 70.84, 'If you leave it out too long.', '如果你让它们留太久，', '/ɪf juː liːv ɪɾ aʊt tuː lɔŋ./', '<span>If</span><span>you</span><span tid="19854">leave</span><span>it</span><span tid="19856">out</span><span>too</span><span tid="19858">long.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 70.84, 75.62, 'there can be some rotting and damage and splitting open of the garlic heads.', '可能会出现腐烂、损坏和大蒜头裂开的情况。', '/ðɛɹ kæn biː sʌm ɹɑːɾɪŋ ænd dæmɪdʒ ænd splɪɾɪŋ oʊpən ʌvðə ɡɑːɹlɪk hɛdz./', '<span>there</span><span>can</span><span>be</span><span>some</span><span tid="19863">rotting</span><span>and</span><span tid="19865" class="highlight highlight-a">damage</span><span>and</span><span tid="19867" class="highlight highlight-a">splitting</span><span tid="19868">open</span><span>of</span><span>the</span><span tid="19871" class="highlight highlight-a">garlic</span><span tid="19872">heads.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 75.62, 77.1, 'These look like they''re fine though.', '不过这些看起来没问题。', '/ðiːz lʊk laɪk ðeɪɚ faɪn ðoʊ./', '<span>These</span><span tid="19874" class="highlight highlight-a">look</span><span>like</span><span>they''re</span><span tid="19877" class="highlight highlight-a">fine</span><span tid="19878">though.</span>'
