INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 77.1, 81.66, 'It''s definitely best to harvest garlic when it''s drier outside.', '采摘大蒜最好是在外面干燥的时候。', '/ɪts dɛfɪnətli bɛst tə hɑːɹvɪst ɡɑːɹlɪk wɛn ɪts dɹaɪɚɹ aʊtsaɪd./', '<span>It''s</span><span tid="19880" class="highlight highlight-a">definitely</span><span>best</span><span>to</span><span tid="19883" class="highlight highlight-a">harvest</span><span tid="19884" class="highlight highlight-a">garlic</span><span>when</span><span>it''s</span><span tid="19887">drier</span><span tid="19888">outside.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 21, 81.66, 84.62, 'but I''ve just been worrying about this garlic out here.', '但我一直担心这些大蒜。', '/bʌt aɪv dʒʌst bɪn wʌɹiɪŋ ɐbaʊt ðɪs ɡɑːɹlɪk aʊt hɪɹ./', '<span>but</span><span>I''ve</span><span>just</span><span>been</span><span tid="19893">worrying</span><span>about</span><span>this</span><span tid="19896" class="highlight highlight-a">garlic</span><span tid="19897">out</span><span>here.</span>'
