INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 160.72, 164.3, 'Secondly, I always plant onion plants, not sets.', '其次，我总是种洋葱苗，而不是洋葱球。', '/sɛkəndli, aɪ ɔːlweɪz plænt ʌniən plænts, nɑːt sɛts./', '<span tid="20071" class="highlight highlight-a">Secondly,</span><span>I</span><span tid="20073">always</span><span tid="20074" class="highlight highlight-a">plant</span><span tid="20075" class="highlight highlight-a">onion</span><span tid="20076" class="highlight highlight-a">plants,</span><span>not</span><span tid="20078" class="highlight highlight-a">sets.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 35, 164.3, 166.92, 'You don''t want to plant your onions too deep.', '你不想把洋葱种得太深。', '/juː doʊnt wɔnt tə plænt jʊɹ ʌniənz tuː diːp./', '<span>You</span><span>don''t</span><span>want</span><span>to</span><span tid="20083" class="highlight highlight-a">plant</span><span>your</span><span tid="20085" class="highlight highlight-a">onions</span><span>too</span><span tid="20087">deep.</span>'
