SELECT e.id, 90, 350.0, 353.8, 'I have been harvesting chamomile like sometimes twice a day.', '我已经开始一天采摘两次洋甘菊了。', '/aɪ hɐvbɪn hɑːɹvɪstɪŋ kæməmaɪl laɪk sʌmtaɪmz twaɪs ɐ deɪ./', '<span>I</span><span>have</span><span>been</span><span tid="20686" class="highlight highlight-a">harvesting</span><span tid="20687" class="highlight highlight-a">chamomile</span><span>like</span><span tid="20689">sometimes</span><span tid="20690">twice</span><span>a</span><span>day.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 91, 353.8, 356.64, 'It goes absolutely wild in the heat.', '它在热天气下会长得非常旺盛。', '/ɪt ɡoʊz æbsəluːtli waɪld ɪnðə hiːt./', '<span>It</span><span>goes</span><span tid="20695" class="highlight highlight-a">absolutely</span><span tid="20696" class="highlight highlight-a">wild</span><span>in</span><span>the</span><span tid="20699" class="highlight highlight-a">heat.</span>'
