INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 92, 356.64, 358.82, 'I got this really nifty gadget.', '我买了一个非常实用的小工具。', '/aɪ ɡɑːt ðɪs ɹiəli nɪfti ɡædʒɪt./', '<span>I</span><span>got</span><span>this</span><span tid="20703">really</span><span tid="20704" class="highlight highlight-a">nifty</span><span tid="20705" class="highlight highlight-a">gadget.</span>'
