INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 93, 358.82, 360.98, 'It''s called a berry picker.', '它叫做浆果采摘器。', '/ɪts kɔːld ɐ bɛɹi pɪkɚ./', '<span>It''s</span><span tid="20707">called</span><span>a</span><span tid="20709" class="highlight highlight-a">berry</span><span tid="20710">picker.</span>'
