INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 106, 414.8, 416.96, 'It was like covering the parsley.', '它差点把欧芹遮住了。', '/ɪt wʌz laɪk kʌvɚɹɪŋ ðə pɑːɹsli./', '<span>It</span><span>was</span><span>like</span><span tid="20889" class="highlight highlight-a">covering</span><span>the</span><span tid="20891" class="highlight highlight-a">parsley.</span>'
