INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 107, 416.96, 418.92, 'It was covering the lavender and the calendula.', '它也把薰衣草和金盏花都遮住了。', '/ɪt wʌz kʌvɚɹɪŋ ðə lævəndɚ ænd ðə kæləndʒuːlə./', '<span>It</span><span>was</span><span tid="20894" class="highlight highlight-a">covering</span><span>the</span><span tid="20896" class="highlight highlight-a">lavender</span><span>and</span><span>the</span><span pid="2479" class="highlight highlight-c">calendula.</span>'
