INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 108, 418.92, 420.72, 'So I just took a whole bunch of this out.', '所以我就把这部分剪掉了。', '/soʊ aɪ dʒʌst tʊk ɐ hoʊl bʌntʃ ʌv ðɪs aʊt./', '<span>So</span><span>I</span><span>just</span><span tid="20903">took</span><span>a</span><span tid="20905">whole</span><span tid="20906" class="highlight highlight-a">bunch</span><span>of</span><span>this</span><span tid="20909">out.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 109, 420.72, 422.62, 'Back here, I have oregano.', '在这里，我有一些牛至。', '/bæk hɪɹ, aɪ hæv ɔːɹɪɡɑːnoʊ./', '<span tid="20910" class="highlight highlight-a">Back</span><span>here,</span><span>I</span><span>have</span><span tid="20914" class="highlight highlight-a">oregano.</span>'
FROM episodes e WHERE e.video_id = '0595pA0eMk9MeYN';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 110, 422.62, 426.8, 'I''ve been harvesting this all spring already, and it''s starting to go to flower.', '我春天一直在收割它，它现在开始开花了。', '/aɪv bɪn hɑːɹvɪstɪŋ ðɪs ɔːl spɹɪŋ ɔːlɹɛdi, ænd ɪts stɑːɹɾɪŋ tə ɡoʊ tə flaʊɚ./', '<span>I''ve</span><span>been</span><span tid="20917" class="highlight highlight-a">harvesting</span><span>this</span><span>all</span><span tid="20920">spring</span><span tid="20921">already,</span><span>and</span><span>it''s</span><span tid="20924">starting</span><span>to</span><span>go</span><span>to</span><span tid="20928">flower.</span>'
