INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 112, 429.78, 433.08, 'These are amazing for tea.', '这些非常适合泡茶。', '/ðiːz ɑːɹ ɐmeɪzɪŋ fɔːɹ tiː./', '<span>These</span><span>are</span><span tid="20937">amazing</span><span>for</span><span tid="20939">tea.</span>'
