INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 113, 433.08, 435.36, 'They''re really good for cold and flu season.', '它们对感冒和流感季节非常有帮助。', '/ðeɪɚ ɹiəli ɡʊd fɔːɹ koʊld ænd fluː siːzən./', '<span>They''re</span><span tid="20941">really</span><span>good</span><span>for</span><span tid="20944" class="highlight highlight-a">cold</span><span>and</span><span tid="20946" class="highlight highlight-a">flu</span><span tid="20947">season.</span>'
