INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 118, 449.36, 455.04, 'I wish this stuff would get more of the buds, but it looks like it''s starting a little bit more.', '我希望它能多长出一些花蕾，但看起来它现在开始多了一点。', '/aɪ wɪʃ ðɪs stʌf wʊd ɡɛt mɔːɹ ʌvðə bʌdz, bʌt ɪt lʊks laɪk ɪts stɑːɹɾɪŋ ɐ lɪɾəl bɪt mɔːɹ./', '<span>I</span><span tid="20993">wish</span><span>this</span><span tid="20995" class="highlight highlight-a">stuff</span><span>would</span><span>get</span><span>more</span><span>of</span><span>the</span><span tid="21001" class="highlight highlight-a">buds,</span><span>but</span><span>it</span><span tid="21004" class="highlight highlight-a">looks</span><span>like</span><span>it''s</span><span tid="21007">starting</span><span>a</span><span tid="21009">little</span><span tid="21010">bit</span><span>more.</span>'
