INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 120, 458.88, 463.64, 'And I''m hoping that maybe next year I can have a second herb garden.', '我希望明年我能再种一个草药花园。', '/ænd aɪm hoʊpɪŋ ðæt meɪbiː nɛkst jɪɹ aɪ kæn hæv ɐ sɛkənd ɜːb ɡɑːɹdən./', '<span>And</span><span>I''m</span><span tid="21023">hoping</span><span>that</span><span tid="21025">maybe</span><span tid="21026">next</span><span tid="21027">year</span><span>I</span><span>can</span><span>have</span><span>a</span><span tid="21032">second</span><span tid="21033" class="highlight highlight-a">herb</span><span tid="21034" class="highlight highlight-a">garden.</span>'
