INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 2.96, 'My name''s Aaron, we''ve got a property here in North Eastern Australia.', '我叫Aaron，我们在澳大利亚东北部有一处房产。', '/maɪ neɪmz ɛɹən, wiːv ɡɑːt ɐ pɹɑːpɚɾi hɪɹ ɪn nɔːɹθ iːstɚn ɔːstɹeɪliə./', '<span>My</span><span tid="18658">name''s</span><span tid="18659">Aaron,</span><span>we''ve</span><span>got</span><span>a</span><span tid="18663" class="highlight highlight-a">property</span><span>here</span><span>in</span><span tid="18666">North</span><span tid="18667">Eastern</span><span tid="18668">Australia.</span>'
FROM episodes e WHERE e.video_id = '0600o9ORMa5PmRs';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 2.96, 7.82, 'It''s very tropical and I want to share with you our journey of being as self-sufficient as possible.', '这里非常热带，我想和大家分享我们尽可能自给自足的旅程。', '/ɪts vɛɹi tɹɑːpɪkəl ænd aɪ wɔnt tə ʃɛɹ wɪð juː aʊɚ dʒɜːni ʌv biːɪŋ æz sɛlf səfɪʃənt æz pɑːsᵻbəl./', '<span>It''s</span><span>very</span><span tid="18671" class="highlight highlight-a">tropical</span><span>and</span><span>I</span><span>want</span><span>to</span><span tid="18676" class="highlight highlight-a">share</span><span>with</span><span>you</span><span>our</span><span tid="18680">journey</span><span>of</span><span>being</span><span>as</span><span tid="18684" class="highlight highlight-a">self-sufficient</span><span>as</span><span tid="18686">possible.</span>'
FROM episodes e WHERE e.video_id = '0600o9ORMa5PmRs';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 7.82, 11.98, 'We''ve got our own animals, we''ve got our own orchard, we''ve got the veggie patch behind me here.', '我们养了自己的动物，拥有自己的果园，后面有菜园。', '/wiːv ɡɑːt aʊɚɹ oʊn ænɪməlz, wiːv ɡɑːt aʊɚɹ oʊn ɔːɹtʃɚd, wiːv ɡɑːt ðə vɛdʒi pætʃ bᵻhaɪnd miː hɪɹ./', '<span>We''ve</span><span>got</span><span>our</span><span tid="18690" class="highlight highlight-a">own</span><span tid="18691">animals,</span><span>we''ve</span><span>got</span><span>our</span><span tid="18695" class="highlight highlight-a">own</span><span tid="18696" class="highlight highlight-a">orchard,</span><span>we''ve</span><span>got</span><span>the</span><span tid="18700" class="highlight highlight-a">veggie</span><span tid="18701" class="highlight highlight-a">patch</span><span tid="18702">behind</span><span>me</span><span>here.</span>'
FROM episodes e WHERE e.video_id = '0600o9ORMa5PmRs';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 11.98, 15.84, 'We try and catch and source all of our own protein from the ocean and the land.', '我们的蛋白质来源基本上都是海洋和这篇土地。', '/wiː tɹaɪ ænd kætʃ ænd sɔːɹs ɔːl ʌv aʊɚɹ oʊn pɹoʊtiːn fɹʌmðɪ oʊʃən ænd ðə lænd./', '<span>We</span><span tid="18706">try</span><span>and</span><span tid="18708">catch</span><span>and</span><span tid="18710" class="highlight highlight-a">source</span><span>all</span><span>of</span><span>our</span><span tid="18714" class="highlight highlight-a">own</span><span tid="18715" class="highlight highlight-a">protein</span><span>from</span><span>the</span><span tid="18718">ocean</span><span>and</span><span>the</span><span tid="18721" class="highlight highlight-a">land.</span>'
FROM episodes e WHERE e.video_id = '0600o9ORMa5PmRs';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 15.84, 20.22, 'and we also have a cafe which I''ll show you over there and some of the animals at the end.', '我们还有一家咖啡馆，我稍后会带你们去看，还有一些动物。', '/ænd wiː ɔːlsoʊ hæv ɐ kæfeɪ wɪtʃ aɪl ʃoʊ juː oʊvɚ ðɛɹ ænd sʌm ʌvðɪ ænɪməlz æt ðɪ ɛnd./', '<span>and</span><span>we</span><span>also</span><span>have</span><span>a</span><span tid="18727">cafe</span><span>which</span><span>I''ll</span><span tid="18730">show</span><span>you</span><span tid="18732">over</span><span>there</span><span>and</span><span>some</span><span>of</span><span>the</span><span tid="18738">animals</span><span>at</span><span>the</span><span tid="18741">end.</span>'
FROM episodes e WHERE e.video_id = '0600o9ORMa5PmRs';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 20.22, 23.88, 'Let''s go for a journey, it''s been four and a half years and I want to share it with you guys.', '让我们开始旅程吧，已经四年半了，我想和大家分享。', '/lɛts ɡoʊ fɚɹə dʒɜːni, ɪts bɪn fɔːɹ ænd ɐ hæf jɪɹz ænd aɪ wɔnt tə ʃɛɹ ɪt wɪð juː ɡaɪz./', '<span>Let''s</span><span>go</span><span>for</span><span>a</span><span tid="18746">journey,</span><span>it''s</span><span>been</span><span>four</span><span>and</span><span>a</span><span tid="18752">half</span><span tid="18753">years</span><span>and</span><span>I</span><span>want</span><span>to</span><span tid="18758" class="highlight highlight-a">share</span><span>it</span><span>with</span><span>you</span><span tid="18762">guys.</span>'
FROM episodes e WHERE e.video_id = '0600o9ORMa5PmRs';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 23.88, 24.72, 'Let''s go for a walk.', '我们去逛逛吧。', '/lɛts ɡoʊ fɚɹə wɔːk./', '<span>Let''s</span><span>go</span><span>for</span><span>a</span><span tid="18767">walk.</span>'
