INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 63.74, 69.7, 'We''ve got mint that''s acting as a bit of a ground cover through the three different beds that we''ve got.', '我们种了薄荷，在我们三个菜床上起到了覆盖地面的作用。', '/wiːv ɡɑːt mɪnt ðæts æktɪŋ æz ɐ bɪt əvə ɡɹaʊnd kʌvɚ θɹuː ðə θɹiː dɪfɹənt bɛdz ðæt wiːv ɡɑːt./', '<span>We''ve</span><span>got</span><span tid="18922" class="highlight highlight-a">mint</span><span>that''s</span><span tid="18924" class="highlight highlight-a">acting</span><span>as</span><span>a</span><span tid="18927">bit</span><span>of</span><span>a</span><span tid="18930" class="highlight highlight-a">ground</span><span tid="18931" class="highlight highlight-a">cover</span><span tid="18932">through</span><span>the</span><span>three</span><span tid="18935">different</span><span tid="18936" class="highlight highlight-a">beds</span><span>that</span><span>we''ve</span><span>got.</span>'
FROM episodes e WHERE e.video_id = '0600o9ORMa5PmRs';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 69.7, 73.9, 'We''ve got broccoli, lots and lots of different chillies.', '我们还种了西兰花，还有很多不同种类的辣椒。', '/wiːv ɡɑːt bɹɑːkəli, lɑːts ænd lɑːts ʌv dɪfɹənt tʃɪliz./', '<span>We''ve</span><span>got</span><span tid="18942" class="highlight highlight-a">broccoli,</span><span tid="18943">lots</span><span>and</span><span tid="18945">lots</span><span>of</span><span tid="18947">different</span><span tid="18948" class="highlight highlight-a">chillies.</span>'
