INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 73.9, 81.08, 'We''ve got here a really beautiful one, it is a rosella, the rosella flower.', '这里这个很好看，这是洛神花。', '/wiːv ɡɑːt hɪɹ ɐ ɹiəli bjuːɾifəl wʌn, ɪɾ ɪz ɐ ɹoʊzɛlə, ðə ɹoʊzɛlə flaʊɚ./', '<span>We''ve</span><span>got</span><span>here</span><span>a</span><span tid="18953">really</span><span tid="18954">beautiful</span><span>one,</span><span>it</span><span>is</span><span>a</span><span tid="18959" class="highlight highlight-a">rosella,</span><span>the</span><span tid="18961" class="highlight highlight-a">rosella</span><span tid="18962">flower.</span>'
