INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 81.08, 86.16, 'They''re beautiful to make teas out of the petal and also you can make beautiful chutneys.', '它们非常美丽，可以用花瓣做茶，也可以做美味的酸辣酱。', '/ðeɪɚ bjuːɾifəl tə meɪk tiːz aʊɾəv ðə pɛɾəl ænd ɔːlsoʊ juː kæn meɪk bjuːɾifəl tʃʌtniz./', '<span>They''re</span><span tid="18964">beautiful</span><span>to</span><span tid="18966">make</span><span tid="18967">teas</span><span tid="18968">out</span><span>of</span><span>the</span><span tid="18971" class="highlight highlight-a">petal</span><span>and</span><span>also</span><span>you</span><span>can</span><span tid="18976">make</span><span tid="18977">beautiful</span><span tid="18978" class="highlight highlight-a">chutneys.</span>'
