INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 21, 86.16, 91.94, 'We''ve really focused on this year getting a lot of different varieties of tomatoes.', '今年我们特别专注于种植多种不同的番茄。', '/wiːv ɹiəli foʊkəst ɔn ðɪs jɪɹ ɡɛɾɪŋ ɐ lɑːt ʌv dɪfɹənt vɚɹaɪəɾiz ʌv təmeɪɾoʊz./', '<span>We''ve</span><span tid="18980">really</span><span tid="18981">focused</span><span>on</span><span>this</span><span tid="18984">year</span><span>getting</span><span>a</span><span tid="18987">lot</span><span>of</span><span tid="18989">different</span><span tid="18990" class="highlight highlight-a">varieties</span><span>of</span><span tid="18992" class="highlight highlight-a">tomatoes.</span>'
