INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 33, 151.44, 158.7, 'At the cafe that we have called the Pocket Cafe here in Alarish, it''s on the main highway as you head up the east coast of Australia.', '在我们位于Alarish的Pocket Cafe咖啡馆，位于澳大利亚东海岸的主干道上。', '/æt ðə kæfeɪ ðæt wiː hæv kɔːld ðə pɑːkɪt kæfeɪ hɪɹ ɪn ɐlɑːɹɹɪʃ, ɪts ɔnðə meɪn haɪweɪ æz juː hɛd ʌp ðɪ iːst koʊst ʌv ɔːstɹeɪliə./', '<span>At</span><span>the</span><span tid="19149">cafe</span><span>that</span><span>we</span><span>have</span><span tid="19153">called</span><span>the</span><span tid="19155">Pocket</span><span tid="19156">Cafe</span><span>here</span><span>in</span><span tid="19159">Alarish,</span><span>it''s</span><span>on</span><span>the</span><span tid="19163">main</span><span tid="19164" class="highlight highlight-a">highway</span><span>as</span><span>you</span><span pid="1326" class="highlight highlight-d">head up</span><span>the</span><span tid="19170">east</span><span tid="19171" class="highlight highlight-a">coast</span><span>of</span><span tid="19173">Australia.</span>'
