INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 50, 247.98, 254.54, 'but we''re going to leave that hang there, let it go brown and we''ll use the seed out of this when we plant more.', '但我们会把它留下，等它变干，我们会用这个种子来种更多的四角豆。', '/bʌt wɪɹ ɡoʊɪŋ tə liːv ðæt hæŋ ðɛɹ, lɛt ɪt ɡoʊ bɹaʊn ænd wiːl juːz ðə siːd aʊɾəv ðɪs wɛn wiː plænt mɔːɹ./', '<span>but</span><span>we''re</span><span>going</span><span>to</span><span tid="19390">leave</span><span>that</span><span tid="19392" class="highlight highlight-a">hang</span><span>there,</span><span>let</span><span>it</span><span>go</span><span tid="19397">brown</span><span>and</span><span>we''ll</span><span tid="19400">use</span><span>the</span><span tid="19402" class="highlight highlight-a">seed</span><span tid="19403">out</span><span>of</span><span>this</span><span>when</span><span>we</span><span tid="19408" class="highlight highlight-a">plant</span><span>more.</span>'
