INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 4.42, 6.7, 'We''re good? Okay. All right.', '我们准备好了吗？好，开始吧。', '/wɪɹ ɡʊd? oʊkeɪ. ɔːl ɹaɪt./', '<span>We''re</span><span>good?</span><span>Okay.</span><span>All</span><span tid="129591" class="highlight highlight-a">right.</span>'
