INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 6.7, 10.12, 'Welcome to all of you today. My name is Mike Nazareth.', '大家好，欢迎你们的到来。我叫Mike Nazareth。', '/wɛlkʌm tʊ ɔːl ʌv juː tədeɪ. maɪ neɪm ɪz maɪk næzɚɹəθ./', '<span tid="129592">Welcome</span><span>to</span><span>all</span><span>of</span><span>you</span><span tid="129597">today.</span><span>My</span><span tid="129599">name</span><span>is</span><span tid="129601">Mike</span><span tid="129602">Nazareth.</span>'
