INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 10.34, 16.32, 'I direct graduate recruiting here for new master''s and PhD students for University of Florida.', '我是佛罗里达大学研究生招生的负责人，负责新硕士和博士生的招生工作。', '/aɪ dᵻɹɛkt ɡɹædʒuːət ɹᵻkɹuːɾɪŋ hɪɹ fɔːɹ nuː mæstɚz ænd piːeɪtʃ diː stuːdənts fɔːɹ juːnɪvɜːsᵻɾi ʌv flɔːɹɪdə./', '<span>I</span><span tid="129604" class="highlight highlight-a">direct</span><span tid="129605" class="highlight highlight-a">graduate</span><span tid="129606" class="highlight highlight-a">recruiting</span><span>here</span><span>for</span><span tid="129609">new</span><span tid="129610" class="highlight highlight-a">master''s</span><span>and</span><span tid="129612" class="highlight highlight-a">PhD</span><span tid="129613">students</span><span>for</span><span tid="129615">University</span><span>of</span><span tid="129617">Florida.</span>'
FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 16.78, 24.3, 'You''ve probably heard from me a great deal in email messaging or application fee waivers or previous webinars that you''ve attended.', '你们可能已经通过电子邮件、申请费减免或之前参加的网络研讨会听到过我的消息。', '/juːv pɹɑːbəbli hɜːd fɹʌm miː ɐ ɡɹeɪt diːl ɪn iːmeɪl mɛsɪdʒɪŋ ɔːɹ æplɪkeɪʃən fiː weɪvɚz ɔːɹ pɹiːviəs wɛbɪnɑːɹz ðæt juːv ɐtɛndᵻd./', '<span>You''ve</span><span tid="129619" class="highlight highlight-a">probably</span><span pid="1558" class="highlight highlight-c">heard from</span><span>me</span><span pid="1561" class="highlight highlight-i">a great deal</span><span>in</span><span tid="129627">email</span><span tid="129628">messaging</span><span>or</span><span pid="1562" class="highlight highlight-c">application fee</span><span tid="129632" class="highlight highlight-a">waivers</span><span>or</span><span tid="129634" class="highlight highlight-a">previous</span><span tid="129635" class="highlight highlight-a">webinars</span><span>that</span><span>you''ve</span><span tid="129638" class="highlight highlight-a">attended.</span>'
FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 24.48, 28.6, 'So welcome. We''re very excited and delighted that you''re here today.', '欢迎大家，我们非常高兴并且很高兴你们今天能来。', '/soʊ wɛlkʌm. wɪɹ vɛɹi ɛksaɪɾᵻd ænd dᵻlaɪɾᵻd ðæt jʊɹ hɪɹ tədeɪ./', '<span>So</span><span tid="129640">welcome.</span><span>We''re</span><span>very</span><span tid="129643">excited</span><span>and</span><span tid="129645" class="highlight highlight-a">delighted</span><span>that</span><span>you''re</span><span>here</span><span tid="129649">today.</span>'
FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 29.24, 33.56, 'All of you have been admitted for the fall 2025 term.', '你们都已被录取为2025年秋季学期的学生。', '/ɔːl ʌv juː hɐvbɪn ɐdmɪɾᵻd fɚðə fɔːl tuː θaʊzənd twɛnti faɪv tɜːm./', '<span>All</span><span>of</span><span>you</span><span>have</span><span>been</span><span tid="129655" class="highlight highlight-a">admitted</span><span>for</span><span>the</span><span tid="129658">fall</span><span>2025</span><span tid="129660" class="highlight highlight-a">term.</span>'
FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 34.14, 42.58, 'There''s a few of you that have been admitted for the summer term, and a few students do start in the summer or switch that over and start in the fall term.', '其中有一些同学被录取为夏季学期，部分学生会选择夏季入学，或转到秋季学期开始。', '/ðɛɹz ɐ fjuː ʌv juː ðæt hɐvbɪn ɐdmɪɾᵻd fɚðə sʌmɚ tɜːm, ænd ɐ fjuː stuːdənts duː stɑːɹt ɪnðə sʌmɚ ɔːɹ swɪtʃ ðæt oʊvɚ ænd stɑːɹt ɪnðə fɔːl tɜːm./', '<span>There''s</span><span>a</span><span tid="129663">few</span><span>of</span><span>you</span><span>that</span><span>have</span><span>been</span><span tid="129669" class="highlight highlight-a">admitted</span><span>for</span><span>the</span><span tid="129672">summer</span><span tid="129673" class="highlight highlight-a">term,</span><span>and</span><span>a</span><span tid="129676">few</span><span tid="129677">students</span><span>do</span><span tid="129679">start</span><span>in</span><span>the</span><span tid="129682">summer</span><span>or</span><span pid="1563" class="highlight highlight-d">switch that over</span><span>and</span><span tid="129688">start</span><span>in</span><span>the</span><span tid="129691">fall</span><span tid="129692" class="highlight highlight-a">term.</span>'
FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 43.0, 47.48, 'We have lots of master''s students that have been admitted that are online today.', '今天有许多被录取的硕士生在线参加。', '/wiː hæv lɑːts ʌv mæstɚ stuːdənts ðæt hɐvbɪn ɐdmɪɾᵻd ðæt ɑːɹ ɑːnlaɪn tədeɪ./', '<span>We</span><span>have</span><span tid="129695">lots</span><span>of</span><span tid="129697" class="highlight highlight-a">master''s</span><span tid="129698">students</span><span>that</span><span>have</span><span>been</span><span tid="129702" class="highlight highlight-a">admitted</span><span>that</span><span>are</span><span tid="129705">online</span><span tid="129706">today.</span>'
