INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 47.82, 53.5, 'These are both master''s students, some that are already at University of Florida in their undergrad.', '这些学生中，有些是已经在佛罗里达大学读本科的硕士生，', '/ðiːz ɑːɹ boʊθ mæstɚ stuːdənts, sʌm ðæt ɑːɹ ɔːlɹɛdi æt juːnɪvɜːsᵻɾi ʌv flɔːɹɪdə ɪn ðɛɹ ʌndɚɡɹæd./', '<span>These</span><span>are</span><span tid="129709">both</span><span tid="129710" class="highlight highlight-a">master''s</span><span tid="129711">students,</span><span>some</span><span>that</span><span>are</span><span tid="129715">already</span><span>at</span><span tid="129717">University</span><span>of</span><span tid="129719">Florida</span><span>in</span><span>their</span><span tid="129722">undergrad.</span>'
