INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 10, 53.9, 57.9, 'others from across the state of Florida or across the United States.', '有些则来自佛罗里达州或美国其他地区。', '/ʌðɚz fɹʌm əkɹɑːs ðə steɪt ʌv flɔːɹɪdə ɔːɹ əkɹɑːs ðə juːnaɪɾᵻd steɪts./', '<span tid="129723">others</span><span>from</span><span tid="129725">across</span><span>the</span><span tid="129727">state</span><span>of</span><span tid="129729">Florida</span><span>or</span><span tid="129731">across</span><span>the</span><span tid="129733">United</span><span tid="129734">States.</span>'
