INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 58.04, 62.8, 'and then many international students that are with us today that have been admitted.', '今天还有许多国际学生也已被录取。', '/ænd ðɛn mɛni ɪntɚnæʃənəl stuːdənts ðæt ɑːɹ wɪð ʌs tədeɪ ðæt hɐvbɪn ɐdmɪɾᵻd./', '<span>and</span><span>then</span><span>many</span><span tid="129738" class="highlight highlight-a">international</span><span tid="129739">students</span><span>that</span><span>are</span><span>with</span><span>us</span><span tid="129744">today</span><span>that</span><span>have</span><span>been</span><span tid="129748" class="highlight highlight-a">admitted.</span>'
FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 63.3, 66.7, 'We also have PhD students that have been admitted online.', '我们也有一些已被录取的博士生在线参加。', '/wiː ɔːlsoʊ hæv piːeɪtʃ diː stuːdənts ðæt hɐvbɪn ɐdmɪɾᵻd ɑːnlaɪn./', '<span>We</span><span>also</span><span>have</span><span tid="129752" class="highlight highlight-a">PhD</span><span tid="129753">students</span><span>that</span><span>have</span><span>been</span><span tid="129757" class="highlight highlight-a">admitted</span><span tid="129758">online.</span>'
