FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 75.14, 76.68, 'So welcome to all of you.', '所以，欢迎大家。', '/soʊ wɛlkʌm tʊ ɔːl ʌv juː./', '<span>So</span><span tid="129785">welcome</span><span>to</span><span>all</span><span>of</span><span>you.</span>'
