INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 76.76, 78.6, 'We''re delighted that you''re here with us.', '我们非常高兴你们在这里。', '/wɪɹ dᵻlaɪɾᵻd ðæt jʊɹ hɪɹ wɪð ʌs./', '<span>We''re</span><span tid="129791" class="highlight highlight-a">delighted</span><span>that</span><span>you''re</span><span>here</span><span>with</span><span>us.</span>'
