INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 78.9, 84.88, 'I know that some of you have already made your decision, and you are planning to enroll at University of Florida.', '我知道其中一些同学已经做出了决定，计划在佛罗里达大学入学。', '/aɪ noʊ ðæt sʌm ʌv juː hæv ɔːlɹɛdi meɪd jʊɹ dᵻsɪʒən, ænd juː ɑːɹ plænɪŋ tʊ ɛnɹoʊl æt juːnɪvɜːsᵻɾi ʌv flɔːɹɪdə./', '<span>I</span><span>know</span><span>that</span><span>some</span><span>of</span><span>you</span><span>have</span><span tid="129804">already</span><span pid="1565" class="highlight highlight-c">made your decision,</span><span>and</span><span>you</span><span>are</span><span tid="129811">planning</span><span>to</span><span tid="129813" class="highlight highlight-a">enroll</span><span>at</span><span tid="129815">University</span><span>of</span><span tid="129817">Florida.</span>'
