INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 88.08, 90.3, 'And others of you are still deciding.', '而你们中的其他人还在做决定。', '/ænd ʌðɚz ʌv juː ɑːɹ stɪl dᵻsaɪdɪŋ./', '<span>And</span><span tid="129826">others</span><span>of</span><span>you</span><span>are</span><span tid="129830">still</span><span tid="129831">deciding.</span>'
FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 90.64, 92.88, 'You''ve been admitted to a few schools.', '你们已经被几所学校录取，', '/juːv bɪn ɐdmɪɾᵻd tʊ ɐ fjuː skuːlz./', '<span>You''ve</span><span>been</span><span tid="129834" class="highlight highlight-a">admitted</span><span>to</span><span>a</span><span tid="129837">few</span><span tid="129838" class="highlight highlight-a">schools.</span>'
