INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 38, 214.54, 221.44, 'I think she has live video going on, but her voice is off, so you will not hear from Krista today.', '我想她现在正在开视频，但她的麦克风没有开启，所以今天你们不会听到她的声音。', '/aɪ θɪŋk ʃiː hɐz laɪv vɪdɪoʊ ɡoʊɪŋ ɔn, bʌt hɜː vɔɪs ɪz ɔf, soʊ juː wɪl nɑːt hɪɹ fɹʌm kɹɪstə tədeɪ./', '<span>I</span><span>think</span><span>she</span><span>has</span><span tid="130181">live</span><span tid="130182">video</span><span>going</span><span>on,</span><span>but</span><span>her</span><span tid="130187">voice</span><span>is</span><span tid="130189">off,</span><span>so</span><span>you</span><span>will</span><span>not</span><span pid="1560" class="highlight highlight-c">hear from</span><span tid="130196">Krista</span><span tid="130197">today.</span>'
FROM episodes e WHERE e.video_id = '061fmrxTaOJJFpl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
