INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 26, 122.86, 125.42, 'It was just like too much stuff, you know?', '就像东西太多了，你知道吗？', '/ɪt wʌz dʒʌst laɪk tuː mʌtʃ stʌf, juː noʊ?/', '<span>It</span><span>was</span><span>just</span><span>like</span><span>too</span><span tid="128167">much</span><span tid="128168" class="highlight highlight-a">stuff,</span><span>you</span><span>know?</span>'
FROM episodes e WHERE e.video_id = '062xBDIp6AU5JcM';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 27, 125.42, 131.72, 'And so it''s safe to say that I''ve made some regrettable purchases in my life.', '所以可以说，我的确做出了一些让我后悔的购买。', '/ænd soʊ ɪts seɪf tə seɪ ðæt aɪv meɪd sʌm ɹᵻɡɹɛɾəbəl pɜːtʃɪsᵻz ɪn maɪ laɪf./', '<span>And</span><span>so</span><span pid="202" class="highlight highlight-l">it''s safe to say</span><span>that</span><span>I''ve</span><span tid="128179">made</span><span>some</span><span tid="128181" class="highlight highlight-a">regrettable</span><span tid="128182" class="highlight highlight-a">purchases</span><span>in</span><span>my</span><span tid="128185">life.</span>'
