INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 165.88, 171.4, 'From casual hangs to vacation, Walmart''s the place to find all your summer pieces.', '从休闲聚会到度假，沃尔玛是你找到所有夏季单品的地方。', '/fɹʌm kæʒuːəl hæŋz tə veɪkeɪʃən, wɔlmɑːɹts ðə pleɪs tə faɪnd ɔːl jʊɹ sʌmɚ piːsᵻz./', '<span>From</span><span tid="128280" class="highlight highlight-a">casual</span><span tid="128281" class="highlight highlight-a">hangs</span><span>to</span><span tid="128283" class="highlight highlight-a">vacation,</span><span tid="128284" class="highlight highlight-a">Walmart''s</span><span>the</span><span tid="128286">place</span><span>to</span><span tid="128288">find</span><span>all</span><span>your</span><span pid="205" class="highlight highlight-c">summer pieces.</span>'
