INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 40, 192.62, 195.16, 'there''s always a chance that I could fall back into it.', '但我始终有可能重新陷入其中。', '/ðɛɹz ɔːlweɪz ɐ tʃæns ðæt aɪ kʊd fɔːl bæk ɪntʊ ɪt./', '<span pid="206" class="highlight highlight-l">there''s always a chance that</span><span>I</span><span>could</span><span pid="207" class="highlight highlight-d">fall back into</span><span>it.</span>'
