INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 42, 198.3, 201.78, 'But also you might be thinking about buying some of these things.', '但你们可能也在考虑买一些这些东西。', '/bʌt ɔːlsoʊ juː maɪt biː θɪŋkɪŋ ɐbaʊt baɪɪŋ sʌm ʌv ðiːz θɪŋz./', '<span>But</span><span>also</span><span>you</span><span tid="128363" class="highlight highlight-a">might</span><span>be</span><span>thinking</span><span>about</span><span tid="128367">buying</span><span>some</span><span>of</span><span>these</span><span>things.</span>'
