INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 46, 219.98, 226.52, 'Like maybe I don''t even seem weird, but I feel weird because there''s like a chemical change happening in my body.', '可能我看起来并不奇怪，但我自己感觉很奇怪，因为我的身体里发生了化学变化。', '/laɪk meɪbiː aɪ doʊnt iːvən siːm wɪɹd, bʌt aɪ fiːl wɪɹd bɪkʌz ðɛɹz laɪk ɐ kɛmɪkəl tʃeɪndʒ hæpənɪŋ ɪn maɪ bɑːdi./', '<span>Like</span><span tid="128431">maybe</span><span>I</span><span>don''t</span><span tid="128434">even</span><span tid="128435" class="highlight highlight-a">seem</span><span tid="128436" class="highlight highlight-a">weird,</span><span>but</span><span>I</span><span tid="128439">feel</span><span tid="128440" class="highlight highlight-a">weird</span><span>because</span><span>there''s</span><span>like</span><span>a</span><span tid="128445" class="highlight highlight-a">chemical</span><span tid="128446">change</span><span tid="128447">happening</span><span>in</span><span>my</span><span tid="128450">body.</span>'
FROM episodes e WHERE e.video_id = '062xBDIp6AU5JcM';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
