INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 92, 426.48, 429.12, 'And the Gucci belt was kind of cool for a second there.', '那条Gucci皮带曾经一度挺酷的。', '/ænd ðə ɡuːtʃi bɛlt wʌz kaɪnd ʌv kuːl fɚɹə sɛkənd ðɛɹ./', '<span>And</span><span>the</span><span tid="129062" class="highlight highlight-a">Gucci</span><span tid="129063" class="highlight highlight-a">belt</span><span>was</span><span tid="129065">kind</span><span>of</span><span tid="129067" class="highlight highlight-a">cool</span><span pid="234" class="highlight highlight-c">for a second</span><span>there.</span>'
