FROM episodes e WHERE e.video_id = '062xBDIp6AU5JcM';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 103, 473.7, 480.32, 'I like the idea of putting an outfit together and people, instead of looking at it and thinking to themselves.', '我喜欢把一套衣服搭配起来，让别人看了后，不是想：', '/aɪ laɪk ðɪ aɪdiə ʌv pʊɾɪŋ ɐn aʊtfɪt təɡɛðɚ ænd piːpəl, ɪnstɛd ʌv lʊkɪŋ æɾ ɪt ænd θɪŋkɪŋ tə ðɛmsɛlvz./', '<span pid="236" class="highlight highlight-l">I like the idea of</span><span pid="192" class="highlight highlight-d">putting an outfit together</span><span>and</span><span tid="129218">people,</span><span tid="129219" class="highlight highlight-a">instead</span><span>of</span><span tid="129221" class="highlight highlight-a">looking</span><span>at</span><span>it</span><span>and</span><span pid="213" class="highlight highlight-i">thinking to themselves.</span>'
