INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 105, 484.12, 488.34, 'I want people to look at my outfit and think, oh, that''s really cool.', '我希望别人看我的衣服时会想，哦，这真酷。', '/aɪ wɔnt piːpəl tə lʊk æt maɪ aʊtfɪt ænd θɪŋk, oʊ, ðæts ɹiəli kuːl./', '<span>I</span><span>want</span><span tid="129246">people</span><span>to</span><span tid="129248" class="highlight highlight-a">look</span><span>at</span><span>my</span><span tid="129251" class="highlight highlight-a">outfit</span><span>and</span><span>think,</span><span>oh,</span><span>that''s</span><span tid="129256">really</span><span tid="129257" class="highlight highlight-a">cool.</span>'
