INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 112, 505.84, 512.24, 'But also I don''t want my sense of style to have anything to do with how much things cost either.', '但我也不希望我的穿搭风格和东西的价格有任何关系。', '/bʌt ɔːlsoʊ aɪ doʊnt wɔnt maɪ sɛns ʌv staɪl tə hæv ɛnɪθɪŋ tə duː wɪð haʊ mʌtʃ θɪŋz kɔst iːðɚ./', '<span>But</span><span>also</span><span>I</span><span>don''t</span><span>want</span><span>my</span><span pid="238" class="highlight highlight-c">sense of style</span><span>to</span><span>have</span><span pid="197" class="highlight highlight-c">anything to do with</span><span>how</span><span tid="129322">much</span><span>things</span><span tid="129324">cost</span><span tid="129325">either.</span>'
