INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 114, 516.96, 521.58, 'And I don''t want my fashion sense to be about that.', '但我不希望我的时尚感是基于这个的。', '/ænd aɪ doʊnt wɔnt maɪ fæʃən sɛns təbi ɐbaʊt ðæt./', '<span>And</span><span>I</span><span>don''t</span><span>want</span><span>my</span><span tid="129352" class="highlight highlight-a">fashion</span><span tid="129353" class="highlight highlight-a">sense</span><span>to</span><span>be</span><span>about</span><span>that.</span>'
