INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 120, 546.14, 549.8, 'you guys probably know what I''m talking about, but you get the idea though.', '你们大概知道我说的是什么，但你们明白我的意思。', '/juː ɡaɪz pɹɑːbəbli noʊ wʌt aɪm tɔːkɪŋ ɐbaʊt, bʌt juː ɡɛt ðɪ aɪdiə ðoʊ./', '<span>you</span><span tid="129447">guys</span><span tid="129448" class="highlight highlight-a">probably</span><span>know</span><span>what</span><span>I''m</span><span tid="129452">talking</span><span>about,</span><span>but</span><span>you</span><span>get</span><span>the</span><span tid="129458">idea</span><span tid="129459">though.</span>'
