INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 27.84, 34.18, 'She is the spoiled little rich girl with an amazing wardrobe who is starting life afresh.', '她是那个被宠坏的富家女孩，拥有一个令人惊叹的衣橱，正在重新开始她的生活。', '/ʃiː ɪz ðə spɔɪld lɪɾəl ɹɪtʃ ɡɜːl wɪð ɐn ɐmeɪzɪŋ wɔːɹdɹoʊb huː ɪz stɑːɹɾɪŋ laɪf ɐfɹɛʃ./', '<span>She</span><span>is</span><span>the</span><span tid="125589" class="highlight highlight-a">spoiled</span><span tid="125590">little</span><span tid="125591">rich</span><span tid="125592">girl</span><span>with</span><span>an</span><span tid="125595">amazing</span><span tid="125596" class="highlight highlight-a">wardrobe</span><span>who</span><span>is</span><span tid="125599">starting</span><span tid="125600">life</span><span tid="125601" class="highlight highlight-a">afresh.</span>'
