INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 34.18, 36.96, 'It''s just an ordinary girl making it on her own.', '她只是一个普通女孩，靠自己打拼。', '/ɪts dʒʌst ɐn ɔːɹdɪnɛɹi ɡɜːl meɪkɪŋ ɪɾ ɔn hɜːɹ oʊn./', '<span>It''s</span><span>just</span><span>an</span><span tid="125605" class="highlight highlight-a">ordinary</span><span tid="125606">girl</span><span pid="1053" class="highlight highlight-d">making it on her own.</span>'
