INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 36, 162.72, 164.72, 'We just see Rachel in her wardrobe.', '我们只是看到了瑞秋穿着她的衣橱中的衣服。', '/wiː dʒʌst siː ɹeɪtʃəl ɪn hɜː wɔːɹdɹoʊb./', '<span>We</span><span>just</span><span tid="126056">see</span><span tid="126057">Rachel</span><span>in</span><span>her</span><span tid="126060" class="highlight highlight-a">wardrobe.</span>'
