INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 44, 198.0, 199.32, 'And there''s something quite comforting in that.', '这让人感到非常舒适。', '/ænd ðɛɹz sʌmθɪŋ kwaɪt kʌmfɚɾɪŋ ɪn ðæt./', '<span>And</span><span>there''s</span><span>something</span><span tid="126182">quite</span><span tid="126183" class="highlight highlight-a">comforting</span><span>in</span><span>that.</span>'
