INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 48, 209.58, 213.1, 'They''re not something you could actually wear in everyday life and feel normal.', '它们不是你能在日常生活中穿着并感到自然的服装。', '/ðeɪɚ nɑːt sʌmθɪŋ juː kʊd æktʃuːəli wɛɹ ɪn ɛvɹɪdeɪ laɪf ænd fiːl nɔːɹməl./', '<span>They''re</span><span>not</span><span>something</span><span>you</span><span>could</span><span tid="126231">actually</span><span tid="126232">wear</span><span>in</span><span pid="1080" class="highlight highlight-c">everyday life</span><span>and</span><span tid="126237">feel</span><span tid="126238">normal.</span>'
