INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 53, 223.44, 226.4, 'They''re not obviously designer or avant-garde pieces.', '它们看起来不是明显的设计师品牌或先锋派作品。', '/ðeɪɚ nɑːt ɑːbviəsli dɪzaɪnɚ ɔːɹ ævəntɡɑːɹd piːsᵻz./', '<span>They''re</span><span>not</span><span tid="126272" class="highlight highlight-a">obviously</span><span tid="126273" class="highlight highlight-a">designer</span><span>or</span><span tid="126275" class="highlight highlight-a">avant-garde</span><span tid="126276">pieces.</span>'
