INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 54, 226.4, 233.54, 'They''re largely very simple clothes, although often expensive, I''m sure, but simple clothes that you could see any woman in her 20s wearing.', '它们大多是非常简单的衣服，虽然我敢肯定它们很贵，但却是你可以看到任何20多岁女性穿的简单服装。', '/ðeɪɚ lɑːɹdʒli vɛɹi sɪmpəl kloʊðz, ɔːlðoʊ ɔfən ɛkspɛnsɪv, aɪm ʃʊɹ, bʌt sɪmpəl kloʊðz ðæt juː kʊd siː ɛni wʊmən ɪn hɜː twɛnti z wɛɹɪŋ./', '<span>They''re</span><span tid="126278" class="highlight highlight-a">largely</span><span>very</span><span tid="126280">simple</span><span tid="126281">clothes,</span><span tid="126282">although</span><span tid="126283">often</span><span tid="126284">expensive,</span><span>I''m</span><span tid="126286">sure,</span><span>but</span><span tid="126288">simple</span><span tid="126289">clothes</span><span>that</span><span>you</span><span>could</span><span tid="126293">see</span><span tid="126294">any</span><span tid="126295">woman</span><span>in</span><span>her</span><span>20s</span><span tid="126299">wearing.</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 55, 233.54, 235.82, 'Again, she was dressed for the real life.', '她们穿的是现实生活中的衣服。', '/ɐɡɛn, ʃiː wʌz dɹɛst fɚðə ɹiːəl laɪf./', '<span tid="126300">Again,</span><span>she</span><span>was</span><span tid="126303">dressed</span><span>for</span><span>the</span><span tid="126306">real</span><span tid="126307">life.</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 56, 235.82, 246.4, 'We were supposed to be looking in through a window into a real-ish world of people in their 20s, a slightly elevated New York 20s lifestyle, rather than a fantasy version.', '我们应该透过窗户看到一个现实的20多岁纽约人的世界，而不是幻想中的版本。', '/wiː wɜː səpoʊzd təbi lʊkɪŋ ɪn θɹuː ɐ wɪndoʊ ɪntʊ ɐ ɹiːəlɪʃ wɜːld ʌv piːpəl ɪn ðɛɹ twɛnti z, ɐ slaɪtli ɛlɪveɪɾᵻd nuː jɔːɹk twɛnti z laɪfstaɪl, ɹæðɚ ðænə fæntəsi vɜːʒən./', '<span>We</span><span>were</span><span tid="126310">supposed</span><span>to</span><span>be</span><span tid="126313" class="highlight highlight-a">looking</span><span>in</span><span tid="126315">through</span><span>a</span><span tid="126317" class="highlight highlight-a">window</span><span tid="126318" class="highlight highlight-a">into</span><span>a</span><span tid="126320">real-ish</span><span tid="126321">world</span><span>of</span><span tid="126323">people</span><span>in</span><span>their</span><span>20s,</span><span>a</span><span tid="126328" class="highlight highlight-a">slightly</span><span tid="126329" class="highlight highlight-a">elevated</span><span tid="126330">New</span><span tid="126331">York</span><span tid="126332">20s</span><span tid="126333" class="highlight highlight-a">lifestyle,</span><span pid="1043" class="highlight highlight-c">rather than</span><span>a</span><span tid="126337" class="highlight highlight-a">fantasy</span><span tid="126338" class="highlight highlight-a">version.</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 57, 246.4, 248.86, 'The second thing is her hair evolution.', '第二个原因是她的发型演变。', '/ðə sɛkənd θɪŋ ɪz hɜː hɛɹ ɛvəluːʃən./', '<span>The</span><span tid="126340">second</span><span>thing</span><span>is</span><span>her</span><span tid="126344">hair</span><span tid="126345" class="highlight highlight-a">evolution.</span>'
