INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 65, 284.12, 287.1, 'You know, you can associate those with periods in the show.', '你知道，你可以将这些发型和剧中的不同阶段联系起来。', '/juː noʊ, juː kæn ɐsoʊsɪeɪt ðoʊz wɪð piəɹɪədz ɪnðə ʃoʊ./', '<span>You</span><span>know,</span><span>you</span><span>can</span><span tid="126475" class="highlight highlight-a">associate</span><span>those</span><span>with</span><span tid="126478" class="highlight highlight-a">periods</span><span>in</span><span>the</span><span tid="126481">show.</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 66, 287.1, 290.16, 'It''s kind of like, you know how Taylor Swift talks about reinventing herself?', '这就像你知道泰勒·斯威夫特如何谈论自己不断重塑自我一样。', '/ɪts kaɪnd ʌv laɪk, juː noʊ haʊ teɪlɚ swɪft tɔːks ɐbaʊt ɹiːɪnvɛntɪŋ hɜːsɛlf?/', '<span>It''s</span><span tid="126483">kind</span><span>of</span><span>like,</span><span>you</span><span>know</span><span>how</span><span tid="126489">Taylor</span><span tid="126490" class="highlight highlight-a">Swift</span><span tid="126491">talks</span><span>about</span><span tid="126493" class="highlight highlight-a">reinventing</span><span tid="126494">herself?</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 67, 290.16, 295.72, 'You''ve got to be someone where you''ve got to reinvent yourself, but not too much, in a kind of way that people like.', '你必须成为一个愿意不断重塑自己的人，但不是那种过于改变到让别人不喜欢的方式。', '/juːv ɡɑːt təbi sʌmwʌn wɛɹ juːv ɡɑːt tə ɹiːɪnvɛnt jɔːɹsɛlf, bʌt nɑːt tuː mʌtʃ ɪn ɐ kaɪnd ʌv weɪ ðæt piːpəl laɪk./', '<span>You''ve</span><span>got</span><span>to</span><span>be</span><span tid="126499">someone</span><span>where</span><span>you''ve</span><span>got</span><span>to</span><span tid="126504" class="highlight highlight-a">reinvent</span><span tid="126505">yourself,</span><span>but</span><span>not</span><span>too</span><span tid="126509">much,</span><span>in</span><span>a</span><span tid="126512">kind</span><span>of</span><span tid="126514" class="highlight highlight-a">way</span><span>that</span><span tid="126516">people</span><span>like.</span>'
