INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 75, 328.26, 331.24, 'All of these are natural features, so these make her look quite grounded.', '这些都是自然的特征，使得她看起来很接地气。', '/ɔːl ʌv ðiːz ɑːɹ nætʃɚɹəl fiːtʃɚz, soʊ ðiːz meɪk hɜː lʊk kwaɪt ɡɹaʊndᵻd./', '<span>All</span><span>of</span><span>these</span><span>are</span><span tid="126624">natural</span><span tid="126625" class="highlight highlight-a">features,</span><span>so</span><span>these</span><span tid="126628">make</span><span>her</span><span tid="126630" class="highlight highlight-a">look</span><span tid="126631">quite</span><span tid="126632" class="highlight highlight-a">grounded.</span>'
