INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 77, 334.66, 337.48, 'She''s often not put in intricate hairstyles.', '她通常不会有复杂的发型。', '/ʃiːz ɔfən nɑːt pʊt ɪn ɪntɹɪkət hɛɹstaɪlz./', '<span>She''s</span><span tid="126649">often</span><span>not</span><span tid="126651">put</span><span>in</span><span tid="126653" class="highlight highlight-a">intricate</span><span tid="126654" class="highlight highlight-a">hairstyles.</span>'
