FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 81, 347.98, 358.1, 'The shot of her which really makes me think gamine is when she''s at Monica''s wedding in her bridesmaids dress, she has her hair up and she has these cute little pixie ears and I think she looks so pixie-like in that particular image.', '让我认为她有少女感的画面是她在莫妮卡婚礼上的样子，穿着伴娘服，头发盘起来，她的耳朵像小精灵一样，我觉得那一刻她看起来非常像小精灵。', '/ðə ʃɑːt ʌv hɜː wɪtʃ ɹiəli meɪks miː θɪŋk ɡæmaɪn ɪz wɛn ʃiːz æt mɑːnɪkəz wɛdɪŋ ɪn hɜː bɹaɪdsmeɪdz dɹɛs, ʃiː hɐz hɜː hɛɹ ʌp ænd ʃiː hɐz ðiːz kjuːt lɪɾəl pɪksi ɪɹz ænd aɪ θɪŋk ʃiː lʊks soʊ pɪksilaɪk ɪn ðæt pɚtɪkjʊlɚɹ ɪmɪdʒ./', '<span>The</span><span tid="126693" class="highlight highlight-a">shot</span><span>of</span><span>her</span><span>which</span><span tid="126697">really</span><span tid="126698">makes</span><span>me</span><span>think</span><span tid="126701" class="highlight highlight-a">gamine</span><span>is</span><span>when</span><span>she''s</span><span>at</span><span tid="126706">Monica''s</span><span tid="126707" class="highlight highlight-a">wedding</span><span>in</span><span>her</span><span tid="126710">bridesmaids</span><span tid="126711">dress,</span><span>she</span><span>has</span><span>her</span><span tid="126715">hair</span><span>up</span><span>and</span><span>she</span><span>has</span><span>these</span><span tid="126721" class="highlight highlight-a">cute</span><span tid="126722">little</span><span tid="126723" class="highlight highlight-a">pixie</span><span tid="126724">ears</span><span>and</span><span>I</span><span>think</span><span>she</span><span tid="126729" class="highlight highlight-a">looks</span><span>so</span><span tid="126731">pixie-like</span><span>in</span><span>that</span><span tid="126734" class="highlight highlight-a">particular</span><span tid="126735">image.</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
