INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 85, 369.44, 375.72, 'We talked about this a little in regards to her mushroom style root where everything is kept very minimal, timeless, simple.', '我们在谈到她的蘑菇风格根源时也提到过这一点，她的一切都保持非常简约、永恒、简单。', '/wiː tɔːkt ɐbaʊt ðɪs ɐ lɪɾəl ɪn ɹᵻɡɑːɹdz tə hɜː mʌʃɹuːm staɪl ɹuːt wɛɹ ɛvɹɪθɪŋ ɪz kɛpt vɛɹi mɪnɪməl, taɪmləs, sɪmpəl./', '<span>We</span><span tid="126787">talked</span><span>about</span><span>this</span><span>a</span><span tid="126791">little</span><span pid="1084" class="highlight highlight-c">in regards to</span><span>her</span><span tid="126796" class="highlight highlight-a">mushroom</span><span pid="1057" class="highlight highlight-c">style root</span><span>where</span><span tid="126800">everything</span><span>is</span><span tid="126802">kept</span><span>very</span><span tid="126804" class="highlight highlight-a">minimal,</span><span tid="126805" class="highlight highlight-a">timeless,</span><span tid="126806">simple.</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
