INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 87, 382.1, 383.44, 'So Jennifer Aniston is a soft summer.', '所以詹妮弗·安妮斯顿属于柔和夏季色调。', '/soʊ dʒɛnɪfɚɹ ænɪstən ɪz ɐ sɔft sʌmɚ./', '<span>So</span><span tid="126826">Jennifer</span><span tid="126827">Aniston</span><span>is</span><span>a</span><span tid="126830">soft</span><span tid="126831">summer.</span>'
