INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 105, 433.6, 435.78, 'They don''t keep her stagnant. They keep her changing.', '他们并没有让她停滞不前，而是保持她的变化。', '/ðeɪ doʊnt kiːp hɜː stæɡnənt ðeɪ kiːp hɜː tʃeɪndʒɪŋ./', '<span>They</span><span>don''t</span><span tid="127024">keep</span><span>her</span><span tid="127026" class="highlight highlight-a">stagnant.</span><span>They</span><span tid="127028">keep</span><span>her</span><span tid="127030">changing.</span>'
