INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 106, 435.78, 438.62, 'And this also works as Friends'' viewership changes.', '这也和《老友记》观众的变化相契合。', '/ænd ðɪs ɔːlsoʊ wɜːks æz fɹɛndz vjuːɚʃɪp tʃeɪndʒᵻz./', '<span>And</span><span>this</span><span>also</span><span tid="127034">works</span><span>as</span><span tid="127036">Friends''</span><span tid="127037" class="highlight highlight-a">viewership</span><span tid="127038">changes.</span>'
