INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 111, 457.34, 460.14, 'And so Rachel''s outfits become more mature as we go.', '于是瑞秋的衣服随着剧情发展变得更加成熟。', '/ænd soʊ ɹeɪtʃəlz aʊtfɪts bɪkʌm mɔːɹ mətʃʊɹ æz wiː ɡoʊ./', '<span>And</span><span>so</span><span tid="127106">Rachel''s</span><span tid="127107" class="highlight highlight-a">outfits</span><span tid="127108">become</span><span>more</span><span tid="127110" class="highlight highlight-a">mature</span><span>as</span><span>we</span><span>go.</span>'
