INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 131, 522.94, 528.74, 'Another typical Rachel Green outfit is she wears like a strapless, kind of like a boob tube, but it''s like full length.', '另一个典型的瑞秋造型是她穿着一条无肩带的长裙，', '/ɐnʌðɚ tɪpɪkəl ɹeɪtʃəl ɡɹiːn aʊtfɪt ɪz ʃiː wɛɹz laɪk ɐ stɹæpləs, kaɪnd ʌv laɪk ɐ buːb tuːb, bʌt ɪts laɪk fʊl lɛŋθ./', '<span tid="127354">Another</span><span tid="127355" class="highlight highlight-a">typical</span><span tid="127356">Rachel</span><span tid="127357">Green</span><span tid="127358" class="highlight highlight-a">outfit</span><span>is</span><span>she</span><span tid="127361">wears</span><span>like</span><span>a</span><span tid="127364" class="highlight highlight-a">strapless,</span><span tid="127365">kind</span><span>of</span><span>like</span><span>a</span><span tid="127369">boob</span><span tid="127370" class="highlight highlight-a">tube,</span><span>but</span><span>it''s</span><span>like</span><span tid="127374">full</span><span tid="127375">length.</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
