INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 152, 601.8, 605.36, 'It''s rooted in her character, which means that we see those returning style roots.', '它根植于她的角色，这意味着我们看到的那些重复出现的风格根源。', '/ɪts ɹuːɾᵻd ɪn hɜː kæɹɪktɚ, wɪtʃ miːnz ðæt wiː siː ðoʊz ɹᵻtɜːnɪŋ staɪl ɹuːts./', '<span>It''s</span><span tid="127636">rooted</span><span>in</span><span>her</span><span tid="127639" class="highlight highlight-a">character,</span><span>which</span><span tid="127641">means</span><span>that</span><span>we</span><span tid="127644">see</span><span>those</span><span tid="127646" class="highlight highlight-a">returning</span><span pid="1061" class="highlight highlight-c">style roots.</span>'
