INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 153, 605.36, 610.02, 'There''s something consistent about Rachel''s style that keeps it classy, keeps it reflective of who she is.', '瑞秋的风格有某种一致性，使它保持高雅，保持她个性的反映。', '/ðɛɹz sʌmθɪŋ kənsɪstənt ɐbaʊt ɹeɪtʃəlz staɪl ðæt kiːps ɪt klæsi, kiːps ɪt ɹᵻflɛktɪv ʌv huː ʃiː ɪz./', '<span>There''s</span><span>something</span><span tid="127651" class="highlight highlight-a">consistent</span><span>about</span><span tid="127653">Rachel''s</span><span tid="127654">style</span><span>that</span><span tid="127656">keeps</span><span>it</span><span tid="127658" class="highlight highlight-a">classy,</span><span tid="127659">keeps</span><span>it</span><span tid="127661" class="highlight highlight-a">reflective</span><span>of</span><span>who</span><span>she</span><span>is.</span>'
