INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 154, 610.02, 612.5, 'It''s rooted in something greater than trends.', '它根植于比潮流更深的东西。', '/ɪts ɹuːɾᵻd ɪn sʌmθɪŋ ɡɹeɪɾɚ ðɐn tɹɛndz./', '<span>It''s</span><span tid="127667">rooted</span><span>in</span><span>something</span><span tid="127670">greater</span><span tid="127671">than</span><span tid="127672" class="highlight highlight-a">trends.</span>'
