INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 155, 612.5, 618.8, 'It''s also rooted in her color season, a particular color palette, an awareness of Jennifer Aniston and what looks good on her and what doesn''t.', '它还根植于她的色彩季节、特定的色调、对詹妮弗·安妮斯顿的了解，以及她什么颜色适合她，什么不适合她。', '/ɪts ɔːlsoʊ ɹuːɾᵻd ɪn hɜː kʌlɚ siːzən, ɐ pɚtɪkjʊlɚ kʌlɚ pælət, ɐn ɐwɛɹnəs ʌv dʒɛnɪfɚɹ ænɪstən ænd wʌt lʊks ɡʊd ɔn hɜː ænd wʌt dʌzənt./', '<span>It''s</span><span>also</span><span tid="127675">rooted</span><span>in</span><span>her</span><span tid="127678">color</span><span tid="127679">season,</span><span>a</span><span tid="127681" class="highlight highlight-a">particular</span><span pid="1076" class="highlight highlight-c">color palette,</span><span>an</span><span tid="127685" class="highlight highlight-a">awareness</span><span>of</span><span tid="127687">Jennifer</span><span tid="127688">Aniston</span><span>and</span><span>what</span><span tid="127691" class="highlight highlight-a">looks</span><span>good</span><span>on</span><span>her</span><span>and</span><span>what</span><span>doesn''t.</span>'
FROM episodes e WHERE e.video_id = '063vosKc5Bf1Nrg';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
