INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 2.08, 10.98, 'In today''s video, I''m going to give you 17 extremely useful words you can use to help you prepare for your next job interview in English.', '在今天的视频中，我将给你们介绍17个非常实用的单词，帮助你为下次的英语面试做好准备。', '/ɪn tədeɪz vɪdɪoʊ, aɪm ɡoʊɪŋ tə ɡɪv juː sɛvəntiːn ɛkstɹiːmli juːsfəl wɜːdz juː kæn juːz tə hɛlp juː pɹɪpɛɹ fɔːɹ jʊɹ nɛkst dʒɑːb ɪntɚvjuː ɪn ɪŋɡlɪʃ./', '<span>In</span><span tid="124076">today''s</span><span tid="124077">video,</span><span>I''m</span><span>going</span><span>to</span><span tid="124081">give</span><span>you</span><span>17</span><span tid="124084" class="highlight highlight-a">extremely</span><span tid="124085">useful</span><span tid="124086">words</span><span>you</span><span>can</span><span tid="124089">use</span><span>to</span><span tid="124091">help</span><span>you</span><span tid="124093" class="highlight highlight-a">prepare</span><span>for</span><span>your</span><span tid="124096">next</span><span pid="1096" class="highlight highlight-c">job interview</span><span>in</span><span tid="124100">English.</span>'
