INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 20.52, 27.4, 'But in today''s video, I''m going to teach you some simple vocabulary, some words on various topics.', '但今天的视频，我将教你一些简单的词汇，涉及各种话题。', '/bʌt ɪn tədeɪz vɪdɪoʊ, aɪm ɡoʊɪŋ tə tiːtʃ juː sʌm sɪmpəl voʊkæbjʊlɛɹi, sʌm wɜːdz ɔn vɛɹiəs tɑːpɪks./', '<span>But</span><span>in</span><span tid="124137">today''s</span><span tid="124138">video,</span><span>I''m</span><span>going</span><span>to</span><span tid="124142">teach</span><span>you</span><span>some</span><span tid="124145">simple</span><span tid="124146" class="highlight highlight-a">vocabulary,</span><span>some</span><span tid="124148">words</span><span>on</span><span tid="124150" class="highlight highlight-a">various</span><span tid="124151">topics.</span>'
