INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 31.5, 38.5, 'talking about your personality that you can use at your next job interview to sound more fluent and more professional.', '以及谈论你的性格，这些词汇你可以在下次面试中使用，让你听起来更加流利和专业。', '/tɔːkɪŋ ɐbaʊt jʊɹ pɜːsənælᵻɾi ðæt juː kæn juːz æt jʊɹ nɛkst dʒɑːb ɪntɚvjuː tə saʊnd mɔːɹ fluːənt ænd mɔːɹ pɹəfɛʃənəl./', '<span tid="124161">talking</span><span>about</span><span>your</span><span tid="124164" class="highlight highlight-a">personality</span><span>that</span><span>you</span><span>can</span><span tid="124168">use</span><span>at</span><span>your</span><span tid="124171">next</span><span pid="1099" class="highlight highlight-c">job interview</span><span>to</span><span tid="124175">sound</span><span>more</span><span tid="124177" class="highlight highlight-a">fluent</span><span>and</span><span>more</span><span tid="124180" class="highlight highlight-a">professional.</span>'
