INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 22, 103.92, 106.54, 'you might be asked for a resume or for a CV.', '你可能会被要求提供简历或CV。', '/juː maɪt biː æskt fɚɹɚ ɹᵻzuːm ɔːɹ fɚɹə siːviː./', '<span>you</span><span tid="124365" class="highlight highlight-a">might</span><span>be</span><span tid="124367">asked</span><span>for</span><span>a</span><span tid="124370" class="highlight highlight-a">resume</span><span>or</span><span>for</span><span>a</span><span tid="124374" class="highlight highlight-a">CV.</span>'
