INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 109.62, 113.26, 'You''ll probably also be asked to provide a cover letter.', '你可能还会被要求提供一封求职信。', '/juːl pɹɑːbəbli ɔːlsoʊ biː æskt tə pɹəvaɪd ɐ kʌvɚ lɛɾɚ./', '<span>You''ll</span><span tid="124384" class="highlight highlight-a">probably</span><span>also</span><span>be</span><span tid="124387">asked</span><span>to</span><span tid="124389" class="highlight highlight-a">provide</span><span>a</span><span pid="1103" class="highlight highlight-c">cover letter.</span>'
