FROM episodes e WHERE e.video_id = '064Moh2H1lpswSl';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 26, 120.26, 123.92, 'why you''re a good fit for the job, and why you should be interviewed.', '为什么你适合这份工作，为什么你应该被面试。', '/waɪ jʊɹ ɐ ɡʊd fɪt fɚðə dʒɑːb, ænd waɪ juː ʃʊd biː ɪntɚvjuːd./', '<span>why</span><span>you''re</span><span>a</span><span>good</span><span tid="124418" class="highlight highlight-a">fit</span><span>for</span><span>the</span><span tid="124421">job,</span><span>and</span><span>why</span><span>you</span><span tid="124425">should</span><span>be</span><span tid="124427" class="highlight highlight-a">interviewed.</span>'
