INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 29, 133.58, 138.98, 'and its goal is to convince the interviewer or the company that you''re a good fit.', '它的目的是说服面试官或公司你是合适的人选。', '/ænd ɪts ɡoʊl ɪz tə kənvɪns ðɪ ɪntɚvjuːɚ ɔːɹ ðə kʌmpəni ðæt jʊɹ ɐ ɡʊd fɪt./', '<span>and</span><span>its</span><span tid="124454">goal</span><span>is</span><span>to</span><span tid="124457" class="highlight highlight-a">convince</span><span>the</span><span tid="124459" class="highlight highlight-a">interviewer</span><span>or</span><span>the</span><span tid="124462">company</span><span>that</span><span>you''re</span><span>a</span><span>good</span><span tid="124467" class="highlight highlight-a">fit.</span>'
