INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 32, 144.12, 146.7, 'The next word we have on our list is the word candidate.', '接下来我们要讲的词是“候选人”这个词。', '/ðə nɛkst wɜːd wiː hæv ɔn aʊɚ lɪst ɪz ðə wɜːd kændᵻdeɪt./', '<span>The</span><span tid="124485">next</span><span tid="124486">word</span><span>we</span><span>have</span><span>on</span><span>our</span><span tid="124491">list</span><span>is</span><span>the</span><span tid="124494">word</span><span tid="124495" class="highlight highlight-a">candidate.</span>'
