INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 38, 163.28, 166.72, 'And let''s look at the word proficient to start.', '我们首先来看一下“熟练”这个词。', '/ænd lɛts lʊk æt ðə wɜːd pɹəfɪʃənt tə stɑːɹt./', '<span>And</span><span>let''s</span><span tid="124544" class="highlight highlight-a">look</span><span>at</span><span>the</span><span tid="124547">word</span><span tid="124548" class="highlight highlight-a">proficient</span><span>to</span><span tid="124550">start.</span>'
