INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 40, 169.5, 171.78, 'You can use it in so many different situations.', '你可以在许多不同的场合使用它。', '/juː kæn juːz ɪɾ ɪn soʊ mɛni dɪfɹənt sɪtʃuːeɪʃənz./', '<span>You</span><span>can</span><span tid="124562">use</span><span>it</span><span>in</span><span>so</span><span>many</span><span tid="124567">different</span><span tid="124568" class="highlight highlight-a">situations.</span>'
