INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 77, 366.2, 368.18, 'It was way too close for comfort.', '太危险了，真让人心惊肉跳。', '/ɪt wʌz weɪ tuː kloʊs fɔːɹ kʌmfɚt./', '<span>It</span><span>was</span><span tid="122480" class="highlight highlight-a">way</span><span pid="1377" class="highlight highlight-i">too close for comfort.</span>'
