INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 80, 380.66, 384.66, 'There are a lot of shower stalls where you can come and take a shower.', '这里有很多淋浴间，你可以过来洗澡。', '/ðɛɹɑːɹ ɐ lɑːt ʌv ʃaʊɚ stɔːlz wɛɹ juː kæn kʌm ænd teɪk ɐ ʃaʊɚ./', '<span>There</span><span>are</span><span>a</span><span tid="122514">lot</span><span>of</span><span pid="1379" class="highlight highlight-c">shower stalls</span><span>where</span><span>you</span><span>can</span><span tid="122521">come</span><span>and</span><span pid="1380" class="highlight highlight-d">take a shower.</span>'
FROM episodes e WHERE e.video_id = '066p1Gu2ETQwliG';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 81, 384.9, 389.4, 'This is a shared men''s bathroom, which is very common in hostels.', '这是一个男生共用浴室，在青旅里很常见。', '/ðɪs ɪz ɐ ʃɛɹd mɛnz bæθɹuːm, wɪtʃ ɪz vɛɹi kɑːmən ɪn hɑːstəlz./', '<span>This</span><span>is</span><span>a</span><span tid="122529" class="highlight highlight-a">shared</span><span tid="122530">men''s</span><span tid="122531" class="highlight highlight-a">bathroom,</span><span>which</span><span>is</span><span>very</span><span tid="122535">common</span><span>in</span><span tid="122537" class="highlight highlight-a">hostels.</span>'
