INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 84, 401.46, 405.8, 'They''re the wall-mounted type, usually used for quick bathroom stops.', '它们是挂墙式的，通常用于快速如厕。', '/ðeɪɚ ðə wɔːlmaʊntᵻd taɪp, juːʒuːəli juːzd fɔːɹ kwɪk bæθɹuːm stɑːps./', '<span>They''re</span><span>the</span><span tid="122569" class="highlight highlight-a">wall-mounted</span><span tid="122570" class="highlight highlight-a">type,</span><span tid="122571">usually</span><span tid="122572">used</span><span>for</span><span tid="122574">quick</span><span tid="122575" class="highlight highlight-a">bathroom</span><span tid="122576">stops.</span>'
