INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 85, 406.76, 413.64, 'This is an 8-person mixed dorm, which means both men and women can sleep in the same room.', '这是一个 8 人混住的宿舍，也就是说男生和女生可以住在同一个房间。', '/ðɪs ɪz ɐn eɪtpɜːsən mɪkst dɔːɹm, wɪtʃ miːnz boʊθ mɛn ænd wɪmɪn kæn sliːp ɪnðə seɪm ɹuːm./', '<span>This</span><span>is</span><span>an</span><span tid="122580">8-person</span><span tid="122581" class="highlight highlight-a">mixed</span><span tid="122582" class="highlight highlight-a">dorm,</span><span>which</span><span tid="122584">means</span><span tid="122585">both</span><span tid="122586">men</span><span>and</span><span tid="122588">women</span><span>can</span><span tid="122590">sleep</span><span>in</span><span>the</span><span tid="122593">same</span><span tid="122594">room.</span>'
