INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 106, 500.54, 502.2, 'We have a soft-sided suitcase.', '这是一个软壳行李箱。', '/wiː hæv ɐ sɔftsaɪdᵻd suːtkeɪs./', '<span>We</span><span>have</span><span>a</span><span pid="1393" class="highlight highlight-c">soft-sided suitcase.</span>'
