INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 107, 502.2, 506.54, 'And this is a hard shell suitcase.', '而这是一个硬壳行李箱。', '/ænd ðɪs ɪz ɐ hɑːɹd ʃɛl suːtkeɪs./', '<span>And</span><span>this</span><span>is</span><span>a</span><span pid="1394" class="highlight highlight-c">hard shell suitcase.</span>'
