INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 108, 506.68, 511.02, 'This part right here is called the handle and it''s an adjustable handle.', '这里这个部分叫拉杆，是可调节的拉杆。', '/ðɪs pɑːɹt ɹaɪt hɪɹ ɪz kɔːld ðə hændəl ænd ɪts ɐn ɐdʒʌstəbəl hændəl./', '<span>This</span><span tid="122829">part</span><span tid="122830" class="highlight highlight-a">right</span><span>here</span><span>is</span><span tid="122833">called</span><span>the</span><span tid="122835" class="highlight highlight-a">handle</span><span>and</span><span>it''s</span><span>an</span><span tid="122839" class="highlight highlight-a">adjustable</span><span tid="122840" class="highlight highlight-a">handle.</span>'
