INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 112, 528.44, 535.72, 'This is a softside suitcase and this is a hard shell suitcase.', '这是软壳行李箱，那是硬壳行李箱。', '/ðɪs ɪz ɐ sɔft saɪd suːtkeɪs ænd ðɪs ɪz ɐ hɑːɹd ʃɛl suːtkeɪs./', '<span>This</span><span>is</span><span>a</span><span tid="122888">softside</span><span tid="122889" class="highlight highlight-a">suitcase</span><span>and</span><span>this</span><span>is</span><span>a</span><span pid="1395" class="highlight highlight-c">hard shell suitcase.</span>'
