INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 113, 535.74, 536.98, 'That''s good, that''s good.', '很好，很好。', '/ðæts ɡʊd, ðæts ɡʊd./', '<span>That''s</span><span>good,</span><span>that''s</span><span>good.</span>'
FROM episodes e WHERE e.video_id = '066p1Gu2ETQwliG';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 114, 537.18, 539.4, 'Now tell me, what is this bag usually used for?', '现在告诉我，这个包通常用来做什么？', '/naʊ tɛl miː, wʌt ɪz ðɪs bæɡ juːʒuːəli juːzd fɔːɹ?/', '<span tid="122901">Now</span><span tid="122902">tell</span><span>me,</span><span>what</span><span>is</span><span>this</span><span tid="122907" class="highlight highlight-a">bag</span><span tid="122908">usually</span><span tid="122909">used</span><span>for?</span>'
FROM episodes e WHERE e.video_id = '066p1Gu2ETQwliG';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 115, 539.54, 543.38, 'A checked bag, a personal item, or a carry-on bag?', '是托运行李、随身小件，还是随身行李？', '/ɐ tʃɛkd bæɡ, ɐ pɜːsənəl aɪɾəm, ɔːɹ ɐ kæɹiɔn bæɡ?/', '<span>A</span><span tid="122912">checked</span><span tid="122913" class="highlight highlight-a">bag,</span><span>a</span><span pid="1386" class="highlight highlight-c">personal item,</span><span>or</span><span>a</span><span tid="122919">carry-on</span><span tid="122920" class="highlight highlight-a">bag?</span>'
FROM episodes e WHERE e.video_id = '066p1Gu2ETQwliG';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 116, 544.4, 548.7, 'This bag is mostly used as a carry-on item.', '这个包大多数情况下是当作随身行李用的。', '/ðɪs bæɡ ɪz moʊstli juːzd æz ɐ kæɹiɔn aɪɾəm./', '<span>This</span><span tid="122922" class="highlight highlight-a">bag</span><span>is</span><span tid="122924" class="highlight highlight-a">mostly</span><span tid="122925">used</span><span>as</span><span>a</span><span tid="122928">carry-on</span><span tid="122929">item.</span>'
