INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 117, 548.78, 554.02, 'Although, if you pack it small enough, you could use it as a personal item sometimes.', '不过，如果你打包得够小，有时也能当作随身小件。', '/ɔːlðoʊ, ɪf juː pæk ɪt smɔːl ɪnʌf, juː kʊd juːz ɪɾ æz ɐ pɜːsənəl aɪɾəm sʌmtaɪmz./', '<span tid="122930">Although,</span><span>if</span><span>you</span><span tid="122933" class="highlight highlight-a">pack</span><span>it</span><span tid="122935">small</span><span tid="122936">enough,</span><span>you</span><span>could</span><span tid="122939">use</span><span>it</span><span>as</span><span>a</span><span pid="1387" class="highlight highlight-c">personal item</span><span tid="122945">sometimes.</span>'
FROM episodes e WHERE e.video_id = '066p1Gu2ETQwliG';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 118, 554.46, 555.6, 'Depending on the airline.', '要看航空公司的规定。', '/dᵻpɛndɪŋ ɔnðɪ ɛɹlaɪn./', '<span tid="122946">Depending</span><span>on</span><span>the</span><span tid="122949" class="highlight highlight-a">airline.</span>'
