INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 120, 557.28, 560.9, 'Can you give me three things I can put in this bag?', '你能说出三样我可以放在里面的东西吗？', '/kæn juː ɡɪv miː θɹiː θɪŋz aɪ kæn pʊt ɪn ðɪs bæɡ?/', '<span>Can</span><span>you</span><span tid="122955">give</span><span>me</span><span>three</span><span>things</span><span>I</span><span>can</span><span tid="122961">put</span><span>in</span><span>this</span><span tid="122964" class="highlight highlight-a">bag?</span>'
FROM episodes e WHERE e.video_id = '066p1Gu2ETQwliG';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 121, 561.4, 564.52, 'Inside your personal item, which is this bag.', '在你的随身小件里，也就是这个包里。', '/ɪnsaɪd jʊɹ pɜːsənəl aɪɾəm, wɪtʃ ɪz ðɪs bæɡ./', '<span tid="122965">Inside</span><span>your</span><span pid="1388" class="highlight highlight-c">personal item,</span><span>which</span><span>is</span><span>this</span><span tid="122972" class="highlight highlight-a">bag.</span>'
