INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 122, 564.72, 574.28, 'you can put stuff that you need quick access to, like your passport, a power bank, your headphones, and your boarding pass.', '你可以放需要快速拿到的东西，比如护照、充电宝、耳机和登机牌。', '/juː kæn pʊt stʌf ðæt juː niːd kwɪk æksɛs tuː, laɪk jʊɹ pæspɔːɹt, ɐ paʊɚ bæŋk, jʊɹ hɛdfoʊnz, ænd jʊɹ bɔːɹdɪŋ pæs./', '<span>you</span><span>can</span><span tid="122975">put</span><span tid="122976" class="highlight highlight-a">stuff</span><span>that</span><span>you</span><span tid="122979">need</span><span tid="122980">quick</span><span tid="122981" class="highlight highlight-a">access</span><span>to,</span><span>like</span><span>your</span><span tid="122985" class="highlight highlight-a">passport,</span><span>a</span><span pid="1392" class="highlight highlight-c">power bank,</span><span>your</span><span tid="122990" class="highlight highlight-a">headphones,</span><span>and</span><span>your</span><span pid="1396" class="highlight highlight-c">boarding pass.</span>'
