INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 123, 574.46, 579.76, 'Although nowadays, you usually have your boarding pass on your phone for convenience.', '不过现在通常登机牌都在手机上，为了方便。', '/ɔːlðoʊ naʊədeɪz, juː juːʒuːəli hæv jʊɹ bɔːɹdɪŋ pæs ɔn jʊɹ foʊn fɔːɹ kənviːnɪəns./', '<span tid="122995">Although</span><span tid="122996" class="highlight highlight-a">nowadays,</span><span>you</span><span tid="122998">usually</span><span>have</span><span>your</span><span pid="1397" class="highlight highlight-c">boarding pass</span><span>on</span><span>your</span><span tid="123005">phone</span><span>for</span><span tid="123007">convenience.</span>'
