INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 30, 174.0, 179.44, 'we experience more job satisfaction, increased team morale.', '我们会感受到更多的工作满足感，团队士气提升。', '/wiː ɛkspiəɹɪəns mɔːɹ dʒɑːb sæɾɪsfækʃən, ɪŋkɹiːst tiːm mɚɹæl./', '<span>we</span><span tid="38604">experience</span><span>more</span><span tid="38606">job</span><span tid="38607" class="highlight highlight-a">satisfaction,</span><span tid="38608">increased</span><span tid="38609">team</span><span tid="38610" class="highlight highlight-a">morale.</span>'
