INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 46, 261.34, 265.42, 'She always created airtime for normally avoided matters.', '她总能为通常被回避的问题创造发声空间。', '/ʃiː ɔːlweɪz kɹiːeɪɾᵻd ɛɹtaɪm fɔːɹ nɔːɹməli ɐvɔɪdᵻd mæɾɚz./', '<span>She</span><span tid="38784">always</span><span tid="38785">created</span><span tid="38786">airtime</span><span>for</span><span tid="38788" class="highlight highlight-a">normally</span><span tid="38789" class="highlight highlight-a">avoided</span><span tid="38790">matters.</span>'
