INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 52, 312.84, 318.24, 'She showed me that as leaders, and I mean all leaders, both formal and informal.', '她向我展示了作为领导者——无论是正式还是非正式的领导者——', '/ʃiː ʃoʊd miː ðæt æz liːdɚz, ænd aɪ miːn ɔːl liːdɚz, boʊθ fɔːɹməl ænd ɪnfɔːɹməl./', '<span>She</span><span tid="38893">showed</span><span>me</span><span>that</span><span>as</span><span tid="38897">leaders,</span><span>and</span><span>I</span><span tid="38900">mean</span><span>all</span><span tid="38902">leaders,</span><span tid="38903">both</span><span tid="38904" class="highlight highlight-a">formal</span><span>and</span><span tid="38906" class="highlight highlight-a">informal.</span>'
