INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 53, 319.1, 326.46, 'we play a pivotal role in leaning into courageous conversations and creating a safe place for others to do the same.', '我们在勇敢面对对话、为他人创造安全空间方面扮演着关键角色。', '/wiː pleɪ ɐ pɪvəɾəl ɹoʊl ɪn liːnɪŋ ɪntʊ kɜːɹeɪdʒəs kɑːnvɚseɪʃənz ænd kɹiːeɪɾɪŋ ɐ seɪf pleɪs fɔːɹ ʌðɚz tə duː ðə seɪm./', '<span>we</span><span tid="38908">play</span><span>a</span><span tid="38910" class="highlight highlight-a">pivotal</span><span tid="38911">role</span><span>in</span><span pid="2516" class="highlight highlight-c">leaning into</span><span tid="38915" class="highlight highlight-a">courageous</span><span tid="38916">conversations</span><span>and</span><span tid="38918">creating</span><span>a</span><span tid="38920">safe</span><span tid="38921">place</span><span>for</span><span tid="38923">others</span><span>to</span><span>do</span><span>the</span><span tid="38927">same.</span>'
