INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 58, 355.82, 362.68, 'So when I find myself needing courage and confidence, making that moment to step into the abyss of a difficult conversation.', '所以当我需要勇气和自信，准备进入一次艰难对话的深渊时，', '/soʊ wɛn aɪ faɪnd maɪsɛlf niːdɪŋ kɜːɹɪdʒ ænd kɑːnfɪdəns, meɪkɪŋ ðæt moʊmənt tə stɛp ɪntʊ ðɪ ɐbɪs əvə dɪfɪkəlt kɑːnvɚseɪʃən./', '<span>So</span><span>when</span><span>I</span><span tid="38999">find</span><span tid="39000">myself</span><span tid="39001">needing</span><span tid="39002" class="highlight highlight-a">courage</span><span>and</span><span tid="39004">confidence,</span><span tid="39005">making</span><span>that</span><span tid="39007" class="highlight highlight-a">moment</span><span>to</span><span pid="2488" class="highlight highlight-d">step into</span><span>the</span><span tid="39012" class="highlight highlight-a">abyss</span><span>of</span><span>a</span><span tid="39015">difficult</span><span tid="39016">conversation.</span>'
