INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 59, 363.4, 370.94, 'I try to remember my mom''s moral compass and the principles she worked so hard to nurture in me.', '我会试着回想妈妈的道德准则，以及她辛苦教会我的那些原则。', '/aɪ tɹaɪ tə ɹᵻmɛmbɚ maɪ mɑːmz mɔːɹəl kʌmpəs ænd ðə pɹɪnsɪpəlz ʃiː wɜːkt soʊ hɑːɹd tə nɜːtʃɚɹ ɪn miː./', '<span>I</span><span tid="39018">try</span><span>to</span><span tid="39020">remember</span><span>my</span><span tid="39022">mom''s</span><span pid="2523" class="highlight highlight-i">moral compass</span><span>and</span><span>the</span><span tid="39027" class="highlight highlight-a">principles</span><span>she</span><span tid="39029">worked</span><span>so</span><span tid="39031">hard</span><span>to</span><span tid="39033" class="highlight highlight-a">nurture</span><span>in</span><span>me.</span>'
