INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 60, 372.04, 383.5, 'I imagine holding a compass in my hand, the cool metal upon my skin, taking a breath, a moment to pause and ground myself.', '我想象自己手握一个指南针，冰冷的金属触感在皮肤上，深呼吸，暂停片刻，让自己稳住。', '/aɪ ɪmædʒɪn hoʊldɪŋ ɐ kʌmpəs ɪn maɪ hænd, ðə kuːl mɛɾəl əpɑːn maɪ skɪn, teɪkɪŋ ɐ bɹɛθ, ɐ moʊmənt tə pɔːz ænd ɡɹaʊnd maɪsɛlf./', '<span>I</span><span tid="39037" class="highlight highlight-a">imagine</span><span tid="39038">holding</span><span>a</span><span pid="2524" class="highlight highlight-i">compass</span><span>in</span><span>my</span><span tid="39043">hand,</span><span>the</span><span tid="39045" class="highlight highlight-a">cool</span><span tid="39046" class="highlight highlight-a">metal</span><span tid="39047">upon</span><span>my</span><span tid="39049">skin,</span><span pid="2532" class="highlight highlight-c">taking a breath,</span><span>a</span><span tid="39054" class="highlight highlight-a">moment</span><span>to</span><span tid="39056" class="highlight highlight-a">pause</span><span>and</span><span tid="39058" class="highlight highlight-a">ground</span><span tid="39059">myself.</span>'
FROM episodes e WHERE e.video_id = '068yjCmyRH6CMUv';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 61, 384.78, 392.88, 'I see the directions of north, south, east, and west, as symbols, reminders of her core teachings.', '我看到北、南、东、西的方向，作为她核心教诲的象征与提醒。', '/aɪ siː ðə dᵻɹɛkʃənz ʌv nɔːɹθ, saʊθ, iːst, ænd wɛst, æz sɪmbəlz, ɹᵻmaɪndɚz ʌv hɜː kɔːɹ tiːtʃɪŋz./', '<span>I</span><span tid="39061">see</span><span>the</span><span tid="39063" class="highlight highlight-a">directions</span><span>of</span><span tid="39065">north,</span><span tid="39066">south,</span><span tid="39067">east,</span><span>and</span><span tid="39069">west,</span><span>as</span><span tid="39071">symbols,</span><span tid="39072" class="highlight highlight-a">reminders</span><span>of</span><span>her</span><span tid="39075" class="highlight highlight-a">core</span><span tid="39076">teachings.</span>'
