INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 62, 394.4, 400.56, 'North, I think about the north star, a guide towards the good and right thing to do.', '北，我想到北极星，引导我走向正确与善良。', '/nɔːɹθ, aɪ θɪŋk ɐbaʊt ðə nɔːɹθ stɑːɹ, ɐ ɡaɪd təwɔːɹdz ðə ɡʊd ænd ɹaɪt θɪŋ tə duː./', '<span tid="39077">North,</span><span>I</span><span>think</span><span>about</span><span>the</span><span tid="39082">north</span><span tid="39083">star,</span><span>a</span><span tid="39085" class="highlight highlight-a">guide</span><span tid="39086">towards</span><span>the</span><span>good</span><span>and</span><span tid="39090" class="highlight highlight-a">right</span><span>thing</span><span>to</span><span>do.</span>'
