SELECT e.id, 92, 554.98, 560.72, 'He lowered his arm and said, well, this is too positive, not an accurate representation of what we''re going through.', '他放下手臂，说，这太积极了，不能准确反映我们所经历的情况。', '/hiː loʊɚd hɪz ɑːɹm ænd sɛd, wɛl, ðɪs ɪz tuː pɑːzᵻtɪv, nɑːt ɐn ækjʊɹət ɹɛpɹᵻzɛnteɪʃən ʌv wʌt wɪɹ ɡoʊɪŋ θɹuː./', '<span>He</span><span tid="39439">lowered</span><span>his</span><span tid="39441">arm</span><span>and</span><span tid="39443">said,</span><span tid="39444">well,</span><span>this</span><span>is</span><span>too</span><span tid="39448" class="highlight highlight-a">positive,</span><span>not</span><span>an</span><span tid="39451" class="highlight highlight-a">accurate</span><span tid="39452" class="highlight highlight-a">representation</span><span>of</span><span>what</span><span>we''re</span><span pid="2485" class="highlight highlight-d">going through.</span>'
FROM episodes e WHERE e.video_id = '068yjCmyRH6CMUv';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
