FROM episodes e WHERE e.video_id = '068yjCmyRH6CMUv';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 94, 568.28, 572.36, 'I wanted to create a safe place where he could feel seen and heard.', '我想创造一个安全空间，让他感到被理解和倾听。', '/aɪ wɔntᵻd tə kɹiːeɪt ɐ seɪf pleɪs wɛɹ hiː kʊd fiːl siːn ænd hɜːd./', '<span>I</span><span>wanted</span><span>to</span><span tid="39469">create</span><span>a</span><span tid="39471">safe</span><span tid="39472">place</span><span>where</span><span>he</span><span>could</span><span pid="2534" class="highlight highlight-c">feel seen</span><span>and</span><span tid="39479">heard.</span>'
