INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 95, 572.96, 577.72, 'So I suggested we sit down together so I could better understand his concerns.', '于是我建议我们坐下来，好让我更好地理解他的顾虑。', '/soʊ aɪ sədʒɛstᵻd wiː sɪt daʊn təɡɛðɚ soʊ aɪ kʊd bɛɾɚɹ ʌndɚstænd hɪz kənsɜːnz./', '<span>So</span><span>I</span><span tid="39482">suggested</span><span>we</span><span tid="39484">sit</span><span tid="39485">down</span><span tid="39486">together</span><span>so</span><span>I</span><span>could</span><span tid="39490">better</span><span tid="39491">understand</span><span>his</span><span tid="39493" class="highlight highlight-a">concerns.</span>'
