INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 96, 579.18, 581.58, 'Next step, wonder.', '下一步，好奇心。', '/nɛkst stɛp, wʌndɚ./', '<span tid="39494">Next</span><span tid="39495">step,</span><span tid="39496" class="highlight highlight-a">wonder.</span>'
