INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 97, 582.5, 585.94, 'We went to his office and I asked curious questions.', '我们去了他的办公室，我提出好奇的问题。', '/wiː wɛnt tə hɪz ɑːfɪs ænd aɪ æskt kjʊɹɹiəs kwɛstʃənz./', '<span>We</span><span>went</span><span>to</span><span>his</span><span tid="39501">office</span><span>and</span><span>I</span><span tid="39504">asked</span><span tid="39505" class="highlight highlight-a">curious</span><span tid="39506">questions.</span>'
