INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 98, 586.52, 589.58, 'And over some tea, he told me his story.', '在喝茶的过程中，他告诉了我他的故事。', '/ænd oʊvɚ sʌm tiː, hiː toʊld miː hɪz stɔːɹi./', '<span>And</span><span tid="39508">over</span><span>some</span><span tid="39510">tea,</span><span>he</span><span tid="39512">told</span><span>me</span><span>his</span><span tid="39515">story.</span>'
