INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 99, 590.32, 595.38, 'He got out a red pen and circled the nine times I''d mentioned something positive in that article.', '他拿出一支红笔，把我在那篇文章中提到积极内容的九个地方圈了出来。', '/hiː ɡɑːt aʊt ɐ ɹɛd pɛn ænd sɜːkəld ðə naɪn taɪmz aɪd mɛnʃənd sʌmθɪŋ pɑːzᵻtɪv ɪn ðæt ɑːɹɾɪkəl./', '<span>He</span><span>got</span><span tid="39518">out</span><span>a</span><span tid="39520">red</span><span tid="39521">pen</span><span>and</span><span tid="39523">circled</span><span>the</span><span>nine</span><span tid="39526">times</span><span>I''d</span><span tid="39528">mentioned</span><span>something</span><span tid="39530" class="highlight highlight-a">positive</span><span>in</span><span>that</span><span tid="39533" class="highlight highlight-a">article.</span>'
FROM episodes e WHERE e.video_id = '068yjCmyRH6CMUv';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 100, 598.26, 603.42, 'I acknowledged, it was too many, understandably devaluing.', '我承认，次数太多了，确实会显得有点贬值。', '/aɪ ɐknɑːlɪdʒd, ɪt wʌz tuː mɛni, ʌndɚstændəbli diːvæljuːɪŋ./', '<span>I</span><span tid="39535" class="highlight highlight-a">acknowledged,</span><span>it</span><span>was</span><span>too</span><span>many,</span><span tid="39540" class="highlight highlight-a">understandably</span><span tid="39541" class="highlight highlight-a">devaluing.</span>'
