INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 101, 604.14, 607.38, 'I then asked if we could look for times I''d mentioned challenges.', '然后我问，能否看看我提到挑战的次数。', '/aɪ ðɛn æskt ɪf wiː kʊd lʊk fɔːɹ taɪmz aɪd mɛnʃənd tʃælɪndʒᵻz./', '<span>I</span><span>then</span><span tid="39544">asked</span><span>if</span><span>we</span><span>could</span><span tid="39548" class="highlight highlight-a">look</span><span>for</span><span tid="39550">times</span><span>I''d</span><span tid="39552">mentioned</span><span tid="39553">challenges.</span>'
FROM episodes e WHERE e.video_id = '068yjCmyRH6CMUv';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 102, 608.34, 612.82, 'To his surprise and frankly, my own, 18 times.', '出乎他的意料，也出乎我自己的意料，有18次。', '/tə hɪz sɚpɹaɪz ænd fɹæŋkli, maɪ oʊn, eɪtiːn taɪmz./', '<span>To</span><span>his</span><span tid="39556">surprise</span><span>and</span><span tid="39558" class="highlight highlight-a">frankly,</span><span>my</span><span tid="39560" class="highlight highlight-a">own,</span><span>18</span><span tid="39562">times.</span>'
FROM episodes e WHERE e.video_id = '068yjCmyRH6CMUv';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 103, 613.46, 617.64, '18, I''d mentioned things that needed to be fixed.', '18次，我提到需要改进的事项。', '/eɪtiːn, aɪd mɛnʃənd θɪŋz ðæt niːdᵻd təbi fɪkst./', '<span>18,</span><span>I''d</span><span tid="39565">mentioned</span><span>things</span><span>that</span><span tid="39568">needed</span><span>to</span><span>be</span><span tid="39571">fixed.</span>'
