INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 59, 403.9, 407.94, 'Maybe due to the fact that the car has a manual transmission.', '也许因为它有手动挡。', 'meɪbiː duː tə ðə fækt ðætðə kɑːɹ hɐz ɐ mænjuːəl tɹænsmɪʃən.', '<span tid="35980">Maybe</span><span pid="2197" class="highlight highlight-i">due to the fact that</span><span>the</span><span tid="35987">car</span><span>has</span><span>a</span><span tid="35990" class="highlight highlight-a">manual</span><span tid="35991" class="highlight highlight-a">transmission.</span>'
