INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 60, 407.94, 417.42, 'Maybe due to the fact that a car has great handling or any other aspect of what makes a car fun to drive.', '也许因为它操控性极佳，或者有其他让驾驶更有乐趣的特质。', 'meɪbiː duː tə ðə fækt ðæɾə kɑːɹ hɐz ɡɹeɪt hændlɪŋ ɔːɹ ɛni ʌðɚɹ æspɛkt ʌv wʌt meɪks ɐ kɑːɹ fʌn tə dɹaɪv.', '<span tid="35992">Maybe</span><span pid="2198" class="highlight highlight-i">due to the fact that</span><span>a</span><span tid="35999">car</span><span>has</span><span tid="36001">great</span><span tid="36002">handling</span><span>or</span><span pid="2200" class="highlight highlight-c">any other</span><span tid="36006" class="highlight highlight-a">aspect</span><span>of</span><span>what</span><span tid="36009">makes</span><span>a</span><span tid="36011">car</span><span tid="36012">fun</span><span>to</span><span tid="36014">drive.</span>'
FROM episodes e WHERE e.video_id = '070qP8mE6ggeGim';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 61, 417.42, 422.06, 'But if I was a person that didn''t care how the car drives.', '但如果我是一个不在乎驾驶感受的人。', 'bʌt ɪf aɪ wʌzɐ pɜːsən ðæt dɪdnt kɛɹ haʊ ðə kɑːɹ dɹaɪvz.', '<span>But</span><span>if</span><span>I</span><span>was</span><span>a</span><span tid="36020">person</span><span>that</span><span>didn''t</span><span tid="36023">care</span><span>how</span><span>the</span><span tid="36026">car</span><span tid="36027">drives.</span>'
