INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 62, 422.06, 425.8, 'and I just wanted to make a rational sensible choice.', '只想做出理智的选择。', 'ænd aɪ dʒʌst wɔntᵻd tə meɪk ɐ ɹæʃənəl sɛnsᵻbəl tʃɔɪs.', '<span>and</span><span>I</span><span>just</span><span>wanted</span><span>to</span><span tid="36033">make</span><span>a</span><span tid="36035" class="highlight highlight-a">rational</span><span pid="2167" class="highlight highlight-c">sensible choice.</span>'
