INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 64, 431.28, 436.64, 'But that doesn''t mean that hybrid cars are not nice to drive.', '但这并不意味着混动车开起来就不舒服。', 'bʌt ðæt dʌzənt miːn ðæt haɪbɹɪd kɑːɹz ɑːɹ nɑːt naɪs tə dɹaɪv.', '<span>But</span><span>that</span><span>doesn''t</span><span tid="36049">mean</span><span>that</span><span pid="2159" class="highlight highlight-b">hybrid cars</span><span>are</span><span>not</span><span tid="36055">nice</span><span>to</span><span tid="36057">drive.</span>'
