INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 11.62, 16.84, 'Today we''re going cafe hopping, which means to go from one coffee shop to the next.', '今天我们要去咖啡馆串门，就是从一家咖啡店跳到另一家。', 'tədeɪ wɪɹ ɡoʊɪŋ kæfeɪ hɑːpɪŋ, wɪtʃ miːnz tə ɡoʊ fɹʌm wʌn kɔfi ʃɑːp tə ðə nɛkst.', '<span tid="55042">Today</span><span>we''re</span><span>going</span><span pid="3306" class="highlight highlight-c">cafe hopping,</span><span>which</span><span tid="55048">means</span><span>to</span><span>go</span><span>from</span><span>one</span><span pid="3307" class="highlight highlight-c">coffee shop</span><span>to</span><span>the</span><span tid="55057">next.</span>'
