INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 21.62, 31.46, 'So we''ve just arrived at the cafe and the name is Wonderlust, which is a wordplay for another word Wanderlust, which means a desire to travel.', '我们刚到这家咖啡馆，名字叫Wanderlust，这其实是个谐音梗，原词Wanderlust的意思是“旅行的渴望”。', 'soʊ wiːv dʒʌst ɚɹaɪvd æt ðə kæfeɪ ænd ðə neɪm ɪz wʌndɚlʌst, wɪtʃ ɪz ɐ wɜːdpleɪ fɔːɹ ɐnʌðɚ wɜːd wɔndɚlʌst, wɪtʃ miːnz ɐ dɪzaɪɚ tə tɹævəl.', '<span>So</span><span>we''ve</span><span>just</span><span tid="55078">arrived</span><span>at</span><span>the</span><span tid="55081">cafe</span><span>and</span><span>the</span><span tid="55084">name</span><span>is</span><span tid="55086">Wonderlust,</span><span>which</span><span>is</span><span>a</span><span tid="55090" class="highlight highlight-a">wordplay</span><span>for</span><span tid="55092">another</span><span tid="55093">word</span><span tid="55094" class="highlight highlight-a">Wanderlust,</span><span>which</span><span tid="55096">means</span><span>a</span><span tid="55098" class="highlight highlight-a">desire</span><span>to</span><span tid="55100">travel.</span>'
FROM episodes e WHERE e.video_id = '071LsfyHOZD0Vr7';
