INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 6.5, 'The brutal reality that no one wants to hear is that you need to stop caring about how you look.', '残酷的现实是，没有人愿意听，但你必须停止在意自己的外表。', 'ðə bɹuːɾəl ɹɪælᵻɾi ðæt noʊwʌn wɔnts tə hɪɹ ɪz ðæt juː niːd tə stɑːp kɛɹɪŋ ɐbaʊt haʊ juː lʊk.', '<span>The</span><span pid="1778" class="highlight highlight-i">brutal reality</span><span>that</span><span>no</span><span>one</span><span>wants</span><span>to</span><span tid="54036">hear</span><span>is</span><span>that</span><span>you</span><span tid="54040">need</span><span>to</span><span tid="54042">stop</span><span tid="54043">caring</span><span>about</span><span>how</span><span>you</span><span tid="54047" class="highlight highlight-a">look.</span>'
