INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 27, 119.52, 124.22, 'You know, I think for so long I''ve been in this pursuit of something that isn''t really real.', '你知道吗，我觉得我很长时间都在追逐一些根本不真实的东西。', 'juː noʊ, aɪ θɪŋk fɔːɹ soʊ lɔŋ aɪv bɪn ɪn ðɪs pɚsuːt ʌv sʌmθɪŋ ðæt ɪzənt ɹiəli ɹiːəl.', '<span>You</span><span>know,</span><span>I</span><span>think</span><span>for</span><span>so</span><span tid="54432">long</span><span>I''ve</span><span>been</span><span>in</span><span>this</span><span tid="54437" class="highlight highlight-a">pursuit</span><span>of</span><span>something</span><span>that</span><span tid="54441">isn''t</span><span tid="54442">really</span><span tid="54443">real.</span>'
