INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 32, 147.96, 156.28, 'You know, I meet on a regular basis some of the most awful, untalented, laziest people.', '你知道，我经常遇到一些极其糟糕、没有天赋、又懒惰的人。', 'juː noʊ, aɪ miːt ɔn ɐ ɹɛɡjʊlɚ beɪsɪs sʌm ʌvðə moʊst ɔːfəl, ʌntæləntᵻd, leɪziɪst piːpəl.', '<span>You</span><span>know,</span><span>I</span><span tid="54517">meet</span><span pid="1784" class="highlight highlight-i">on a regular basis</span><span>some</span><span>of</span><span>the</span><span tid="54525">most</span><span tid="54526" class="highlight highlight-a">awful,</span><span tid="54527" class="highlight highlight-a">untalented,</span><span tid="54528">laziest</span><span tid="54529">people.</span>'
