INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 33, 156.28, 165.52, 'that you could possibly meet that on the surface live what appears to be the perfect life just because of how they look.', '但他们表面上却过着看似完美的生活，仅仅因为他们的长相。', 'ðæt juː kʊd pɑːsᵻbli miːt ðæt ɔnðə sɜːfɪs laɪv wʌt ɐpɪɹz təbi ðə pɜːfɛkt laɪf dʒʌst bɪkʌz ʌv haʊ ðeɪ lʊk.', '<span>that</span><span>you</span><span>could</span><span tid="54533">possibly</span><span tid="54534">meet</span><span>that</span><span pid="1785" class="highlight highlight-i">on the surface</span><span tid="54539">live</span><span>what</span><span tid="54541">appears</span><span>to</span><span>be</span><span>the</span><span tid="54545">perfect</span><span tid="54546">life</span><span>just</span><span>because</span><span>of</span><span>how</span><span>they</span><span tid="54552" class="highlight highlight-a">look.</span>'
FROM episodes e WHERE e.video_id = '0720BUefQc5EoP8';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 170.88, 172.78, 'How many followers do you need to be considered an influencer?', '要多少粉丝才算网红？', 'haʊ mɛni fɑːloʊɚz duː juː niːd təbi kənsɪdɚd ɐn ɪnfluːənsɚ?', '<span>How</span><span>many</span><span tid="54555" class="highlight highlight-a">followers</span><span>do</span><span>you</span><span tid="54558">need</span><span>to</span><span>be</span><span tid="54561" class="highlight highlight-a">considered</span><span>an</span><span tid="54563" class="highlight highlight-a">influencer?</span>'
