INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 35, 172.78, 174.72, 'Is it 5,000 Is it half a million Is it a million?', '是五千？是五十万？还是一百万？', 'ɪz ɪt faɪv,ziəɹoʊziəɹoʊ ziəɹoʊ ɪz ɪt hæf ɐ mɪliən ɪz ɪɾ ɐ mɪliən?', '<span>Is</span><span>it</span><span>5,000</span><span>Is</span><span>it</span><span tid="54569">half</span><span>a</span><span tid="54571">million</span><span>Is</span><span>it</span><span>a</span><span tid="54575">million?</span>'
