INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 36, 175.12, 179.3, 'I want you to take a moment and I want you to think about the person who had the most influence over you in your life.', '我想让你花点时间，想一想在你人生中对你影响最大的人是谁。', 'aɪ wɔnt juː tə teɪk ɐ moʊmənt ænd aɪ wɔnt juː tə θɪŋk ɐbaʊt ðə pɜːsən huː hæd ðə moʊst ɪnfluːəns oʊvɚ juː ɪn jʊɹ laɪf.', '<span>I</span><span>want</span><span>you</span><span>to</span><span pid="1786" class="highlight highlight-i">take a moment</span><span>and</span><span>I</span><span>want</span><span>you</span><span>to</span><span>think</span><span>about</span><span>the</span><span tid="54591">person</span><span>who</span><span>had</span><span>the</span><span tid="54595">most</span><span tid="54596" class="highlight highlight-a">influence</span><span tid="54597">over</span><span>you</span><span>in</span><span>your</span><span tid="54601">life.</span>'
