INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 37, 179.48, 181.38, 'And now I want you to ask yourself this question.', '然后我想让你问自己一个问题。', 'ænd naʊ aɪ wɔnt juː tʊ æsk jɔːɹsɛlf ðɪs kwɛstʃən.', '<span>And</span><span tid="54603">now</span><span>I</span><span>want</span><span>you</span><span>to</span><span tid="54608">ask</span><span tid="54609">yourself</span><span>this</span><span tid="54611">question.</span>'
