INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 3.62, 'I don''t really ever talk about money and there''s a reason for that.', '我其实很少谈论金钱，这是有原因的。', '/aɪ doʊnt ɹiəli ɛvɚ tɔːk ɐbaʊt mʌni ænd ðɛɹz ɐ ɹiːzən fɔːɹ ðæt./', '<span>I</span><span>don''t</span><span tid="51448">really</span><span tid="51449" class="highlight highlight-a">ever</span><span tid="51450">talk</span><span>about</span><span tid="51452">money</span><span>and</span><span pid="261" class="highlight highlight-l">there''s a reason for that.</span>'
