INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 72.06, 76.72, 'Like there''s a process that needs to happen in between where you are now and where you want to be.', '就像你现在的位置和你想去的地方之间，其实需要一个过程。', '/laɪk ðɛɹz ɐ pɹɑːsɛs ðæt niːdz tə hæpən ɪn bᵻtwiːn wɛɹ juː ɑːɹ naʊ ænd wɛɹ juː wɔnt tə biː./', '<span>Like</span><span>there''s</span><span>a</span><span tid="51665" class="highlight highlight-a">process</span><span>that</span><span tid="51667">needs</span><span>to</span><span tid="51669">happen</span><span pid="247" class="highlight highlight-i">in between</span><span>where</span><span>you</span><span>are</span><span tid="51675">now</span><span>and</span><span>where</span><span>you</span><span>want</span><span>to</span><span>be.</span>'
