INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 113, 467.18, 470.46, 'When you implement these skills, you''re not going to do them perfect.', '当你运用这些技能时，你不会做得完美。', '/wɛn juː ɪmplɪmənt ðiːz skɪlz, jʊɹ nɑːt ɡoʊɪŋ tə duː ðɛm pɜːfɛkt./', '<span>When</span><span>you</span><span tid="52820" class="highlight highlight-a">implement</span><span>these</span><span tid="52822">skills,</span><span>you''re</span><span>not</span><span>going</span><span>to</span><span>do</span><span>them</span><span tid="52829">perfect.</span>'
FROM episodes e WHERE e.video_id = '074upYDO5FBjKTE';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 114, 470.46, 473.98, 'You''re going to do them, you''re going to be like, I could have did that better.', '你会觉得“我本可以做得更好”。', '/jʊɹ ɡoʊɪŋ tə duː ðɛm, jʊɹ ɡoʊɪŋ təbi laɪk, aɪ kʊdɐv dɪd ðæt bɛɾɚ./', '<span>You''re</span><span>going</span><span>to</span><span>do</span><span>them,</span><span>you''re</span><span>going</span><span>to</span><span>be</span><span>like,</span><span>I</span><span>could</span><span>have</span><span>did</span><span>that</span><span tid="52845">better.</span>'
