INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 115, 473.98, 475.04, 'But it''s repetition.', '但这就是重复的过程。', '/bʌt ɪts ɹɛpətɪʃən./', '<span>But</span><span>it''s</span><span tid="52848" class="highlight highlight-a">repetition.</span>'
