INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 133, 568.4, 574.16, 'you have new experiences, your life just starts to unfold towards things that are aligned with abundance.', '你会拥有新的体验，你的人生会逐渐展开，走向丰盛。', '/juː hæv nuː ɛkspiəɹɪənsᵻz, jʊɹ laɪf dʒʌst stɑːɹts tʊ ʌnfoʊld təwɔːɹdz θɪŋz ðæt ɑːɹ ɐlaɪnd wɪð ɐbʌndəns./', '<span>you</span><span>have</span><span tid="53131">new</span><span tid="53132">experiences,</span><span>your</span><span tid="53134">life</span><span>just</span><span tid="53136">starts</span><span>to</span><span tid="53138" class="highlight highlight-a">unfold</span><span tid="53139">towards</span><span>things</span><span>that</span><span>are</span><span pid="305" class="highlight highlight-c">aligned with</span><span tid="53145" class="highlight highlight-a">abundance.</span>'
