INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 134, 574.16, 576.32, 'Do you understand Cool.', '你明白了吗？很好。', '/duː juː ʌndɚstænd kuːl./', '<span>Do</span><span>you</span><span tid="53148">understand</span><span tid="53149" class="highlight highlight-a">Cool.</span>'
