INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 135, 576.32, 578.36, 'So implement these things, my friend.', '所以去落实这些吧，朋友。', '/soʊ ɪmplɪmənt ðiːz θɪŋz, maɪ fɹɛnd./', '<span>So</span><span tid="53151" class="highlight highlight-a">implement</span><span>these</span><span>things,</span><span>my</span><span tid="53155">friend.</span>'
FROM episodes e WHERE e.video_id = '074upYDO5FBjKTE';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 136, 578.36, 579.62, 'It starts now.', '从现在开始。', '/ɪt stɑːɹts naʊ./', '<span>It</span><span tid="53157">starts</span><span tid="53158">now.</span>'
