INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 137, 579.62, 582.98, 'That''s why I gave you these practical, you can do all of these things starting today.', '这就是我为什么给你这些实际的建议，你今天就能开始做。', '/ðæts waɪ aɪ ɡeɪv juː ðiːz pɹæktɪkəl, juː kæn duː ɔːl ʌv ðiːz θɪŋz stɑːɹɾɪŋ tədeɪ./', '<span>That''s</span><span>why</span><span>I</span><span tid="53162">gave</span><span>you</span><span>these</span><span tid="53165" class="highlight highlight-a">practical,</span><span>you</span><span>can</span><span>do</span><span>all</span><span>of</span><span>these</span><span>things</span><span tid="53173">starting</span><span tid="53174">today.</span>'
