INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 138, 582.98, 586.7, 'I''m not giving you the top 10 tricks to make 10 grand this month.', '我不是在给你“本月赚一万美金的十大技巧”。', '/aɪm nɑːt ɡɪvɪŋ juː ðə tɑːp tɛn tɹɪks tə meɪk tɛn ɡɹænd ðɪs mʌnθ./', '<span>I''m</span><span>not</span><span tid="53177">giving</span><span>you</span><span>the</span><span tid="53180" class="highlight highlight-a">top</span><span>10</span><span tid="53182" class="highlight highlight-a">tricks</span><span>to</span><span tid="53184">make</span><span>10</span><span tid="53186" class="highlight highlight-a">grand</span><span>this</span><span tid="53188">month.</span>'
