INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 139, 586.7, 590.16, 'I''m giving you real advice that you can start doing now.', '我给你的是可以立刻开始执行的真实建议。', '/aɪm ɡɪvɪŋ juː ɹiːəl ɐdvaɪs ðæt juː kæn stɑːɹt duːɪŋ naʊ./', '<span>I''m</span><span tid="53190">giving</span><span>you</span><span tid="53192">real</span><span tid="53193">advice</span><span>that</span><span>you</span><span>can</span><span tid="53197">start</span><span>doing</span><span tid="53199">now.</span>'
FROM episodes e WHERE e.video_id = '074upYDO5FBjKTE';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 140, 590.16, 596.4, 'And I''ve walked you through the mental aspect, the psychology of detaching yourself from this want.', '而且我已经带你走过了心态层面，带你理解如何在心理上把自己从“想要”里抽离出来。', '/ænd aɪv wɔːkt juː θɹuː ðə mɛntəl æspɛkt, ðə saɪkɑːlədʒi ʌv dɪtætʃɪŋ jɔːɹsɛlf fɹʌm ðɪs wɔnt./', '<span>And</span><span>I''ve</span><span pid="260" class="highlight highlight-d">walked you through</span><span>the</span><span tid="53206" class="highlight highlight-a">mental</span><span tid="53207" class="highlight highlight-a">aspect,</span><span>the</span><span tid="53209" class="highlight highlight-a">psychology</span><span>of</span><span tid="53211" class="highlight highlight-a">detaching</span><span tid="53212">yourself</span><span>from</span><span>this</span><span>want.</span>'
FROM episodes e WHERE e.video_id = '074upYDO5FBjKTE';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 141, 596.4, 601.06, 'Because the more you try to attach to something, the further it runs away from you.', '因为你越是拼命去抓住某样东西，它就越会离你远去。', '/bɪkʌz ðə mɔːɹ juː tɹaɪ tʊ ɐtætʃ tə sʌmθɪŋ, ðə fɜːðɚɹ ɪt ɹʌnz ɐweɪ fɹʌm juː./', '<span>Because</span><span>the</span><span>more</span><span>you</span><span tid="53220">try</span><span>to</span><span pid="306" class="highlight highlight-d">attach to</span><span>something,</span><span>the</span><span tid="53226" class="highlight highlight-a">further</span><span>it</span><span pid="307" class="highlight highlight-d">runs away from</span><span>you.</span>'
FROM episodes e WHERE e.video_id = '074upYDO5FBjKTE';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 142, 601.06, 604.62, 'I appreciate your time, and I will see you soon.', '感谢你的时间，我们很快再见。', '/aɪ ɐpɹiːʃɪeɪt jʊɹ taɪm, ænd aɪ wɪl siː juː suːn./', '<span>I</span><span tid="53233" class="highlight highlight-a">appreciate</span><span>your</span><span tid="53235">time,</span><span>and</span><span>I</span><span>will</span><span tid="53239">see</span><span>you</span><span tid="53241">soon.</span>'
