INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.7, 4.06, 'I love that in Berlin you can be whoever you want to be.', '在柏林，你可以成为任何你想成为的人。', '/aɪ lʌv ðæt ɪn bɜːlɪn juː kæn biː huːɛvɚ juː wɔnt tə biː./', '<span>I</span><span tid="50539">love</span><span>that</span><span>in</span><span tid="50542">Berlin</span><span>you</span><span>can</span><span>be</span><span tid="50546">whoever</span><span>you</span><span>want</span><span>to</span><span>be.</span>'
FROM episodes e WHERE e.video_id = '075hOo7AXwPYToQ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 4.06, 10.5, 'And for myself, I love participating in the startup scene, in the arts, in the dance clubs.', '而对我来说，我喜欢参与创业圈、艺术界，还有舞蹈俱乐部。', '/ænd fɔːɹ maɪsɛlf, aɪ lʌv pɑːɹtɪsᵻpeɪɾɪŋ ɪnðə stɑːɹɾʌp siːn, ɪnðɪ ɑːɹts, ɪnðə dæns klʌbz./', '<span>And</span><span>for</span><span tid="50553">myself,</span><span>I</span><span tid="50555">love</span><span tid="50556" class="highlight highlight-a">participating</span><span>in</span><span>the</span><span tid="50559" class="highlight highlight-a">startup</span><span tid="50560" class="highlight highlight-a">scene,</span><span>in</span><span>the</span><span tid="50563">arts,</span><span>in</span><span>the</span><span tid="50566">dance</span><span tid="50567">clubs.</span>'
FROM episodes e WHERE e.video_id = '075hOo7AXwPYToQ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 10.5, 16.1, 'It really feels like an adult Disneyland and we welcome everyone here.', '这里真的就像是成人版的迪士尼乐园，我们欢迎所有人。', '/ɪt ɹiəli fiːlz laɪk ɐn ɐdʌlt dɪsnɪlænd ænd wiː wɛlkʌm ɛvɹɪwʌn hɪɹ./', '<span>It</span><span tid="50569">really</span><span tid="50570">feels</span><span>like</span><span>an</span><span tid="50573" class="highlight highlight-a">adult</span><span tid="50574" class="highlight highlight-a">Disneyland</span><span>and</span><span>we</span><span tid="50577">welcome</span><span tid="50578">everyone</span><span>here.</span>'
FROM episodes e WHERE e.video_id = '075hOo7AXwPYToQ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 16.1, 31.28, 'I''m Vanessa Wachtmeister, I''m 34 years old and I currently live in Berlin, Germany with my husband and my two cats.', '我叫Vanessa Wachtmeister，今年34岁，现在和我丈夫还有两只猫住在德国柏林。', '/aɪm vɐnɛsə wætʃtmaɪstɚ, aɪm θɜːɾi fɔːɹ jɪɹz oʊld ænd aɪ kɜːɹəntli lɪv ɪn bɜːlɪn, dʒɜːməni wɪð maɪ hʌsbənd ænd maɪ tuː kæts./', '<span>I''m</span><span tid="50581">Vanessa</span><span tid="50582">Wachtmeister,</span><span>I''m</span><span>34</span><span tid="50585">years</span><span tid="50586">old</span><span>and</span><span>I</span><span tid="50589" class="highlight highlight-a">currently</span><span tid="50590">live</span><span>in</span><span tid="50592">Berlin,</span><span tid="50593">Germany</span><span>with</span><span>my</span><span tid="50596">husband</span><span>and</span><span>my</span><span>two</span><span tid="50600">cats.</span>'
FROM episodes e WHERE e.video_id = '075hOo7AXwPYToQ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 31.28, 42.58, 'I''m originally from Los Angeles, California, but I''ve been abroad for the last 12 years.', '我原本来自美国加州洛杉矶，但过去12年一直在国外生活。', '/aɪm ɚɹɪdʒɪnəli fɹʌm lɑːs ændʒəlɪs, kælɪfɔːɹniə, bʌt aɪv bɪn ɐbɹɔːd fɚðə læst twɛlv jɪɹz./', '<span>I''m</span><span tid="50602" class="highlight highlight-a">originally</span><span>from</span><span tid="50604">Los</span><span tid="50605">Angeles,</span><span tid="50606">California,</span><span>but</span><span>I''ve</span><span>been</span><span tid="50610" class="highlight highlight-a">abroad</span><span>for</span><span>the</span><span tid="50613" class="highlight highlight-a">last</span><span>12</span><span tid="50615">years.</span>'
