INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 45.28, 50.8, 'Most people don''t think you can get good Mexican food out here, but you can.', '大多数人觉得在这里吃不到正宗的墨西哥菜，但其实可以。', '/moʊst piːpəl doʊnt θɪŋk juː kæn ɡɛt ɡʊd mɛksɪkən fuːd aʊt hɪɹ, bʌt juː kæn./', '<span tid="50623">Most</span><span tid="50624">people</span><span>don''t</span><span>think</span><span>you</span><span>can</span><span>get</span><span>good</span><span tid="50631">Mexican</span><span tid="50632">food</span><span tid="50633">out</span><span>here,</span><span>but</span><span>you</span><span>can.</span>'
