INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 29, 160.2, 165.74, 'We spend so much time here because we love to cook.', '我们花很多时间待在厨房，因为我们喜欢做饭。', '/wiː spɛnd soʊ mʌtʃ taɪm hɪɹ bɪkʌz wiː lʌv tə kʊk./', '<span>We</span><span tid="50881">spend</span><span>so</span><span tid="50883">much</span><span tid="50884">time</span><span>here</span><span>because</span><span>we</span><span tid="50888">love</span><span>to</span><span tid="50890" class="highlight highlight-a">cook.</span>'
