FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 5.98, 6.92, 'I mean, it couldn''t be clearer.', '我的意思是，这再清楚不过了。', '/aɪ miːn, ɪt kʊdənt biː klɪɹɚ./', '<span>I</span><span tid="48593">mean,</span><span>it</span><span>couldn''t</span><span>be</span><span tid="48597">clearer.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 6.92, 13.72, 'Let me give you the good side of boredom in general.', '让我来告诉你无聊的积极一面。', '/lɛt miː ɡɪv juː ðə ɡʊd saɪd ʌv bɔːɹdəm ɪn dʒɛnɚɹəl./', '<span>Let</span><span>me</span><span tid="48600">give</span><span>you</span><span>the</span><span>good</span><span tid="48604">side</span><span>of</span><span tid="48606" class="highlight highlight-a">boredom</span><span pid="313" class="highlight highlight-i">in general.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 13.72, 26.74, 'Boredom is a tendency for us to not be occupied otherwise cognitively which switches over our thinking system to use a part of our brain that''s called the default mode network.', '无聊其实是我们在没有其他认知任务的时候，大脑会切换到一个叫做“预设模式网络”的系统。', '/bɔːɹdəm ɪz ɐ tɛndənsi fɔːɹ ʌs tə nɑːt biː ɑːkjʊpaɪd ʌðɚwaɪz kɑːɡnᵻtɪvli wɪtʃ swɪtʃᵻz oʊvɚɹ aʊɚ θɪŋkɪŋ sɪstəm tə juːz ɐ pɑːɹt ʌv aʊɚ bɹeɪn ðæts kɔːld ðə dᵻfɔlt moʊd nɛtwɜːk./', '<span tid="48609" class="highlight highlight-a">Boredom</span><span>is</span><span>a</span><span tid="48612" class="highlight highlight-a">tendency</span><span>for</span><span>us</span><span>to</span><span>not</span><span>be</span><span tid="48618">occupied</span><span tid="48619" class="highlight highlight-a">otherwise</span><span tid="48620" class="highlight highlight-a">cognitively</span><span>which</span><span pid="316" class="highlight highlight-d">switches over</span><span>our</span><span tid="48625">thinking</span><span tid="48626">system</span><span>to</span><span tid="48628">use</span><span>a</span><span tid="48630">part</span><span>of</span><span>our</span><span tid="48633">brain</span><span>that''s</span><span tid="48635">called</span><span>the</span><span pid="317" class="highlight highlight-b">default mode network.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 26.74, 28.52, 'That sounds fancy It''s really not.', '听起来很高大上，其实并不是。', '/ðæt saʊndz fænsi ɪts ɹiəli nɑːt./', '<span>That</span><span tid="48641">sounds</span><span tid="48642" class="highlight highlight-a">fancy</span><span>It''s</span><span tid="48644">really</span><span>not.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 28.52, 34.94, 'The default mode network is a bunch of structures in your brain that switch on when you don''t have anything else to think about.', '预设模式网络就是大脑里一堆结构，在你没有别的事情想的时候会被激活。', '/ðə dᵻfɔlt moʊd nɛtwɜːk ɪz ɐ bʌntʃ ʌv stɹʌktʃɚz ɪn jʊɹ bɹeɪn ðæt swɪtʃ ɔn wɛn juː doʊnt hæv ɛnɪθɪŋ ɛls tə θɪŋk ɐbaʊt./', '<span>The</span><span pid="318" class="highlight highlight-b">default mode network</span><span>is</span><span pid="308" class="highlight highlight-i">a bunch of</span><span tid="48654" class="highlight highlight-a">structures</span><span>in</span><span>your</span><span tid="48657">brain</span><span>that</span><span pid="323" class="highlight highlight-d">switch on</span><span>when</span><span>you</span><span>don''t</span><span>have</span><span tid="48665">anything</span><span tid="48666">else</span><span>to</span><span>think</span><span>about.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 34.94, 39.04, 'So you forgot your phone and you''re sitting in a light, for example.', '比如你忘带手机，正坐在红灯前等灯。', '/soʊ juː fɚɡɑːt jʊɹ foʊn ænd jʊɹ sɪɾɪŋ ɪn ɐ laɪt, fɔːɹ ɛɡzæmpəl./', '<span>So</span><span>you</span><span tid="48672">forgot</span><span>your</span><span tid="48674">phone</span><span>and</span><span>you''re</span><span tid="48677">sitting</span><span>in</span><span>a</span><span tid="48680" class="highlight highlight-a">light,</span><span>for</span><span tid="48682">example.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 39.04, 41.82, 'That''s when your default mode network goes on.', '这时候你的预设模式网络就会启动。', '/ðæts wɛn jʊɹ dᵻfɔlt moʊd nɛtwɜːk ɡoʊz ɔn./', '<span>That''s</span><span>when</span><span>your</span><span pid="319" class="highlight highlight-b">default mode network</span><span>goes</span><span>on.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 10, 41.82, 43.32, 'We don''t like it.', '我们并不喜欢这种感觉。', '/wiː doʊnt laɪk ɪt./', '<span>We</span><span>don''t</span><span>like</span><span>it.</span>'
