INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 61.58, 64.0, 'Sit there bored or get a shock.', '要么坐着无聊，要么来一下电击。', '/sɪt ðɛɹ bɔːɹd ɔːɹ ɡɛt ɐ ʃɑːk./', '<span tid="48759">Sit</span><span>there</span><span tid="48761">bored</span><span>or</span><span>get</span><span>a</span><span tid="48765">shock.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 64.0, 68.24, 'A big majority of the participants gave themselves shocks instead of thinking about nothing.', '结果大多数参与者宁愿电自己，也不愿什么都不想。', '/ɐ bɪɡ mədʒɔːɹᵻɾi ʌvðə pɑːɹtɪsɪpənts ɡeɪv ðɛmsɛlvz ʃɑːks ɪnstɛd ʌv θɪŋkɪŋ ɐbaʊt nʌθɪŋ./', '<span>A</span><span tid="48767">big</span><span tid="48768" class="highlight highlight-a">majority</span><span>of</span><span>the</span><span tid="48771" class="highlight highlight-a">participants</span><span tid="48772">gave</span><span tid="48773">themselves</span><span tid="48774">shocks</span><span tid="48775" class="highlight highlight-a">instead</span><span>of</span><span>thinking</span><span>about</span><span tid="48779">nothing.</span>'
FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
