INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 72.42, 77.86, 'Well, because the default mode network makes us think about things that might be kind of uncomfortable.', '因为预设模式网络会让我们想到一些可能不太舒服的事情。', '/wɛl, bɪkʌz ðə dᵻfɔlt moʊd nɛtwɜːk meɪks ʌs θɪŋk ɐbaʊt θɪŋz ðæt maɪt biː kaɪnd ʌv ʌŋkʌmftəbəl./', '<span tid="48791">Well,</span><span>because</span><span>the</span><span pid="320" class="highlight highlight-b">default mode network</span><span tid="48797">makes</span><span>us</span><span>think</span><span>about</span><span>things</span><span>that</span><span tid="48803" class="highlight highlight-a">might</span><span>be</span><span tid="48805">kind</span><span>of</span><span tid="48807">uncomfortable.</span>'
