FROM episodes e WHERE e.video_id = '077p0utRNLcA1Ej';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 92.58, 97.66, 'One of the reasons that we have such an explosion of depression and anxiety in our society today is because.', '我们今天社会里抑郁和焦虑爆发的一个原因就是，', '/wʌn ʌvðə ɹiːzənz ðæt wiː hæv sʌtʃ ɐn ɛksploʊʒən ʌv dᵻpɹɛʃən ænd æŋzaɪəɾi ɪn aʊɚ səsaɪəɾi tədeɪ ɪz bɪkʌz./', '<span>One</span><span>of</span><span>the</span><span tid="48857">reasons</span><span>that</span><span>we</span><span>have</span><span tid="48861">such</span><span>an</span><span tid="48863" class="highlight highlight-a">explosion</span><span>of</span><span tid="48865" class="highlight highlight-a">depression</span><span>and</span><span tid="48867" class="highlight highlight-a">anxiety</span><span>in</span><span>our</span><span tid="48870">society</span><span tid="48871">today</span><span>is</span><span>because.</span>'
