INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 59, 306.04, 313.6, 'To make this dye pot, I simmered the berries with water for about an hour on low heat.', '为了做这锅染料，我用小火把果子和水煮了大概一个小时。', '/tə meɪk ðɪs daɪ pɑːt, aɪ sɪmɚd ðə bɛɹiz wɪð wɔːɾɚ fɔːɹ ɐbaʊt ɐn aʊɚɹ ɔn loʊ hiːt./', '<span>To</span><span tid="47899">make</span><span>this</span><span tid="47901" class="highlight highlight-a">dye</span><span tid="47902" class="highlight highlight-a">pot,</span><span>I</span><span tid="47904" class="highlight highlight-a">simmered</span><span>the</span><span tid="47906" class="highlight highlight-a">berries</span><span>with</span><span tid="47908">water</span><span>for</span><span>about</span><span>an</span><span tid="47912">hour</span><span>on</span><span pid="681" class="highlight highlight-c">low heat.</span>'
