INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 64, 336.36, 343.819, 'I was honestly so shocked when I put the fabric in, it changed color almost immediately.', '当我把布放进去时，看到它几乎立刻变色，我真是惊呆了。', '/aɪ wʌz ɑːnɪstli soʊ ʃɑːkt wɛn aɪ pʊt ðə fæbɹɪk ɪn, ɪt tʃeɪndʒd kʌlɚɹ ɔːlmoʊst ɪmiːdɪətli./', '<span>I</span><span>was</span><span tid="47977" class="highlight highlight-a">honestly</span><span>so</span><span tid="47979" class="highlight highlight-a">shocked</span><span>when</span><span>I</span><span tid="47982">put</span><span>the</span><span tid="47984" class="highlight highlight-a">fabric</span><span>in,</span><span>it</span><span tid="47987">changed</span><span tid="47988">color</span><span tid="47989">almost</span><span tid="47990" class="highlight highlight-a">immediately.</span>'
