INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 65, 343.819, 349.72, 'I was actually kind of nervous that the fabric would end up becoming, like, too bright.', '其实我还有点担心颜色会太亮。', '/aɪ wʌz æktʃuːəli kaɪnd ʌv nɜːvəs ðætðə fæbɹɪk wʊd ɛnd ʌp bᵻkʌmɪŋ, laɪk, tuː bɹaɪt./', '<span>I</span><span>was</span><span tid="47993">actually</span><span tid="47994">kind</span><span>of</span><span tid="47996">nervous</span><span>that</span><span>the</span><span tid="47999" class="highlight highlight-a">fabric</span><span>would</span><span tid="48001">end</span><span>up</span><span tid="48003">becoming,</span><span>like,</span><span>too</span><span tid="48006">bright.</span>'
