INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 67, 354.4, 358.22, 'We all imagine where we should be by a certain age.', '我们总会想象自己在某个年龄该到什么阶段。', '/wiː ɔːl ɪmædʒɪn wɛɹ wiː ʃʊd biː baɪ ɐ sɜːʔn̩ eɪdʒ./', '<span>We</span><span>all</span><span tid="48024" class="highlight highlight-a">imagine</span><span>where</span><span>we</span><span tid="48027">should</span><span>be</span><span>by</span><span>a</span><span tid="48031" class="highlight highlight-a">certain</span><span tid="48032" class="highlight highlight-a">age.</span>'
