INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 68, 358.22, 363.48, 'and it''s hard when life doesn''t match that picture in our heads.', '可当现实和脑海里的画面不符时，就会很难受。', '/ænd ɪts hɑːɹd wɛn laɪf dʌzənt mætʃ ðæt pɪktʃɚɹ ɪn aʊɚ hɛdz./', '<span>and</span><span>it''s</span><span tid="48035">hard</span><span>when</span><span tid="48037">life</span><span>doesn''t</span><span tid="48039">match</span><span>that</span><span tid="48041">picture</span><span>in</span><span>our</span><span tid="48044">heads.</span>'
