INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 70, 369.8, 376.54, 'I certainly did not think that I would be here living alone in the mountains at this age.', '我从没想过这个年纪会一个人住在山里。', '/aɪ sɜːʔn̩li dɪdnɑːt θɪŋk ðæt aɪ wʊd biː hɪɹ lɪvɪŋ ɐloʊn ɪnðə maʊntɪnz æt ðɪs eɪdʒ./', '<span>I</span><span tid="48059" class="highlight highlight-a">certainly</span><span>did</span><span>not</span><span>think</span><span>that</span><span>I</span><span>would</span><span>be</span><span>here</span><span tid="48068">living</span><span tid="48069">alone</span><span>in</span><span>the</span><span tid="48072">mountains</span><span>at</span><span>this</span><span tid="48075" class="highlight highlight-a">age.</span>'
