INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 82, 439.22, 445.3, 'I have to say, I''m a little bit nervous about spending the winter alone here.', '老实说，我有点担心要一个人在这里过冬。', '/aɪ hæv tə seɪ, aɪm ɐ lɪɾəl bɪt nɜːvəs ɐbaʊt spɛndɪŋ ðə wɪntɚɹ ɐloʊn hɪɹ./', '<span>I</span><span pid="663" class="highlight highlight-i">have to say,</span><span>I''m</span><span>a</span><span tid="48260">little</span><span tid="48261">bit</span><span tid="48262">nervous</span><span>about</span><span tid="48264">spending</span><span>the</span><span tid="48266">winter</span><span tid="48267">alone</span><span>here.</span>'
FROM episodes e WHERE e.video_id = '078Ea0JuDwyiNFs';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
