INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 84, 455.079, 460.379, 'And I''m thinking to myself, like, wow, can I do this?', '我心里会想：天啊，我真的能撑过去吗？', '/ænd aɪm θɪŋkɪŋ tə maɪsɛlf, laɪk, waʊ, kæn aɪ duː ðɪs?/', '<span>And</span><span>I''m</span><span>thinking</span><span>to</span><span tid="48291">myself,</span><span>like,</span><span tid="48293">wow,</span><span>can</span><span>I</span><span>do</span><span>this?</span>'
