INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 63, 353.284, 356.188, 'To show you what’s new, here’s Megan.', '接下来由 Megan 带来介绍。', '/tə ʃoʊ juː wʌts nuː, hɪɹz mɛɡən./', '<span>To</span><span tid="46628">show</span><span>you</span><span>what’s</span><span tid="46631">new,</span><span>here’s</span><span tid="46633">Megan.</span>'
FROM episodes e WHERE e.video_id = '079h26qT9WubuTa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 64, 356.188, 359.725, '♪ “Bikini” by Nick León & Erika De Casier ♪', '♪ “Bikini” by Nick León & Erika De Casier ♪', '/ “bɪkiːni” baɪ nɪk lɛɑːn ænd ɛɹɪkə də keɪsiɚ/', '<span>♪</span><span tid="46635">“Bikini”</span><span>by</span><span tid="46637">Nick</span><span tid="46638">León</span><span>&</span><span tid="46640">Erika</span><span tid="46641">De</span><span tid="46642">Casier</span><span>♪</span>'
