INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 66, 370.336, 375.408, 'Our Fusion technology combines the capabilities of two cameras in one,', '我们的 Fusion 技术将两颗镜头的能力结合在一起，', '/aʊɚ fjuːʒən tɛknɑːlədʒi kəmbaɪnz ðə keɪpəbɪlᵻɾiz ʌv tuː kæmɹəz ɪn wʌn,/', '<span>Our</span><span tid="46655" class="highlight highlight-a">Fusion</span><span tid="46656">technology</span><span tid="46657">combines</span><span>the</span><span tid="46659" class="highlight highlight-a">capabilities</span><span>of</span><span>two</span><span tid="46662" class="highlight highlight-a">cameras</span><span>in</span><span>one,</span>'
