INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 67, 375.408, 379.812, 'with a main camera and an optical-quality 2x telephoto,', '配备主摄和具备光学品质的 2 倍长焦，', '/wɪð ɐ meɪn kæmɹə ænd ɐn ɑːptɪkəlkwɔlᵻɾi tuː ɛks tɛlᵻfoʊɾoʊ,/', '<span>with</span><span>a</span><span tid="46667">main</span><span tid="46668" class="highlight highlight-a">camera</span><span>and</span><span>an</span><span tid="46671">optical-quality</span><span tid="46672">2x</span><span tid="46673" class="highlight highlight-a">telephoto,</span>'
