INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 68, 379.812, 382.38, 'each with dedicated image pipelines.', '每颗镜头都有独立的图像处理管线。', '/iːtʃ wɪð dɛdᵻkeɪɾᵻd ɪmɪdʒ paɪplaɪnz./', '<span tid="46674">each</span><span>with</span><span tid="46676" class="highlight highlight-a">dedicated</span><span tid="46677">image</span><span tid="46678" class="highlight highlight-a">pipelines.</span>'
