INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 71, 391.789, 398.563, 'And for everyday photos, the 24MP default resolution provides the perfect balance,', '而在日常拍摄中，默认 2400 万像素分辨率提供理想平衡，', '/ænd fɔːɹ ɛvɹɪdeɪ foʊɾoʊz, ðə twɛnti fɔːɹ ɛmpiː dᵻfɔlt ɹɛzəluːʃən pɹəvaɪdz ðə pɜːfɛkt bæləns,/', '<span>And</span><span>for</span><span tid="46701">everyday</span><span tid="46702">photos,</span><span>the</span><span tid="46704">24MP</span><span tid="46705">default</span><span tid="46706" class="highlight highlight-a">resolution</span><span tid="46707" class="highlight highlight-a">provides</span><span>the</span><span tid="46709">perfect</span><span tid="46710" class="highlight highlight-a">balance,</span>'
