INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 73, 403.735, 406.105, 'that’s ideal for saving and sharing.', '非常适合保存和分享。', '/ðæts aɪdiəl fɔːɹ seɪvɪŋ ænd ʃɛɹɪŋ./', '<span>that’s</span><span tid="46723" class="highlight highlight-a">ideal</span><span>for</span><span tid="46725">saving</span><span>and</span><span tid="46727" class="highlight highlight-a">sharing.</span>'
