INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 74, 406.105, 411.778, 'At 2x, the optical-quality telephoto gets you closer to the subject,', '在 2 倍变焦下，光学级长焦让你更接近拍摄对象，', '/æt tuː ɛks, ðɪ ɑːptɪkəlkwɔlᵻɾi tɛlᵻfoʊɾoʊ ɡɛts juː kloʊsɚ tə ðə sʌbdʒɛkt,/', '<span>At</span><span tid="46729">2x,</span><span>the</span><span tid="46731">optical-quality</span><span tid="46732" class="highlight highlight-a">telephoto</span><span>gets</span><span>you</span><span tid="46735">closer</span><span>to</span><span>the</span><span tid="46738">subject,</span>'
