INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 71, 361.36, 364.28, 'The first is with harsh criticism.', '第一种是严厉批评。', '/ðə fɜːst ɪz wɪð hɑːɹʃ kɹɪɾɪsɪzəm./', '<span>The</span><span tid="57478">first</span><span>is</span><span>with</span><span tid="57481" class="highlight highlight-a">harsh</span><span tid="57482" class="highlight highlight-a">criticism.</span>'
