INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 72, 364.28, 370.48, 'The son comes in, shows the father the math grade, and the father says, I''m ashamed of you.', '儿子拿着数学成绩单进来，父亲说，我为你感到羞耻。', '/ðə sʌn kʌmz ɪn, ʃoʊz ðə fɑːðɚ ðə mæθ ɡɹeɪd, ænd ðə fɑːðɚ sɛz, aɪm ɐʃeɪmd ʌv juː./', '<span>The</span><span tid="57484">son</span><span tid="57485">comes</span><span>in,</span><span tid="57487">shows</span><span>the</span><span tid="57489">father</span><span>the</span><span tid="57491">math</span><span tid="57492">grade,</span><span>and</span><span>the</span><span tid="57495">father</span><span tid="57496">says,</span><span>I''m</span><span pid="842" class="highlight highlight-i">ashamed of</span><span>you.</span>'
FROM episodes e WHERE e.video_id = '080jUzRCjJSFiO5';
