FROM episodes e WHERE e.video_id = '080jUzRCjJSFiO5';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 82, 401.64, 406.1, 'But what if the father takes a compassionate approach?', '但是，如果父亲采取一个富有同情心的方式呢？', '/bʌt wʌt ɪf ðə fɑːðɚ teɪks ɐ kəmpæʃənət ɐpɹoʊtʃ?/', '<span>But</span><span>what</span><span>if</span><span>the</span><span tid="57588">father</span><span tid="57589">takes</span><span>a</span><span tid="57591" class="highlight highlight-a">compassionate</span><span tid="57592" class="highlight highlight-a">approach?</span>'
FROM episodes e WHERE e.video_id = '080jUzRCjJSFiO5';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 83, 406.1, 410.8, 'The son shows him the failing math grade, and the father says, Ooh, ouch.', '儿子给他看数学不及格的成绩单，父亲说，哎呀', '/ðə sʌn ʃoʊz hɪm ðə feɪlɪŋ mæθ ɡɹeɪd, ænd ðə fɑːðɚ sɛz, uː, aʊtʃ./', '<span>The</span><span tid="57594">son</span><span tid="57595">shows</span><span>him</span><span>the</span><span tid="57598">failing</span><span tid="57599">math</span><span tid="57600">grade,</span><span>and</span><span>the</span><span tid="57603">father</span><span tid="57604">says,</span><span tid="57605">Ooh,</span><span tid="57606" class="highlight highlight-a">ouch.</span>'
