INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 122, 602.62, 603.9, 'This is a true story.', '这是一个真实的故事。', '/ðɪs ɪz ɐ tɹuː stɔːɹi./', '<span>This</span><span>is</span><span>a</span><span tid="58088">true</span><span tid="58089">story.</span>'
