INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 138, 640.32, 649.26, 'So I''m kind of taking this four -year -old, flailing child to the bathroom, which was, of course, occupied, right?', '所以，我带着这个四岁、挥舞的孩子去洗手间，当然是已经有人占着了，吧？', '/soʊ aɪm kaɪnd ʌv teɪkɪŋ ðɪs fɔːɹ jɪɹ oʊld, fleɪlɪŋ tʃaɪld tə ðə bæθɹuːm, wɪtʃ wʌz, ʌv kɔːɹs, ɑːkjʊpaɪd, ɹaɪt?/', '<span>So</span><span>I''m</span><span tid="58205">kind</span><span>of</span><span tid="58207">taking</span><span>this</span><span>four</span><span tid="58210">-year</span><span tid="58211">-old,</span><span tid="58212" class="highlight highlight-a">flailing</span><span tid="58213">child</span><span>to</span><span>the</span><span tid="58216" class="highlight highlight-a">bathroom,</span><span>which</span><span>was,</span><span>of</span><span tid="58220" class="highlight highlight-a">course,</span><span tid="58221">occupied,</span><span tid="58222" class="highlight highlight-a">right?</span>'
