INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 150, 706.18, 707.78, 'You know how to be a good friend.', '你知道如何做一个好朋友。', '/juː noʊ haʊ təbi ɐ ɡʊd fɹɛnd./', '<span>You</span><span>know</span><span>how</span><span>to</span><span>be</span><span>a</span><span>good</span><span tid="58377">friend.</span>'
FROM episodes e WHERE e.video_id = '080jUzRCjJSFiO5';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 151, 707.78, 711.06, 'You know what to say to comfort someone when they are in need.', '你知道当别人需要安慰时，该说些什么。', '/juː noʊ wʌt tə seɪ tə kʌmfɚt sʌmwʌn wɛn ðeɪ ɑːɹ ɪn niːd./', '<span>You</span><span>know</span><span>what</span><span>to</span><span tid="58382">say</span><span>to</span><span tid="58384" class="highlight highlight-a">comfort</span><span tid="58385">someone</span><span>when</span><span>they</span><span>are</span><span>in</span><span tid="58390">need.</span>'
FROM episodes e WHERE e.video_id = '080jUzRCjJSFiO5';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 152, 711.06, 714.74, 'You just have to remember to be a good friend to yourself.', '你只需要记得要对自己做一个好朋友。', '/juː dʒʌst hæv tə ɹᵻmɛmbɚ təbi ɐ ɡʊd fɹɛnd tə jɔːɹsɛlf./', '<span>You</span><span>just</span><span>have</span><span>to</span><span tid="58395">remember</span><span>to</span><span>be</span><span>a</span><span>good</span><span tid="58400">friend</span><span>to</span><span tid="58402">yourself.</span>'
