INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 153, 714.74, 719.9, 'It''s easier than you think, and it really could change your life.', '这比你想象的更容易，而且真的能改变你的人生。', '/ɪts iːziɚ ðɐn juː θɪŋk, ænd ɪt ɹiəli kʊd tʃeɪndʒ jʊɹ laɪf./', '<span>It''s</span><span tid="58404">easier</span><span tid="58405">than</span><span>you</span><span>think,</span><span>and</span><span>it</span><span tid="58410">really</span><span>could</span><span tid="58412">change</span><span>your</span><span tid="58414">life.</span>'
FROM episodes e WHERE e.video_id = '080jUzRCjJSFiO5';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 154, 719.9, 725.44, 'And that''s why I think self-compassion is an idea worth spreading Thank you.', '这就是为什么我认为自我关爱是一个值得传播的理念。谢谢。', '/ænd ðæts waɪ aɪ θɪŋk sɛlfkəmpæʃən ɪz ɐn aɪdiə wɜːθ spɹɛdɪŋ θæŋk juː./', '<span>And</span><span>that''s</span><span>why</span><span>I</span><span>think</span><span tid="58420" class="highlight highlight-a">self-compassion</span><span>is</span><span>an</span><span tid="58423">idea</span><span tid="58424">worth</span><span tid="58425" class="highlight highlight-a">spreading</span><span tid="58426">Thank</span><span>you.</span>'
