INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 13.56, 19.3, 'And that''s just one of the five crazy science experiments that I got to test inside this plane.', '而这只是我在这架飞机上进行的五个疯狂科学实验之一。', '/ænd ðæts dʒʌst wʌn ʌvðə faɪv kɹeɪzi saɪəns ɛkspɛɹɪmənts ðæt aɪ ɡɑːt tə tɛst ɪnsaɪd ðɪs pleɪn./', '<span>And</span><span>that''s</span><span>just</span><span>one</span><span>of</span><span>the</span><span>five</span><span tid="140758">crazy</span><span tid="140759">science</span><span tid="140760" class="highlight highlight-a">experiments</span><span>that</span><span>I</span><span tid="140763">got</span><span>to</span><span tid="140765">test</span><span tid="140766">inside</span><span>this</span><span tid="140768">plane.</span>'
