INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 43.32, 55.12, 'The experiments that I''m going to show you are run by the European Space Agency.', '这些实验是由欧洲航天局进行的。', '/ðɪ ɛkspɛɹɪmənts ðæt aɪm ɡoʊɪŋ tə ʃoʊ juː ɑːɹ ɹʌn baɪ ðə jʊɹɹəpiən speɪs eɪdʒənsi./', '<span>The</span><span tid="140840" class="highlight highlight-a">experiments</span><span>that</span><span>I''m</span><span tid="140843">going</span><span>to</span><span tid="140845">show</span><span>you</span><span>are</span><span tid="140848">run</span><span>by</span><span>the</span><span tid="140851">European</span><span tid="140852">Space</span><span tid="140853">Agency.</span>'
