INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 30, 127.86, 131.16, 'But in zero gravity, something weird happens.', '但在零重力下，发生了一些奇怪的事情。', '/bʌt ɪn ziəɹoʊ ɡɹævᵻɾi, sʌmθɪŋ wɪɹd hæpənz./', '<span>But</span><span>in</span><span pid="352" class="highlight highlight-c">zero gravity,</span><span tid="141088">something</span><span tid="141089" class="highlight highlight-a">weird</span><span tid="141090">happens.</span>'
