INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 31, 131.16, 134.7, 'All of a sudden, all of your blood isn''t getting pulled away naturally anymore.', '突然间，你的血液不再自然地被吸走了。', '/ɔːl əvə sʌdən, ɔːl ʌv jʊɹ blʌd ɪzənt ɡɛɾɪŋ pʊld ɐweɪ nætʃɚɹəli ɛnɪmɔːɹ./', '<span>All</span><span>of</span><span>a</span><span tid="141094">sudden,</span><span>all</span><span>of</span><span>your</span><span tid="141098">blood</span><span tid="141099">isn''t</span><span tid="141100">getting</span><span tid="141101">pulled</span><span tid="141102">away</span><span tid="141103">naturally</span><span tid="141104">anymore.</span>'
