INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 39, 158.44, 163.4, 'So to reach a new equilibrium, that negative pressure is pulling some of your blood away from your brain.', '为了达到新的平衡，负压将一些血液从你的大脑中拉走。', '/soʊ tə ɹiːtʃ ɐ nuː iːkwɪlɪbɹiəm, ðæt nɛɡətɪv pɹɛʃɚɹ ɪz pʊlɪŋ sʌm ʌv jʊɹ blʌd ɐweɪ fɹʌm jʊɹ bɹeɪn./', '<span>So</span><span>to</span><span tid="141189">reach</span><span>a</span><span tid="141191">new</span><span tid="141192" class="highlight highlight-a">equilibrium,</span><span>that</span><span pid="359" class="highlight highlight-c">negative pressure</span><span>is</span><span tid="141197">pulling</span><span>some</span><span>of</span><span>your</span><span tid="141201">blood</span><span tid="141202">away</span><span>from</span><span>your</span><span tid="141205">brain.</span>'
