INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 94, 335.08, 339.0, 'Specifically, how well you can tell if something is upright or not compared to you.', '具体来说，就是测试你能多好地判断某样东西相对于你是否是正的。', '/spəsɪfɪkli, haʊ wɛl juː kæn tɛl ɪf sʌmθɪŋ ɪz ʌpɹaɪt ɔːɹ nɑːt kəmpɛɹd tə juː./', '<span tid="141783" class="highlight highlight-a">Specifically,</span><span>how</span><span tid="141785">well</span><span>you</span><span>can</span><span tid="141788">tell</span><span>if</span><span tid="141790">something</span><span>is</span><span tid="141792" class="highlight highlight-a">upright</span><span>or</span><span>not</span><span tid="141795">compared</span><span>to</span><span>you.</span>'
