INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 96, 342.86, 346.96, 'First, you strap your head into this little cap that measures electrical activity in your brain.', '首先，你要把头戴进这个小帽子里，它会测量你大脑的电活动。', '/fɜːst, juː stɹæp jʊɹ hɛd ɪntʊ ðɪs lɪɾəl kæp ðæt mɛʒɚz ᵻlɛktɹɪkəl æktɪvᵻɾi ɪn jʊɹ bɹeɪn./', '<span tid="141813">First,</span><span>you</span><span tid="141815" class="highlight highlight-a">strap</span><span>your</span><span tid="141817">head</span><span tid="141818">into</span><span>this</span><span tid="141820">little</span><span tid="141821">cap</span><span>that</span><span tid="141823" class="highlight highlight-a">measures</span><span tid="141824" class="highlight highlight-a">electrical</span><span tid="141825">activity</span><span>in</span><span>your</span><span tid="141828">brain.</span>'
