INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 99, 351.16, 354.96, 'And every time it changes, you hit the button on the side to say whether you think it''s tilted or straight.', '每次它变化时，你就按一下旁边的按钮，表示你觉得它是倾斜的还是直的。', '/ænd ɛvɹi taɪm ɪt tʃeɪndʒᵻz, juː hɪt ðə bʌʔn̩ ɔnðə saɪd tə seɪ wɛðɚ juː θɪŋk ɪts tɪltᵻd ɔːɹ stɹeɪt./', '<span>And</span><span tid="141850">every</span><span tid="141851">time</span><span>it</span><span tid="141853">changes,</span><span>you</span><span pid="370" class="highlight highlight-c">hit the button</span><span>on</span><span>the</span><span tid="141860">side</span><span>to</span><span tid="141862">say</span><span tid="141863">whether</span><span>you</span><span tid="141865">think</span><span>it''s</span><span tid="141867" class="highlight highlight-a">tilted</span><span>or</span><span tid="141869" class="highlight highlight-a">straight.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 100, 354.96, 361.04, 'You will put your head inside and do the task for 20 seconds of microgravity exposure.', '你会把头伸进去，在微重力状态下执行20秒这个任务。', '/juː wɪl pʊt jʊɹ hɛd ɪnsaɪd ænd duː ðə tæsk fɔːɹ twɛnti sɛkəndz ʌv maɪkɹoʊɡɹævᵻɾi ɛkspoʊʒɚ./', '<span>You</span><span>will</span><span tid="141872">put</span><span>your</span><span tid="141874">head</span><span tid="141875">inside</span><span>and</span><span>do</span><span>the</span><span tid="141879">task</span><span>for</span><span>20</span><span tid="141882">seconds</span><span>of</span><span tid="141884">microgravity</span><span tid="141885" class="highlight highlight-a">exposure.</span>'
