INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 104, 375.86, 380.12, 'scientists can learn how microgravity affects our ability to perceive verticality.', '科学家就能了解到微重力如何影响我们感知“垂直”的能力。', '/saɪəntɪsts kæn lɜːn haʊ maɪkɹoʊɡɹævᵻɾi ɐfɛkts aʊɚɹ ɐbɪləɾi tə pɚsiːv vɜːɾɪkælᵻɾi./', '<span tid="141939">scientists</span><span>can</span><span tid="141941">learn</span><span>how</span><span tid="141943">microgravity</span><span tid="141944" class="highlight highlight-a">affects</span><span>our</span><span tid="141946" class="highlight highlight-a">ability</span><span>to</span><span tid="141948" class="highlight highlight-a">perceive</span><span tid="141949">verticality.</span>'
