INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 117, 417.639, 419.578, 'Specifically, he''s testing four things.', '具体来说，他要测试四个方面。', '/spəsɪfɪkli, hiːz tɛstɪŋ fɔːɹ θɪŋz./', '<span tid="142070" class="highlight highlight-a">Specifically,</span><span>he''s</span><span tid="142072">testing</span><span>four</span><span tid="142074">things.</span>'
