INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 118, 419.578, 423.46, 'The stiffness of his blade, the resistance of the hydraulic fluid in his knee.', '他的刀锋假肢的刚度，膝盖里液压装置的阻力。', '/ðə stɪfnəs ʌv hɪz bleɪd, ðə ɹᵻsɪstəns ʌvðə haɪdɹɔːlɪk fluːɪd ɪn hɪz niː./', '<span>The</span><span tid="142076" class="highlight highlight-a">stiffness</span><span>of</span><span>his</span><span tid="142079" class="highlight highlight-a">blade,</span><span>the</span><span tid="142081" class="highlight highlight-a">resistance</span><span>of</span><span>the</span><span tid="142084" class="highlight highlight-a">hydraulic</span><span tid="142085" class="highlight highlight-a">fluid</span><span>in</span><span>his</span><span tid="142088">knee.</span>'
