INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 120, 427.12, 430.7, 'We want to be as prepared as possible if I do get the chance to go.', '如果我真的有机会去，我们想尽可能做好准备。', '/wiː wɔnt təbi æz pɹɪpɛɹd æz pɑːsᵻbəl ɪf aɪ duː ɡɛt ðə tʃæns tə ɡoʊ./', '<span>We</span><span tid="142106">want</span><span>to</span><span>be</span><span tid="142109">as</span><span tid="142110" class="highlight highlight-a">prepared</span><span tid="142111">as</span><span tid="142112">possible</span><span>if</span><span>I</span><span>do</span><span tid="142116">get</span><span>the</span><span tid="142118">chance</span><span>to</span><span tid="142120">go.</span>'
