INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 121, 430.7, 433.6, 'What makes this so exciting is that John is really close to going.', '令人兴奋的是，约翰真的已经非常接近了。', '/wʌt meɪks ðɪs soʊ ɛksaɪɾɪŋ ɪz ðæt dʒɑːn ɪz ɹiəli kloʊs tə ɡoʊɪŋ./', '<span>What</span><span tid="142122">makes</span><span>this</span><span>so</span><span tid="142125">exciting</span><span>is</span><span>that</span><span tid="142128">John</span><span>is</span><span tid="142130">really</span><span tid="142131">close</span><span>to</span><span tid="142133">going.</span>'
