SELECT e.id, 126, 450.078, 452.038, 'I am ready to be assigned.', '我已经准备好被分配任务了。', '/aɪɐm ɹɛdi təbi ɐsaɪnd./', '<span>I</span><span>am</span><span tid="142206">ready</span><span>to</span><span>be</span><span tid="142209" class="highlight highlight-a">assigned.</span>'
