INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 131, 470.639, 471.798, 'We''re all rooting for you, John.', '我们都为你加油，约翰。', '/wɪɹ ɔːl ɹuːɾɪŋ fɔːɹ juː, dʒɑːn./', '<span>We''re</span><span>all</span><span pid="372" class="highlight highlight-d">rooting for</span><span>you,</span><span tid="142281">John.</span>'
