INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 147, 525.019, 527.139, 'So it''s hard to make it better.', '所以很难进一步改进。', '/soʊ ɪts hɑːɹd tə meɪk ɪt bɛɾɚ./', '<span>So</span><span>it''s</span><span tid="142472">hard</span><span>to</span><span tid="142474">make</span><span>it</span><span tid="142476">better.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 148, 527.139, 529.038, 'That''s where this experiment comes in.', '这就是这个实验的意义。', '/ðæts wɛɹ ðɪs ɛkspɛɹɪmənt kʌmz ɪn./', '<span>That''s</span><span>where</span><span>this</span><span tid="142480" class="highlight highlight-a">experiment</span><span tid="142481">comes</span><span>in.</span>'
