INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 149, 529.038, 532.278, 'Inside here, they''re using laser light to mimic the sun''s rays.', '在这里，他们用激光光来模拟太阳光。', '/ɪnsaɪd hɪɹ, ðeɪɚ juːzɪŋ leɪzɚ laɪt tə mɪmɪk ðə sʌnz ɹeɪz./', '<span tid="142483">Inside</span><span tid="142484">here,</span><span>they''re</span><span tid="142486">using</span><span tid="142487" class="highlight highlight-a">laser</span><span tid="142488" class="highlight highlight-a">light</span><span>to</span><span tid="142490" class="highlight highlight-a">mimic</span><span>the</span><span tid="142492">sun''s</span><span tid="142493" class="highlight highlight-a">rays.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 150, 532.278, 537.778, 'It shoots out here and hits a mirror, redirecting it upwards to a bunch of samples made of different materials.', '它从这里射出，打到一面镜子上，被反射到上方一堆不同材料做成的样品。', '/ɪt ʃuːts aʊt hɪɹ ænd hɪts ɐ mɪɹɚ, ɹiːdᵻɹɛktɪŋ ɪɾ ʌpwɚdz tʊ ɐ bʌntʃ ʌv sæmpəlz meɪd ʌv dɪfɹənt mətɪɹiəlz./', '<span>It</span><span tid="142495" class="highlight highlight-a">shoots</span><span tid="142496">out</span><span tid="142497">here</span><span>and</span><span tid="142499" class="highlight highlight-a">hits</span><span>a</span><span tid="142501">mirror,</span><span tid="142502">redirecting</span><span>it</span><span tid="142504">upwards</span><span>to</span><span pid="341" class="highlight highlight-i">a bunch of</span><span tid="142509">samples</span><span tid="142510">made</span><span>of</span><span tid="142512">different</span><span tid="142513" class="highlight highlight-a">materials.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 151, 537.778, 542.298, 'So once the laser hits the sample, it''s like... Oh, cool.', '所以当激光打到样品时，就会像这样……哦，酷。', '/soʊ wʌns ðə leɪzɚ hɪts ðə sæmpəl, ɪts laɪk... oʊ, kuːl./', '<span>So</span><span tid="142515" class="highlight highlight-a">once</span><span>the</span><span tid="142517" class="highlight highlight-a">laser</span><span tid="142518" class="highlight highlight-a">hits</span><span>the</span><span tid="142520">sample,</span><span>it''s</span><span>like...</span><span>Oh,</span><span tid="142524" class="highlight highlight-a">cool.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 152, 542.298, 542.918, 'This is the motion.', '这就是运动的效果。', '/ðɪs ɪz ðə moʊʃən./', '<span>This</span><span>is</span><span>the</span><span tid="142528" class="highlight highlight-a">motion.</span>'
