INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 153, 542.918, 545.72, 'Learning how to harness this could be huge.', '学会如何利用这一点可能意义重大。', '/lɜːnɪŋ haʊ tə hɑːɹnɪs ðɪs kʊd biː hjuːdʒ./', '<span tid="142529">Learning</span><span>how</span><span>to</span><span tid="142532" class="highlight highlight-a">harness</span><span>this</span><span>could</span><span>be</span><span tid="142536">huge.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 154, 545.72, 552.678, 'Because the traditional methods that we use to move stuff in space require the spacecraft to carry all of its future fuel with it.', '因为传统的推进方式需要航天器携带所有未来要用的燃料。', '/bɪkʌz ðə tɹɐdɪʃənəl mɛθədz ðæt wiː juːz tə muːv stʌf ɪn speɪs ɹᵻkwaɪɚ ðə speɪskɹæft tə kæɹi ɔːl ʌv ɪts fjuːtʃɚ fjuːəl wɪð ɪt./', '<span>Because</span><span>the</span><span tid="142539">traditional</span><span tid="142540">methods</span><span>that</span><span>we</span><span tid="142543">use</span><span>to</span><span tid="142545">move</span><span tid="142546" class="highlight highlight-a">stuff</span><span>in</span><span tid="142548">space</span><span tid="142549">require</span><span>the</span><span tid="142551" class="highlight highlight-a">spacecraft</span><span>to</span><span tid="142553">carry</span><span>all</span><span>of</span><span>its</span><span tid="142557">future</span><span tid="142558" class="highlight highlight-a">fuel</span><span>with</span><span>it.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 155, 552.678, 554.538, 'And it can only carry so much.', '而它所能携带的是有限的。', '/ænd ɪt kæn oʊnli kæɹi soʊ mʌtʃ./', '<span>And</span><span>it</span><span>can</span><span tid="142564">only</span><span tid="142565">carry</span><span>so</span><span tid="142567">much.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 156, 554.538, 560.98, 'Using light to move things forward could be a fuel -free way to explore the cosmos.', '用光来推动物体前进，可能是一种不依赖燃料的方式去探索宇宙。', '/juːzɪŋ laɪt tə muːv θɪŋz fɔːɹwɚd kʊd biː ɐ fjuːəl fɹiː weɪ tʊ ɛksplɔːɹ ðə kɑːzmoʊs./', '<span tid="142568">Using</span><span tid="142569" class="highlight highlight-a">light</span><span>to</span><span tid="142571">move</span><span tid="142572">things</span><span tid="142573">forward</span><span>could</span><span>be</span><span>a</span><span tid="142577" class="highlight highlight-a">fuel</span><span tid="142578">-free</span><span tid="142579" class="highlight highlight-a">way</span><span>to</span><span tid="142581" class="highlight highlight-a">explore</span><span>the</span><span tid="142583">cosmos.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 157, 560.98, 562.94, 'Huge if true.', '如果是真的，那真是太牛了。', '/hjuːdʒ ɪf tɹuː./', '<span tid="142584">Huge</span><span>if</span><span tid="142586">true.</span>'
