INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 158, 562.94, 563.96, 'How''s it going?', '进展如何？', '/haʊz ɪt ɡoʊɪŋ?/', '<span>How''s</span><span>it</span><span tid="142589">going?</span>'
