INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 159, 563.96, 566.019, 'In this experiment, we''re still comparing.', '在这个实验中，我们还在比较。', '/ɪn ðɪs ɛkspɛɹɪmənt, wɪɹ stɪl kəmpɛɹɪŋ./', '<span>In</span><span>this</span><span tid="142592" class="highlight highlight-a">experiment,</span><span>we''re</span><span tid="142594">still</span><span tid="142595">comparing.</span>'
