INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 161, 567.158, 569.48, 'But our experiments have been successful so far.', '不过到目前为止，我们的实验是成功的。', '/bʌt aʊɚɹ ɛkspɛɹɪmənts hɐvbɪn səksɛsfəl soʊ fɑːɹ./', '<span>But</span><span>our</span><span tid="142603" class="highlight highlight-a">experiments</span><span>have</span><span>been</span><span tid="142606">successful</span><span pid="342" class="highlight highlight-c">so far.</span>'
