INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 162, 569.48, 572.62, 'We''re getting results, getting motion in microgravity.', '我们在微重力环境中获得了结果，得到了运动。', '/wɪɹ ɡɛɾɪŋ ɹɪzʌlts, ɡɛɾɪŋ moʊʃən ɪn maɪkɹoʊɡɹævᵻɾi./', '<span>We''re</span><span tid="142610">getting</span><span tid="142611">results,</span><span tid="142612">getting</span><span tid="142613" class="highlight highlight-a">motion</span><span>in</span><span tid="142615">microgravity.</span>'
