INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 164, 576.32, 579.0, 'Hopefully, we will publish something soon about it.', '希望我们很快能就此发表一些成果。', '/hoʊpfəli, wiː wɪl pʌblɪʃ sʌmθɪŋ suːn ɐbaʊt ɪt./', '<span tid="142630" class="highlight highlight-a">Hopefully,</span><span>we</span><span>will</span><span tid="142633">publish</span><span tid="142634">something</span><span tid="142635">soon</span><span tid="142636">about</span><span>it.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 165, 579.0, 586.558, 'Science like this matters for you and me because we don''t know what we''ll find.', '这样的科学对你我都很重要，因为我们不知道会发现什么。', '/saɪəns laɪk ðɪs mæɾɚz fɔːɹ juː ænd miː bɪkʌz wiː doʊnt noʊ wʌt wiːl faɪnd./', '<span tid="142638">Science</span><span>like</span><span>this</span><span tid="142641">matters</span><span>for</span><span>you</span><span>and</span><span>me</span><span>because</span><span>we</span><span>don''t</span><span tid="142649">know</span><span>what</span><span>we''ll</span><span tid="142652">find.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 166, 586.558, 588.899, 'We don''t know what we''re capable of.', '我们不知道自己有多大的潜能。', '/wiː doʊnt noʊ wʌt wɪɹ keɪpəbəl ʌv./', '<span>We</span><span>don''t</span><span tid="142655">know</span><span>what</span><span>we''re</span><span pid="374" class="highlight highlight-c">capable of.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 167, 588.899, 593.72, 'Smart people are working all the time to learn more and push us just a little bit farther.', '聪明的人们一直在努力学习更多知识，并推动我们一点点向前。', '/smɑːɹt piːpəl ɑːɹ wɜːkɪŋ ɔːl ðə taɪm tə lɜːn mɔːɹ ænd pʊʃ ʌs dʒʌst ɐ lɪɾəl bɪt fɑːɹðɚ./', '<span tid="142660">Smart</span><span tid="142661">people</span><span>are</span><span tid="142663">working</span><span pid="346" class="highlight highlight-c">all the time</span><span>to</span><span tid="142668">learn</span><span tid="142669">more</span><span>and</span><span tid="142671" class="highlight highlight-a">push</span><span>us</span><span>just</span><span>a</span><span tid="142675">little</span><span tid="142676">bit</span><span tid="142677">farther.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 168, 593.72, 598.658, 'And if you want to see that, if you want more optimistic science and tech stories, subscribe.', '如果你想看到这样的内容，想要更多积极的科学和科技故事，记得订阅。', '/ænd ɪf juː wɔnt tə siː ðæt, ɪf juː wɔnt mɔːɹ ɑːptɪmɪstɪk saɪəns ænd tɛk stɔːɹiz, səbskɹaɪb./', '<span>And</span><span>if</span><span>you</span><span tid="142681">want</span><span>to</span><span tid="142683">see</span><span>that,</span><span>if</span><span>you</span><span tid="142687">want</span><span tid="142688">more</span><span tid="142689" class="highlight highlight-a">optimistic</span><span tid="142690">science</span><span>and</span><span tid="142692" class="highlight highlight-a">tech</span><span tid="142693">stories,</span><span tid="142694" class="highlight highlight-a">subscribe.</span>'
FROM episodes e WHERE e.video_id = '081gdiTa7BGapBJ';

