INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 45.96, 51.22, 'It was a gloomy Saturday morning and rain was coming down in buckets.', '那是一个阴沉的星期六早晨，雨下得像盆一样大。', '/ɪt wʌzɐ ɡluːmi sæɾɚdeɪ mɔːɹnɪŋ ænd ɹeɪn wʌz kʌmɪŋ daʊn ɪn bʌkɪts./', '<span>It</span><span>was</span><span>a</span><span tid="67368" class="highlight highlight-a">gloomy</span><span tid="67369">Saturday</span><span tid="67370">morning</span><span>and</span><span tid="67372">rain</span><span>was</span><span tid="67374">coming</span><span tid="67375">down</span><span pid="3028" class="highlight highlight-i">in buckets.</span>'
