INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 65.78, 69.52, 'He was in a jam and his GPS told him he was going to be late.', '他陷入了困境，GPS告诉他他会迟到。', '/hiː wʌz ɪn ɐ dʒæm ænd hɪz dʒiːpiːɛs toʊld hɪm hiː wʌz ɡoʊɪŋ təbi leɪt./', '<span>He</span><span>was</span><span pid="3032" class="highlight highlight-i">in a jam</span><span>and</span><span>his</span><span tid="67433">GPS</span><span tid="67434">told</span><span>him</span><span>he</span><span>was</span><span>going</span><span>to</span><span>be</span><span tid="67441">late.</span>'
