INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 5.12, 'Hey, I''m John Kanell, and today on Preppy Kitchen, we''re making some creamy, dreamy rice pudding.', '嘿，我是John Kanell，今天在Preppy Kitchen，我们要做一款奶香浓郁的米布丁。', '/heɪ, aɪm dʒɑːn keɪnəl, ænd tədeɪ ɔn pɹɛpi kɪtʃən, wɪɹ meɪkɪŋ sʌm kɹiːmi, dɹiːmi ɹaɪs pʊdɪŋ./', '<span>Hey,</span><span>I''m</span><span tid="63701">John</span><span tid="63702">Kanell,</span><span>and</span><span tid="63704">today</span><span>on</span><span tid="63706">Preppy</span><span tid="63707">Kitchen,</span><span>we''re</span><span tid="63709">making</span><span>some</span><span tid="63711" class="highlight highlight-a">creamy,</span><span tid="63712" class="highlight highlight-a">dreamy</span><span pid="3178" class="highlight highlight-c">rice pudding.</span>'
FROM episodes e WHERE e.video_id = '085uUljhj1GkBSK';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
