INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 6.18, 11.58, 'First off, in a large pot, we''re gonna combine four and a half cups of whole milk.', '首先，在一个大锅里，我们将四个半杯全脂牛奶倒入。', '/fɜːst ɔf, ɪn ɐ lɑːɹdʒ pɑːt, wɪɹ ɡənə kəmbaɪn fɔːɹ ænd ɐ hæf kʌps ʌv hoʊl mɪlk./', '<span tid="63719">First</span><span tid="63720">off,</span><span>in</span><span>a</span><span tid="63723">large</span><span tid="63724" class="highlight highlight-a">pot,</span><span>we''re</span><span tid="63726">gonna</span><span tid="63727">combine</span><span>four</span><span>and</span><span>a</span><span tid="63731">half</span><span tid="63732">cups</span><span>of</span><span pid="3183" class="highlight highlight-c">whole milk.</span>'
FROM episodes e WHERE e.video_id = '085uUljhj1GkBSK';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
