INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 13.9, 24.88, 'A quarter cup, or 50 grams, of granulated sugar, and a nice pinch of salt.', '加入四分之一杯，或者50克的细砂糖，还有一小撮盐。', '/ɐ kwɔːɹɾɚ kʌp, ɔːɹ fɪfti ɡɹæmz, ʌv ɡɹænjʊleɪɾᵻd ʃʊɡɚ, ænd ɐ naɪs pɪntʃ ʌv sɔlt./', '<span>A</span><span tid="63740" class="highlight highlight-a">quarter</span><span tid="63741">cup,</span><span>or</span><span>50</span><span tid="63744" class="highlight highlight-a">grams,</span><span>of</span><span pid="3185" class="highlight highlight-c">granulated sugar,</span><span>and</span><span>a</span><span tid="63750">nice</span><span tid="63751" class="highlight highlight-a">pinch</span><span>of</span><span tid="63753">salt.</span>'
