INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 27.74, 33.04, 'Imagine your favorite company is like a chocolate cake cut into thousands or even millions of slices.', '假设你最喜欢的公司就像一块巧克力蛋糕，切成成千上万甚至数百万片。', '/ɪmædʒɪn jʊɹ feɪvɚɹᵻt kʌmpəni ɪz laɪk ɐ tʃɑːklət keɪk kʌt ɪntʊ θaʊzəndz ɔːɹ iːvən mɪliənz ʌv slaɪsᵻz./', '<span tid="61232" class="highlight highlight-a">Imagine</span><span>your</span><span tid="61234">favorite</span><span tid="61235">company</span><span>is</span><span>like</span><span>a</span><span tid="61239" class="highlight highlight-a">chocolate</span><span tid="61240">cake</span><span tid="61241" class="highlight highlight-a">cut</span><span tid="61242" class="highlight highlight-a">into</span><span tid="61243">thousands</span><span>or</span><span tid="61245">even</span><span tid="61246">millions</span><span>of</span><span tid="61248" class="highlight highlight-a">slices.</span>'
