INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 10, 33.04, 36.5, 'Each slice is what we call a share.', '每一片就是我们所说的股票份额。', '/iːtʃ slaɪs ɪz wʌt wiː kɔːl ɐ ʃɛɹ./', '<span tid="61249">Each</span><span tid="61250" class="highlight highlight-a">slice</span><span>is</span><span>what</span><span>we</span><span tid="61254">call</span><span>a</span><span tid="61256" class="highlight highlight-a">share.</span>'
