INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 36.5, 42.02, 'When you buy a share, you''re basically saying, I''ll take that slice of the company, please.', '当你购买一份股票时，你基本上是在说：“我想要这家公司的一片。”', '/wɛn juː baɪ ɐ ʃɛɹ, jʊɹ beɪsɪkli seɪɪŋ, aɪl teɪk ðæt slaɪs ʌvðə kʌmpəni, pliːz./', '<span>When</span><span>you</span><span tid="61259">buy</span><span>a</span><span tid="61261" class="highlight highlight-a">share,</span><span>you''re</span><span tid="61263" class="highlight highlight-a">basically</span><span tid="61264">saying,</span><span>I''ll</span><span tid="61266">take</span><span>that</span><span tid="61268" class="highlight highlight-a">slice</span><span>of</span><span>the</span><span tid="61271">company,</span><span tid="61272">please.</span>'
