INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 46.8, 50.56, 'and you owned five of those shares, you''d actually own half of that company.', '而你拥有其中5份股票，那你就拥有了这家公司的一半。', '/ænd juː oʊnd faɪv ʌv ðoʊz ʃɛɹz, juːd æktʃuːəli oʊn hæf ʌv ðæt kʌmpəni./', '<span>and</span><span>you</span><span tid="61288" class="highlight highlight-a">owned</span><span>five</span><span>of</span><span>those</span><span tid="61292" class="highlight highlight-a">shares,</span><span>you''d</span><span tid="61294">actually</span><span tid="61295" class="highlight highlight-a">own</span><span tid="61296">half</span><span>of</span><span>that</span><span tid="61299">company.</span>'
