INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 100, 386.18, 388.92, 'The stock market can be a wild rollercoaster ride.', '股市可以是一场疯狂的过山车之旅。', '/ðə stɑːk mɑːɹkɪt kæn biː ɐ waɪld ɹoʊlɚkoʊstɚ ɹaɪd./', '<span>The</span><span tid="62205" class="highlight highlight-a">stock</span><span tid="62206">market</span><span>can</span><span>be</span><span>a</span><span tid="62210" class="highlight highlight-a">wild</span><span tid="62211" class="highlight highlight-a">rollercoaster</span><span tid="62212" class="highlight highlight-a">ride.</span>'
FROM episodes e WHERE e.video_id = '087Zyaj85dXFEUQ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 101, 388.92, 394.14, 'Some people invest in stocks for the long term, hoping the companies grow over many years.', '有些人投资股票是为了长期持有，希望公司多年后能成长。', '/sʌm piːpəl ɪnvɛst ɪn stɑːks fɚðə lɔŋ tɜːm, hoʊpɪŋ ðə kʌmpəniz ɡɹoʊ oʊvɚ mɛni jɪɹz./', '<span>Some</span><span tid="62214">people</span><span tid="62215" class="highlight highlight-a">invest</span><span>in</span><span tid="62217" class="highlight highlight-a">stocks</span><span pid="3067" class="highlight highlight-c">for the long term,</span><span tid="62222">hoping</span><span>the</span><span tid="62224">companies</span><span tid="62225">grow</span><span tid="62226">over</span><span>many</span><span tid="62228">years.</span>'
