INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 105, 403.62, 404.78, 'Stocks in a nutshell.', '简明概述股票。', '/stɑːks ɪn ɐ nʌtʃɛl./', '<span tid="62254" class="highlight highlight-a">Stocks</span><span pid="3068" class="highlight highlight-f">in a nutshell.</span>'
