INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 107, 410.02, 412.62, 'you''re buying actual ownership in a real business.', '你是在购买一个真正的企业的所有权。', '/jʊɹ baɪɪŋ æktʃuːəl oʊnɚʃɪp ɪn ɐ ɹiːəl bɪznəs./', '<span>you''re</span><span tid="62279">buying</span><span tid="62280">actual</span><span tid="62281" class="highlight highlight-a">ownership</span><span>in</span><span>a</span><span tid="62284">real</span><span tid="62285">business.</span>'
