INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 108, 412.62, 419.8, 'If you''re thinking about investing, start with companies you understand and believe in and don''t put all your money in one stock.', '如果你考虑投资，先从你了解并相信的公司开始，并且不要把所有的钱都投入到一只股票里。', '/ɪf jʊɹ θɪŋkɪŋ ɐbaʊt ɪnvɛstɪŋ, stɑːɹt wɪð kʌmpəniz juː ʌndɚstænd ænd bᵻliːv ɪn ænd doʊnt pʊt ɔːl jʊɹ mʌni ɪn wʌn stɑːk./', '<span>If</span><span>you''re</span><span>thinking</span><span>about</span><span tid="62290" class="highlight highlight-a">investing,</span><span tid="62291">start</span><span>with</span><span tid="62293">companies</span><span>you</span><span tid="62295">understand</span><span>and</span><span tid="62297">believe</span><span>in</span><span>and</span><span>don''t</span><span tid="62301">put</span><span>all</span><span>your</span><span tid="62304">money</span><span>in</span><span>one</span><span tid="62307" class="highlight highlight-a">stock.</span>'
