INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 111, 423.76, 430.82, 'If you found this helpful, hit that like button and subscribe for more videos breaking down financial concepts into simple terms.', '如果你觉得这有帮助，点击点赞按钮并订阅，获取更多将财务概念简单化的视频。', '/ɪf juː faʊnd ðɪs hɛlpfəl, hɪt ðæt laɪk bʌʔn̩ ænd səbskɹaɪb fɔːɹ mɔːɹ vɪdɪoʊz bɹeɪkɪŋ daʊn faɪnænʃəl kɑːnsɛpts ɪntʊ sɪmpəl tɜːmz./', '<span>If</span><span>you</span><span tid="62322">found</span><span>this</span><span tid="62324" class="highlight highlight-a">helpful,</span><span tid="62325" class="highlight highlight-a">hit</span><span>that</span><span>like</span><span tid="62328" class="highlight highlight-a">button</span><span>and</span><span tid="62330" class="highlight highlight-a">subscribe</span><span>for</span><span>more</span><span tid="62333">videos</span><span tid="62334">breaking</span><span tid="62335">down</span><span tid="62336">financial</span><span tid="62337" class="highlight highlight-a">concepts</span><span tid="62338" class="highlight highlight-a">into</span><span tid="62339">simple</span><span tid="62340" class="highlight highlight-a">terms.</span>'
