INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 80, 516.76, 520.92, 'So I''m going home tomorrow and I wish I wasn''t going home.', '我明天就要回家了，真希望不用回去。', '/soʊ aɪm ɡoʊɪŋ hoʊm təmɑːɹoʊ ænd aɪ wɪʃ aɪ wʌzn̩t ɡoʊɪŋ hoʊm./', '<span>So</span><span>I''m</span><span>going</span><span tid="60961">home</span><span tid="60962">tomorrow</span><span>and</span><span>I</span><span tid="60965">wish</span><span>I</span><span tid="60967">wasn''t</span><span>going</span><span tid="60969">home.</span>'
