INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 81, 520.92, 524.56, 'I wish I was going to another country, but life happens.', '真希望是要去另一个国家，不过生活嘛，总得继续。', '/aɪ wɪʃ aɪ wʌz ɡoʊɪŋ tʊ ɐnʌðɚ kʌntɹi, bʌt laɪf hæpənz./', '<span>I</span><span tid="60971">wish</span><span>I</span><span>was</span><span>going</span><span>to</span><span tid="60976">another</span><span tid="60977">country,</span><span>but</span><span tid="60979">life</span><span tid="60980">happens.</span>'
