INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 83.3, 86.88, 'Instead of mating dogs to emphasize their function.', '那时人们不再只是为了实用功能去配种。', '/ɪnstɛd ʌv meɪɾɪŋ dɑːɡz tʊ ɛmfɐsaɪz ðɛɹ fʌŋkʃən./', '<span tid="59725" class="highlight highlight-a">Instead</span><span>of</span><span tid="59727">mating</span><span tid="59728">dogs</span><span>to</span><span tid="59730" class="highlight highlight-a">emphasize</span><span>their</span><span tid="59732" class="highlight highlight-a">function.</span>'
FROM episodes e WHERE e.video_id = '08926MxSFLl0gZH';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 86.88, 94.38, 'people selectively inbred dogs to achieve particular features and established overarching breed standards.', '而是为了获得特定外观特征进行近亲繁殖，并确立了统一的犬种标准。', '/piːpəl sᵻlɛktɪvli ɪnbɹɛd dɑːɡz tʊ ɐtʃiːv pɚtɪkjʊlɚ fiːtʃɚz ænd ɪstæblɪʃt oʊvɚɹɑːɹtʃɪŋ bɹiːd stændɚdz./', '<span tid="59733">people</span><span tid="59734" class="highlight highlight-a">selectively</span><span tid="59735">inbred</span><span tid="59736">dogs</span><span>to</span><span tid="59738" class="highlight highlight-a">achieve</span><span tid="59739" class="highlight highlight-a">particular</span><span tid="59740" class="highlight highlight-a">features</span><span>and</span><span tid="59742">established</span><span tid="59743">overarching</span><span tid="59744" class="highlight highlight-a">breed</span><span tid="59745" class="highlight highlight-a">standards.</span>'
FROM episodes e WHERE e.video_id = '08926MxSFLl0gZH';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 94.38, 102.24, 'But while maintaining specific lines of inheritance and characteristics is important to kennel clubs, breed genetics are complex.', '不过，虽然犬舍协会非常重视保持特定的血统和特征，但犬种的基因其实很复杂。', '/bʌt waɪl meɪnteɪnɪŋ spəsɪfɪk laɪnz ʌv ɪnhɛɹɪtəns ænd kæɹɪktɚɹɪstɪks ɪz ɪmpɔːɹtənt tə kɛnəl klʌbz, bɹiːd dʒɪnɛɾɪks ɑːɹ kɑːmplɛks./', '<span>But</span><span tid="59747">while</span><span tid="59748" class="highlight highlight-a">maintaining</span><span tid="59749" class="highlight highlight-a">specific</span><span tid="59750">lines</span><span>of</span><span tid="59752" class="highlight highlight-a">inheritance</span><span>and</span><span tid="59754" class="highlight highlight-a">characteristics</span><span>is</span><span tid="59756">important</span><span>to</span><span tid="59758" class="highlight highlight-a">kennel</span><span tid="59759">clubs,</span><span tid="59760" class="highlight highlight-a">breed</span><span tid="59761" class="highlight highlight-a">genetics</span><span>are</span><span tid="59763" class="highlight highlight-a">complex.</span>'
