INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 17, 102.24, 106.86, 'In one study, where scientists sequenced the genomes of different dog breeds.', '在一项科学家对不同犬种基因组进行测序的研究中，', '/ɪn wʌn stʌdi, wɛɹ saɪəntɪsts siːkwənst ðə dʒiːnoʊmz ʌv dɪfɹənt dɑːɡ bɹiːdz./', '<span>In</span><span>one</span><span tid="59766">study,</span><span>where</span><span tid="59768">scientists</span><span tid="59769" class="highlight highlight-a">sequenced</span><span>the</span><span tid="59771" class="highlight highlight-a">genomes</span><span>of</span><span tid="59773">different</span><span tid="59774">dog</span><span tid="59775" class="highlight highlight-a">breeds.</span>'
