INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 106.86, 112.9, 'ten major groups emerged that roughly aligned with the lineage''s historic working role.', '出现了十个主要的分支，大致对应它们历史上的工作类型。', '/tɛn meɪdʒɚ ɡɹuːps ɪmɜːdʒd ðæt ɹʌfli ɐlaɪnd wɪððə lɪnɪɪdʒᵻz hɪstɔːɹɪk wɜːkɪŋ ɹoʊl./', '<span>ten</span><span tid="59777">major</span><span tid="59778">groups</span><span tid="59779" class="highlight highlight-a">emerged</span><span>that</span><span tid="59781">roughly</span><span pid="2696" class="highlight highlight-c">aligned with</span><span>the</span><span tid="59785" class="highlight highlight-a">lineage''s</span><span tid="59786" class="highlight highlight-a">historic</span><span tid="59787">working</span><span tid="59788">role.</span>'
