INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 112.9, 117.12, 'from pointing and flushing to scent tracking and retrieving.', '从指示、驱赶，到嗅觉追踪和拾回猎物。', '/fɹʌm pɔɪntɪŋ ænd flʌʃɪŋ tə sɛnt tɹækɪŋ ænd ɹᵻtɹiːvɪŋ./', '<span>from</span><span tid="59790">pointing</span><span>and</span><span tid="59792" class="highlight highlight-a">flushing</span><span>to</span><span tid="59794" class="highlight highlight-a">scent</span><span tid="59795">tracking</span><span>and</span><span tid="59797" class="highlight highlight-a">retrieving.</span>'
