INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 50, 292.7, 300.2, 'Or find out what''s behind that peculiar urge you have to squeeze and smush adorable creatures with this one.', '或者看看这支视频，了解为什么我们会想要去捏那些可爱的动物。', '/ɔːɹ faɪnd aʊt wʌts bᵻhaɪnd ðæt pɪkjuːlɪɹ ɜːdʒ juː hæv tə skwiːz ænd smʌʃ ɐdɔːɹəbəl kɹiːtʃɚz wɪð ðɪswʌn./', '<span>Or</span><span tid="60212">find</span><span tid="60213">out</span><span>what''s</span><span tid="60215">behind</span><span>that</span><span tid="60217" class="highlight highlight-a">peculiar</span><span tid="60218" class="highlight highlight-a">urge</span><span>you</span><span>have</span><span>to</span><span tid="60222" class="highlight highlight-a">squeeze</span><span>and</span><span tid="60224">smush</span><span tid="60225" class="highlight highlight-a">adorable</span><span tid="60226" class="highlight highlight-a">creatures</span><span>with</span><span>this</span><span>one.</span>'
